window.__D("text/torat-chaim/c018",{"p":[[2300540138,"דוקא, וע\"כ נק' אספקלריא דלא נהרא מעצמה רק מכח המאיר על מדה זו מלמעלה דהיינו מח\"ע ומדות שברצה\"ע דכ\"ע כמ\"ש דכתר מל' איהו כ\"ע<sup data-n=\"4619\">26</sup> כו'. וזהו כמו הלבנה דלית לה אור מעצמה כ\"א מה שמקבלת משמש כך שמש הוא אור אבא<sup data-n=\"4620\">27</sup> בז\"א שנק' שמשא<sup data-n=\"4621\">28</sup> כידוע בזהר ומאיר למל' שנק' לבנה<sup data-n=\"4622\">29</sup> ואז נעשה המל' כתר לבי\"ע בבחי' מלך על עם כנ\"ל וד\"ל.\n<b>והפי'</b> הב' במה שאמר דלית לה מגרמה כלום כ\"א מה שמקבל מלמטה למעלה גם זה אמת, דהנה אנו רואים שיש במדה זאת דהתנשאות שנתעוררה בלב מצד העלאה מ[ל]מטה למעלה דוקא, וכמו המלך ושר גדול שבלתי התעוררות מאנשי המדינה שמעלים רצון שלהם בביטול גדול לקבלו למלך לא יתעורר בעצמו בבחי' ההתנשאות ואף לא ברצון לזה כלל, וכל שמתעוררי' מלמטה יותר, יותר יתעורר ברצון בהתנשאות זאת והוא כתר מלוכה שמכתירים אותו מאנשים ועבדים הנאמנים, ואם אין עם אין מלך ואין מלך בלא עם<sup data-n=\"4623\">30</sup> כידוע, ונמצא שכתר מל' זה נעשה מלמטה למעלה דוקא שמן העם ועבדים עיקר הסיבה [לבחי' ה]התנשאות של המל'. וכמו\"כ במלאכים עליונים דבי\"ע שמעלים מ\"ן בתשוקה גדולה לקבל עליהם עומ\"ש באהוי\"ר וכמו שאו' וכולם מקבלים<sup data-n=\"4624\">31</sup> עליהם עומ\"ש כו'. וזהו שאומרים בקדושה דמוסף כתר יתנו לך מלאכים כו' ועמך ישראל קבוצי מטה<sup data-n=\"4625\">*32</sup> בקבלת עומ\"ש בתומ\"צ שהוא פנימיות כתר המל' יותר ונק' הדר מלכותו<sup data-n=\"4626\">32</sup> (כמ\"ש במ\"א) (והוא מה שאו'<sup data-n=\"4627\">33</sup> אמרו לפני מלכיות<sup data-n=\"4628\">34</sup> שתמליכונ\"י עליכ\"ם [דוקא] שאומרים י\"פ דמלכיות בר\"ה כדי שתמליכוני עליכם<sup data-n=\"4629\">35</sup> ואח\"כ יהי' מלך לעולם [כו']). ולפי\"ז מה שהמל' נק' אספקלריא דלא נהרא מצד עצמה היינו רק מחמת העלאת מ\"ן מלמטה דוקא (וזהו כמו המלך ואדון ושר שהכל משפיעים לו ונותנים לו כל צרכו בכבוד גדול עד להעשירו עושר גדול ובכח זה מתגדל ומתרומם ומושל עליהם דוקא שנמצא שהוא מקבל מן הכל ואח\"כ נק' מלך ושר לנהוג אותם בחן ו[ב]חסד וכרועה צאן כו' להשפיע להם מרב טובו ולהגן עליהם מכל אויב כו').\n<b>ונמצא</b> מובן מכ\"ז דב' הפירושי' במה שא' דמל' לית לה מג\"כ אמת שמקבלת מלמעלה למטה ומלמטלמ\"ע לחדש האור דרצון וחכ' ומדות דמל' ואינם סותרים זא\"ז כלל (וזהו שא' בזהר דהמל' נק' אבן ספי\"ר<sup data-n=\"4630\">36</sup> דגוונין דספיר כו' לפי אופן",[["4619","26","<b>דכתר מל' איהו כ\"ע</b>: ב: דכתר עליון איהו כתר מל' — ת\"ז בהקדמה (יז, א). ראה גם לקמן קא, ב."],["4620","27","<b>שמש הוא אור אבא</b>: ראה ביאוה\"ז ויצא טז, רע\"ד. יז, ג. ש\"א ד, ב. מאמרי אדה\"א ויקרא ח\"א ע' כט."],["4621","28","<b>בז\"א שנק' שמשא</b>: ע\"ח (שער לידת המוחין) שכ\"א, פ\"ב."],["4622","29","<b>למל' שנק' לבנה</b>: ראה פרדס (שעה\"כ) שכ\"ג, מערכת לבנה."],["4623","30","<b>ואין מלך בלא עם</b>: נסמן לעיל עה, ב."],["4624","31","<b>וכמו שאו' וכולם מקבלים</b>: בברכת יוצר."],["4625","*32","<b>כתר. . ועמך ישראל קבוצי מטה</b>: ראה גם מאמרי אדה\"ז על מארז\"ל ע' תפז וע' תפט. לקמן קא, ב."],["4626","32","<b>הדר מלכותו</b>: תהלים קמה, יב. ראה מאמרי אדה\"ז תקס\"ו ע' שסח. מאמרי אדה\"א שמות ח\"א ע' נא. וש\"נ. ח\"ב ע' תרעו. וראה גם שם ע' שמט."],["4627","33","<b>שאו'</b>: אב: שאומרים י\"פ דמלכיות בר\"ה שא'."],["4628","34","<b>אמרו לפני מלכיות</b>: ר\"ה טז, סע\"א. לד, ב."],["4629","35","<b>שאומרים. . עליכם</b>: אב: ליתא. וראה לעיל הערה 33."],["4630","36","<b>דהמל' נק' אבן ספי\"ר</b>: נסמן לעיל צד, ג."]]],[2300540175,"העלאה מלמטה או לפי אופן המשכת האור מלמעלה כו' וד\"ל). אלא שההפרש הוא בחי' העלאת מ\"ן דעולמות שמחדשים כת\"ר למל' שיחזור הארת<sup data-n=\"4631\">37</sup> אור האצי' בבי\"ע להיות מל' כ\"ע<sup data-n=\"4632\">38</sup> דהיינו מה שכבר נתצמצם בלבוש מל' שלא יסתלק כו' [שנק' ע\"י דבריאה (כמשי\"ת)], אבל המשכה דכ\"ע וחו\"ב ומדות דאצי' למל' הוא בחי' השפעה חדשה לחדש מקור ושרש דמ\"ד<sup data-n=\"4633\">39</sup> המל' כמו שהיא בבחי' האצי' <span data-k=\"pg\">372</span> ּ שיומשך משם רצון מחדש במל' להיות כתר לנבראים כמו בר\"ה וכה\"ג שזהו עיקר בנין המל' כידוע. וזהו פי' האמיתי יותר במה שא' דהמל' לית לה מגרמה כלום דהיינו דלית לה אור עצמי'<sup data-n=\"4634\">40</sup> להיות ראש ומקור להשפיע לעולמות מאין ליש בלתי שתקבל הארה בעצמה תחלה מן המשפיע שהוא מדות דחכ'<sup data-n=\"4635\">41</sup> דאד\"ם העליון דאצי' וכנ\"ל. וזהו כמו הלבנה שלא תאיר עצם<sup data-n=\"4636\">42</sup> הארתה על הארץ אם לא שקיבלה אור השמש בקירובה תחלה ואח\"כ בריחוק מקום תאיר אור לארץ (והוא אור השמש ולא אור עצמה וי\"א שהוא אור עצמה<sup data-n=\"4637\">43</sup> דוקא וכאשה כי תזריע<sup data-n=\"4638\">44</sup> כו' כמ\"ש במ\"א). וכמו\"כ בענין סיבת ההתנשאו' דמל' להיות מלך על עם זהו בא מלמעלה דוקא ולא מלמטה (ואע\"פ שמעוררי' רצון למל' מלמטה זהו התעוררות לבד ולא שיחודש האור בעצם אור המדה הזאת רק מה שמקבלת מלמעלה כנ\"ל וד\"ל).\n[ב] <b>אך</b> לפי המבואר ממשל מלך כו'<sup data-n=\"4639\">45</sup> שיכתירו אותו אנשי המדינה וכן ממה שיעשירו אותו ברוממות וגדולה שכ\"ז הוא בחי' מקבל מלמטה דוקא ואיך יובן כמו זה במל' דרקיעא, שאיך יוכל להיות התעוררות רצון למל' דלעילא להיות מלך על עם נפרד מאתעדל\"ת דמלאכים ונשמות דבי\"ע שהן ב\"ג שאין ערוך כלל אליו, וגם מה שמהם וע\"י ביטול היש לאין עי\"ז דוקא משפיע<sup data-n=\"4640\">46</sup> אורות במל' שמזה נעשה בחי' מלך כו'. אמנם ההכרח לומר כן דמצינו [ב]כתובים רבים כן כמו שישעי' ראה ה' צבאות<sup data-n=\"4641\">47</sup> יושב על כסא רם ונשא כו' ושרפים עומדים ממעל לו שש כנפיים לא' כו' ואו' קדוש<sup data-n=\"4642\">48</sup> כו', והיינו בחי' כת\"ר מל' דבריאה בכת\"ר מל' ע\"כ<sup data-n=\"4643\">49</sup> רם כו' ושרפים דעולם הבריאה<sup data-n=\"4644\">50</sup> או' קדוש הוי' צבאות וכמו\"כ יחזקאל ראה מרכבה דיצי' באופנים<sup data-n=\"4645\">51</sup> וחיוה\"ק כו' שהוא כתר מל' דיצי' כו' וזכרי' ראה מרכבה דעשי' ששם מאיר כתר מל' דעשי' (וגם בדורות האחרונים כר\"י כה\"ג",[["4631","37","<b>הארת</b>: אב: ליתא."],["4632","38","<b>כ\"ע</b>: כתר עליון."],["4633","39","<b>דמ\"ד</b>: אב: דמדת."],["4634","40","<b>עצמי'</b>: א: עצמות. ב: עצמו. ד: עצמה."],["4635","41","<b>דחכ'</b>: אב: וחכ'."],["4636","42","<b>עצם</b>: אב: ליתא."],["4637","43","<b>אור השמש. . אור עצמה</b>: ראה מאמרי אדה\"א דברים ח\"ג ע' תתפג. קונטרסים ע' רו ובהנסמן בהנ\"ל."],["4638","44","<b>וכאשה כי תזריע</b>: נסמן לעיל פ' שמות ט, ג."],["4639","45","<b>כו'</b>: אב: ב\"ו בשר ודם."],["4640","46","<b>משפיע</b>: אב: מוסיפי'."],["4641","47","<b>שישעי' ראה ה' צבאות</b>: נסמן לעיל פ' וארא פו, ב."],["4642","48","<b>שישעי' ראה. . ושרפים. . ואו' קדוש</b>: ישעי' ו, א-ג."],["4643","49","<b>ע\"כ</b>: אב: על כסא."],["4644","50","<b>ושרפים דעולם הבריאה</b>: ראה לקו\"ת להאריז\"ל ישעי' שם. מאמרי אדה\"א דברים ח\"א ע' רסג. וש\"נ. שע\"ת סב, א הערה 10."],["4645","51","<b>דיצי' באופנים</b>: ראה גם לקמן פ' תצוה שמ, ג. שמט, ב. ויקהל תכט, א. לקו\"ת במדבר ד, ב. מאמרי אדה\"א קונטרסים ע' רפג. וש\"ג. תו\"ח מקץ ריז, ג. וראה גם עט\"ר מא, א."]]],[2300540212,"שראה כת\"ר מל' דעשי'<sup data-n=\"4646\">52</sup> בהיכל ק\"ק וא' ישמעאל בני ברכני<sup data-n=\"4647\">53</sup> כו'). והענין הוא לפי שהארה זאת דמל' דאצי' שנעשה כתר ועתיק לבריאה הוא בא ע\"י צמצום המסך בהארה דהארה לבד שעי\"ז יתהווה מאין ליש משם אלקי' ושם אד' כו' כמ\"ש אד' ב\"ם<sup data-n=\"4648\">54</sup> כו', ע\"כ יוכל להיות גם זה שבהעלאת מ\"ן שלהם בשירה ובמה שאו' קדוש כו' שיעוררו אתעדל\"ע דמל' דאצי' שיחזור להאיר דרך מסך להיות כתר מל' לבריאה וכן ממל' דבריאה שנעשה כתר ליצי' ע\"י מסך וכן מיצי' לעשי' וכידוע ומבואר במ\"א וד\"ל). אך הנה כ\"ז הוא האור ושפע האלקי שנמשך ומאיר ממל' דאצי' בבי\"ע למלאכים עליונים<sup data-n=\"4649\">55</sup> כמרכב' דבריאה ויצי' כו', אבל בחי' גילוי שכינה בנשמות כמו בנשמות הנביאים כישעי' ויחזקאל וכה\"ג אע\"פ שא' בבחי' הנבואה דנביאי' הן<sup data-n=\"4650\">56</sup> במראה אליו אתוודע כו' וכן א' וביד הנביאים אדמ\"ה<sup data-n=\"4651\">57</sup> כו' כמו בחלום וחזיונות הלילה כידוע, עכ\"ז הרי אור המל' דאצי' מאיר ומלובש בהם בתוך תוכם כמו שהוא בבחי' האצי' ממש שלא ע\"י צמצום דמסכים הנ\"ל כלל, שהרי מראה הנבואה הי' בדבר ה' ממש שבא בגילוי גמור בפי הנביא (וע\"כ נק' נביא לשון ניב שפתים<sup data-n=\"4652\">58</sup> ) בקול ודיבור שלו, שהי' מאיר בזה האור אלקי<sup data-n=\"4653\">59</sup> דאצי' ממש, וע\"כ העובר ע\"ד הנביא<sup data-n=\"4654\">60</sup> כעובר ע\"ד ה' ממש כידוע, ולזאת הי' הנביא מופשט מכל גשמיות גופו<sup data-n=\"4655\">61</sup> בשעה זו שדבר ה' דבר בו <span data-k=\"pg\">קפו</span> ּ מאליו מתוך גרונו כו'. ואע\"פ שישעי' ראה הנבואה שלו רק במראה דמות כבוד הוי' יושב על כסא רם כו' שזהו מל' דאצי' [ש]נעשה כתר לבריאה כו' כנ\"ל, אבל לא הי' ע\"י מסך ולבוש כלל כמו לשרפי' כו'. ורק<sup data-n=\"4656\">62</sup> יחזקאל במרכבה דיצי' דכתיב ועל ראשי החיות<sup data-n=\"4657\">63</sup> רקיע כעין הקרח הנורא כו' נתגלה לו מאור העצמות דמל' דאצי' שמלובש ביצי'. ומה שא'<sup data-n=\"4658\">64</sup> בע\"ח בשרש נבואת ישעי' שהי' רק בבחי' נו\"ה דז\"א דבריאה<sup data-n=\"4659\">65</sup> ונבואת יחזקאל בנו\"ה דז\"א דיצי'<sup data-n=\"4660\">66</sup> כו', היינו בעצמות האור דז\"א דאצי' ולא כמו שז\"א מקנן ביצי'<sup data-n=\"4661\">67</sup> ואור אימא מקננת בבריאה<sup data-n=\"4662\">68</sup> אלא אור העצמות כמו שהוא בזו\"נ דאצי' מאירים בנשמות דנביאים הללו הגם ששרשם בבריאה או יצי' כו' והיינו ע\"י נו\"ה דז\"א דבריאה ויצי' שבהן מאיר אור דנו\"ה דז\"א דאצי' ממש כו' (וזהו שנק' השגת המהות ולא השגת המציאות בלבד כמשי\"ת), וראי' לזה ממה שא' הנביא ואשמע אחרי<sup data-n=\"4663\">69</sup> קול רעש כו' אחר\"י דוקא כו'",[["4646","52","<b>כר\"י כה\"ג שראה כת\"ר מל' דעשי'</b>: ראה גם לקמן צט, ג. פ' ויקהל שפו, ד. מאמרי אדה\"ז אתהלך לאזניא ע' ע. ענינים ע' שפב. מאמרי אדה\"א בראשית ע' כה. וש\"נ. הנחות תקע\"ז כאן (ע' כג)."],["4647","53","<b>ישמעאל בני ברכני</b>: ברכות ז, א."],["4648","54","<b>אד' ב\"ם</b>: תהלים סח, יח."],["4649","55","<b>עליונים</b>: אב: ליתא."],["4650","56","<b>הן</b>: כ\"ה באב. וכנראה שבתו\"ח כאן כתוב ה'."],["4651","57","<b>וביד הנביאים אדמ\"ה</b>: הושע יב, יא. ראה שעה\"י קלז, ב."],["4652","58","<b>נביא לשון ניב שפתים</b>: נסמן לעיל פ' וארא נט, א."],["4653","59","<b>בקול ודיבור שלו. . האור אלקי</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקצא ובהנסמן לשם."],["4654","60","<b>העובר ע\"ד הנביא</b>: ראה גם לקמן קיד, ג. וש\"נ."],["4655","61","<b>הנביא מופשט מכל גשמיות גופו</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ז, ה\"ב. ה\"ו. קו\"א לתניא קנו, א ובהנסמן במ\"מ לשם. לקמן פ' בשלח קצד, ג."],["4656","62","<b>ורק</b>: אב: וכן."],["4657","63","<b>ועל ראשי החיות</b>: יחזקאל א, כב [ושם: ודמות על ראשי החי' — ראה לקמן קיט, ד. פ' תרומה שו, ג. שז, ד. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תערה־ לשע\"ת צב, א הערה 12]."],["4658","64","<b>ומה שא'</b>: אב: ומ\"ש."],["4659","65","<b>נבואת ישעי'. . נו\"ה דז\"א דבריאה</b>: נסמן לקמן קיד, ג."],["4660","66","<b>ונבואת יחזקאל בנו\"ה דז\"א דיצי'</b>: נסמן לקמן קיד, ג."],["4661","67","<b>שז\"א מקנן ביצי'</b>: נסמן לעיל פ' שמות טו, ג."],["4662","68","<b>ואור אימא מקננת בבריאה</b>: נסמן לעיל ה, ד."],["4663","69","<b>ואשמע אחרי</b>: יחזקאל ג, יב. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקצה. במדבר ח\"ב ע' תתנט."]]],[2300540244,"(כמ\"ש במ\"א) <b>.</b> ואמנם נבוא[ה] דמשה הי' למעלה מנבואת כל הנביאי' והוא מה שא' דמשה נתנבא בז\"ה<sup data-n=\"4664\">70</sup> וכל הנביאים בכ\"ה בבחי' המל'<sup data-n=\"4665\">71</sup> שנק' מראה דמות כו' כידוע, וכמ\"ש בס' הקבלה בשרש נבואה דמשה שהי' בפנימי' דאור אבא<sup data-n=\"4666\">72</sup> דאצי' ועכ\"ז הוצרך להיות התלבשות דאור אבא דאצי' בבחי' נו\"ה דז\"א<sup data-n=\"4667\">73</sup> דאצי' (שהן ענין ב' הכרובים<sup data-n=\"4668\">74</sup> שהי' הקול מדבר אליו<sup data-n=\"4669\">75</sup> כו' (כמ\"ש בפ' תרומה<sup data-n=\"4670\">76</sup> ) שזהו בבחי' התלבשות דיסוד אבא ביסוד ז\"א כו'), וגם זאת לא הי' בגילוי גמור בפנימיות רק בחיצוניות ואחוריים דנו\"ה כו' כמ\"ש וראית את אחורי<sup data-n=\"4671\">77</sup> ופני לא יראו כו' (ובאמת זה סותר למ\"ש ולא קם נביא עוד כו' אשר ידעו ה' פא\"פ<sup data-n=\"4672\">78</sup> כו').\n[ג<sup data-n=\"4673\">*79</sup> ] והנה מעתה יש להבין ענין א' שהוא נפלא ביותר והוא מאחר שכל הנביאים אף הם לא ראו במראה הנבואה רק בבחי' התלבשות דאור המל' דאצי' בנו\"ה דבריאה ויצי' ולא למעלה מבחי' מל' דאצי' עכ\"פ כנ\"ל, ואף גם משה שהי' רבן של כל הנביאים<sup data-n=\"4674\">79</sup> כנ\"ל לא הי' שרש נבואתו רק בנו\"ה דאצי' בחיצוניות שבו ואף שהי' מלובש בזה מפנימי' אור אבא כנ\"ל, וא\"כ למה אנו מוצאי' שהיו נשמות צדיקים בדורות האחרוני' אחר החורבן דב\"ש כר\"ע ורשב\"י שהשיגו ודברו במדרגות האורות העליונים דע\"ס דאצי', והגבה למעלה גם מעולם האצי' כמו בכתר דא\"ק וע\"י עד מל' דא\"ס בטה\"ע וטה\"ת ולמעלה יותר בעצמות אוא\"ס ממש, כמובן מתוך דברי המקובלים האחרונים המפרשי' מא' הזהר באד\"ר ואדר\"ז שדברו בפרצופי' דאו\"א וא\"א וע\"י וא\"ק עד רום המעלות, וידוע דגם שנשמות גבוהות היו מאד והשיגו כל אלה ברוה\"ק וג\"א<sup data-n=\"4675\">80</sup> (כמו ר\"ח שא' באד\"ר אסתכלנא<sup data-n=\"4676\">81</sup> כו' אף<sup data-n=\"4677\">82</sup> רשב\"י נושא עון חמית כו'), הרי גם בחי' רוה\"ק וג\"א יש בהן מדרגות זו למעלה מזו בעולמות העליונים והעליון מכולם אינו אלא ביצי' ובריאה מחיצוניות המל' בכלים דבריאה ויצי', כמו מט\"ט דבריאה<sup data-n=\"4678\">83</sup>",[["4664","70","<b>דמשה נתנבא בז\"ה</b>: ראה ספרי ר\"פ מטות הובא ברש\"י שם. לקמן פ' בשלח קמד, ב הערה 29."],["4665","71","<b>בכ\"ה בבחי' המל'</b>: ראה פרדס (שעה\"כ) שכ\"ג מערכת כה. ע\"ח (שער תיקון הנוקבא) של\"ד, פ\"ב כלל כא. מאו\"א מערכת כ\"ה סי\"ג וביאיר נתיב שם."],["4666","72","<b>נבואה דמשה. . אבא</b>: נסמן לקמן קטו, ב."],["4667","73","<b>נבואה דמשה. . נו\"ה דז\"א</b>: ראה שעהיחוה\"א פ\"ה. אגה\"ק סי\"ט. לקו\"ש שמות (כרך ו) ע' 251 ואילך."],["4668","74","<b>נו\"ה. . ב' הכרובים</b>: ראה זהר (רע\"מ) פינחס רלו, סע\"א. פרדס (שעה\"כ) שכ\"ג מערכת כרובים. זהר הרקיע לאחרי סז, א (ע' קעד). ס' הליקוטים להאריז\"ל תרומה (כה, יז-יח) סכ\"ה. מאו\"א מערכת כרובים סמ\"ד וביאיר נתיב שם."],["4669","75","<b>שהי' הקול מדבר אליו</b>: נשא ז, פט."],["4670","76","<b>כמ\"ש בפ' תרומה</b>: ראה לקמן פ' תרומה שטו, ד."],["4671","77","<b>וראית את אחורי</b>: תשא לג, כג."],["4672","78","<b>ולא קם נביא. . פא\"פ</b>: ברכה לד, י."],["4673","*79","<b>ג</b>: טז: ב."],["4674","79","<b>משה שהי' רבן של כל הנביאים</b>: שמו\"ר פכ\"א, ד."],["4675","80","<b>וג\"א</b>: ג: וגילוי אלקות. ואולי — וגילוי אליהו ראה לקמן פ' בשלח קנז, א הערה 353. קפו, ג הערה 116."],["4676","81","<b>ר\"ח [ ר' חזקי']. . אסתכלנא</b>: ראה זהר (אד\"ר) נשא קלב, ב. לקמן הערה 293."],["4677","82","<b>אף</b>: אב: א\"ל — באד\"ר שם: פתחו ואמרו — ראה לקמן קג, א. הנסמן בשה\"א צב, א הערה 7."],["4678","83","<b>מט\"ט דבריאה</b>: נסמן לקמן קכב, ג."]]],[2300540275,"שקושר כתרים לקונו<sup data-n=\"4679\">84</sup> וכן יש מט\"ט דיצי'<sup data-n=\"4680\">85</sup> ועשי'<sup data-n=\"4681\">86</sup> כו', אבל לא באורות דאצי' כלל (וגם ר\"י כה\"ג שראה בחי' כת\"ר מל' דעשי' כו' זהו כמבואר בהיכלות דר\"י כה\"ג<sup data-n=\"4682\">87</sup> ופרקי דר\"א הגדול<sup data-n=\"4683\">88</sup> שזהו הכל בהיכלות דבריאה ויצי' ועשי' לבד כו'). וגם אותן ארבעה שנכנסו לפרד\"ס<sup data-n=\"4684\">89</sup> כר\"ע וב\"ז כו' זהו רק בבחי' היכלות דבריאה או <span data-k=\"pg\">374</span> ּ יצי' לבד (ומה שראה למט\"ט יושב<sup data-n=\"4685\">90</sup> כו' זהו מט\"ט דיצי' או עשי' כו' כמבואר בס' הקבלה כו'), שכל זה שהשיגו וראו בפרד\"ס זה לא הי' רק בהיכלות דיצי' לבד, וגם זה בהתלבשות והעלמות כצדיקי' דחזו אפי שכינתא<sup data-n=\"4686\">91</sup> באספקלריא דלא נהרא כו', כי הנבואה נתבטלה אחר החורבן<sup data-n=\"4687\">92</sup>. וגם אותן ששמשו בב\"ק כשמואל הקטן<sup data-n=\"4688\">93</sup> שאמר נביאות לא הי' רק מחיצוניות הכלים דמל' דאצי' בבי\"ע בכמה צמצומים והעלמות כו', וא\"כ איך השיגו חכמי הזהר וכה\"ג באורות העליונים שלמעלה גם מן אורות דאצי' כנ\"ל וד\"ל.\n<b>אך</b> הנה כ\"ז יובן בהקדים הקדמה א' והוא ענין הנהוג בספרי הקבלה לדמות לכל ההשתל' דע\"ס דאבי\"ע בציור אדם<sup data-n=\"4689\">94</sup>, שמחמת זה יוכלו לדמות ולהבין ולהשכיל גם בספי' דאצי' כמו דמיון וציור בנפש האדם בראש ומוחי' ומדות וכה\"ג. אשר באמת השגה זו שאנו משיגים [ב]מהות וערך השכל וחכ' ודעת וגם [ה]מדות שנולדו מהם בנפש האדם שלמטה לערוך מהם וכדוגמתם למעלה בשכל וחכ' ומדות דאדם העליון דאצי' שאין ערך ודמיון כלל ביניהם, שאין לו גוף ולא דמות הגוף<sup data-n=\"4690\">95</sup> וכמ\"ש כי לא ראיתם כל תמונה<sup data-n=\"4691\">96</sup> כו'. וגם שא' בצלם אלקי' עשה את האדם<sup data-n=\"4692\">97</sup> וגם א' מבשרי אחזה אלוה<sup data-n=\"4693\">98</sup> כו', כי זה<sup data-n=\"4694\">99</sup> אינו רק בדרך משל ודמיון בדוגמא דדוגמא להבין מציור זה שעד\"ז יושג רק מציאות הע\"ס דאצי' בבחי' מוחי' ומדות כו' דהיינו רק בחי' מציאות[ן] לבד ולא השגת מהותן כלל. והענין הוא כמו כשאנו משיגים שיש בחי' אור החכ' או בינה דאצי' היינו שאנו מדמים במחשבתינו שיש מציאות חכ' ושכל שהוא בבחי' האצי', שממנו",[["4679","84","<b>מט\"ט. . שקושר כתרים לקונו</b>: ראה סה\"מ ה'תש\"ח ע' 202 בהערה."],["4680","85","<b>מט\"ט דיצי'</b>: ראה פרדס (שער אבי\"ע) שט\"ז, פ\"א. פ\"ד. ע\"ח (שער סדר אבי\"ע) שמ\"ז, פ\"ו. לקו\"ת (שבהערה הבאה) בשם הזהר."],["4681","86","<b>מט\"ט. . ועשי'</b>: ראה גם לקו\"ת — להאריז\"ל — בראשית ג, א (כו, ב). לקוטי הש\"ס — להאריז\"ל — לקדושין (ע' יב)."],["4682","87","<b>בהיכלות דר\"י כה\"ג</b>: אב: בהיכלות דר\"נ ב\"ה דר' נחוניא בן הקנה. ראה גם לקמן צט, ג. ס' היכלות מיוחס לר' ישמעאל בן אלישע כה\"ג ור\"ע. וראה גם שער היחודים ספ\"א ”שבפרקי ההיכלות דר\"י ור\"ע\". וראה בהערה הבאה."],["4683","88","<b>בהיכלות דר\"י כה\"ג ופרקי דר\"א הגדול</b>: במאמרי אדה\"ז תקס\"ג כאן (ע' רפה): בפרקי היכלות דרנב\"ה ודרי\"ש כה\"ג. וראה הערה שלפנ\"ז."],["4684","89","<b>ארבעה שנכנסו לפרד\"ס</b>: חגיגה יד, ב. ראה ע\"ח (שער כסה\"כ) שמ\"ו, פ\"ב. שער רוה\"ק דרוש א' (הא' — יג, א). שער היחודים שם."],["4685","90","<b>שראה למט\"ט יושב</b>: ראה חגיגה טו, א. שער היחודים שם."],["4686","91","<b>כצדיקי' דחזו אפי שכינתא</b>: ראה סוכה מה, ב."],["4687","92","<b>הנבואה נתבטלה אחרי החורבן</b>: ראה סוטה מח, ב. לקמן קיד, ג. פ' בשלח רלא, ד. הנסמן בלקו\"ש ח\"ש (כרך כ) ע' 97 הערה 64. וראה לקו\"ש שופטים (כרך יד) ס\"ג ע' 72 ואילך ובהנסמן לשם."],["4688","93","<b>ששמשו בב\"ק כשמואל הקטן</b>: ראה סוטה שם. מאמרי אדה\"א נ\"ך ע' קמג. וש\"נ."],["4689","94","<b>דע\"ס. . בציור אדם</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א, ענף ב. (שער דרושי אבי\"ע) שמ\"ב, פ\"ב. שער ההקדמות בתחלתו סוף הקדמה ב. הקדמה ד."],["4690","95","<b>שאין לו. . הגוף</b>: ע\"ד פיוט יגדל."],["4691","96","<b>כי לא ראיתם כל תמונה</b>: ואתחנן ד, טו."],["4692","97","<b>בצלם אלקי' עשה את האדם</b>: נח ט, ו."],["4693","98","<b>מבשרי אחזה אלוה</b>: איוב יט, כו [ושם: ומבשרי — ראה לקמן פ' יתרו רסה, א. תצוה שכו, ד. של, ג.] ראה מאמרי אדה\"ז הקצרים ע' רסד. תקס\"ב ח\"א ע' קנד. תקס\"ג ח\"א ר\"ע שנו. [ונו\"ש] שם ע' שנח. לקמן פ' משפטים רפז, ג. הנסמן במאמרי אדה\"א קונטרסים ע' רכח. שעה\"י קלא, ב הערה 24."],["4694","99","<b>כי זה</b>: אב: כ\"ז כל זה."]]],[2300540303,"נמצא מציאות כל חכ' ושכל בכל עולם ועולם לפי מה שהוא כמו חכ' דבריאה וחכ' דיצי' עד שיתהוה מציאות שכל וחכ' האנושית למטה שזהו שאנו רואים ומשיגים איכותו ומהותו, אבל במקור הראשון שהוא בחי' חכ' דאצי' אין לנו השגה במהותו של אור החכ' הזאת איך [היא] ומה ה[י]א שא\"א לדמותו כלל וכלל למהות שכל[ו] של אדם במוח החכ' שבו לא מיני' ולא מקצתי' אף בדוגמא לדוגמא כו', יותר משאין ערוך לגשם הדומם וצומח עם הרוחני כמו הצומח דעשב הגשמי לגבי כח הצומח המצמיחו מאין כו' דעשב זה נתפס במישוש וראות משא\"כ כח המצמיחו כו' דעכ\"ז יש ערך ויחוס וקשר ביניהם, אבל ערך שכל האנושי לגבי בחי' שכל וחכ' דאצי' אין לו דמיון ויחוס כלל, ויותר ממה שלא יוכלו לומר שימששו השכל האנושי שהוא רוחני ביד שאינו בגדר חוש המישוש יותר מזה א\"א לומר שישיג השכל האנושי במהות אור החכ' דאצי'. וגם מה שמשיגים המלאכים בחכ' ומדות דאצי' בכלי השגתם רחוק ערכם מאד יותר מערך הדומם לגבי השכל, כי גם [ל]בחי' אין וכח הרוחני האלקי המהווה אותם מאין ליש לא יוכלו להשיג בשכלם כלל וכלל ולכך אומרים איה מקום כבודו<sup data-n=\"4695\">100</sup> אחר שאו' קדושה כו' (וכמו שנפש אדה\"ר בעל שכל והשגה נמשך רק מבחי' הבל ורוח פיו ית' שנפח באפיו נ\"ח<sup data-n=\"4696\">101</sup> שא\"א לומר שיש ערך ויחוס [ל]שכל ודעת דאדה\"ר לשכל וחכ' האלקי' [אף] שמלובש ברוח והבל זה וכ\"ש [גם] לחכ' ומדות שבעצמות אלקות כו', וכך כל המלאכים ונשמות דבי\"ע שנבראו <span data-k=\"pg\">קפז</span> ּ ברוח פיו ית' וכמ\"ש וברוח פיו כ\"צ<sup data-n=\"4697\">102</sup> איך יוכל להיות שישיגו בשכלם במהות החכ' ומדות דדיבור העליון האלקי המהווה אותם מאחר שלא נתהווה עיקר מציאותם רק מבחי' הבל דדיבור לבד כו'). וכ\"ש בשכל האדם בכלי גופו החומרי שנברא בבטן אמו ששרש שכלו מקבל רק מחכ' שבמל' [ד]מל' דעשי' ששופע במזלות כו'. אך עכ\"ז אנו יכולים להשיג בשכלינו שיש עכ\"פ מציאות דחו\"ב גם באצי' ואיך שמהם נסתעפו ונמשכו בחי' מדות דאצי' שמהם נתהוה מהות כל הנבראי' דבי\"ע במהות חכ' ומדות שלהם כו' ע\"י התלבשות החכ' ומדות דאצי' בדיבור העליון כנ\"ל. וכמו שאנו רואים שיוכל להסתעף מן השכל שבמוח האדם התהוות התפעלות מציאות האהבה בלב כך נוכל לדמות בדוגמא דדוגמא עכ\"פ שיוכל להיות עד\"ז למעלה גם באצי' שיסתעף התהוות אצי' אור מציאות האהבה וחסד מאורות דחו\"ב דאצי', ואע\"פ שאין אנו משיגים כלל במהות המדות והחכ' [דאצי'] בשום דמיון וערך לערך כלל [וכלל] עכ\"ז בבחי' השגת המציאות נוכל להשיג דהיינו שיש מציאות דחו\"ב ומדות באצי' דוגמא לשכל שבאדם למטה שיתהוה ממנו מדת האהבה, אע\"פ שאין שכל ומדות האהבה דאדם התחתון דמיון וערך ודוגמא כלל לחכ'",[["4695","100","<b>אומרים איה מקום כבודו</b>: בקדושת כתר."],["4696","101","<b>שנפח באפיו נ\"ח</b>: בראשית ב, ז."],["4697","102","<b>וברוח פיו כ\"צ</b>: תהלים לג, ו."]]],[2300540328,"ומדות דאצי' שהרי מן שכל האדם לא יתהווה שום מציאות נברא מאין ליש ולא ממדות שלו בלב וכ\"ש מדבורו ומחשבתו לא ימשיך שום אור וחיות ושפע אפי' להיות בריאה קלה ושפע גשמי' לכל בריאה כו', אבל מבחי' דיבור העליון ומדותיו וחכמתו ובינתו ית' שנאצלו מעצמותו הרי מהם נמשך מקור האור והחיות והזמן של כל העולמות דבי\"ע בג' מדרגות דעולם שנה נפש בכל עולם ועולם לפי ערכו כידוע, וכללותם יחד עם כל מה שבא ונמשך בהם התהוות שכליות והשגות מיוחדות דמלאכי' ונשמות ופרטי אופניהם בציור אדם ובציור בהמה וחיות ועוף כפני ארי' ושור ונשר כו' כולם מתייחסים שנתהוו ממקור אחד הכולל הכל שהוא בחי' אור החכ' דאצי' שמלובש בחכ' שבי\"מ<sup data-n=\"4698\">103</sup> כמ\"ש כולם בחכ' עשית<sup data-n=\"4699\">104</sup> וכמ\"ש בראשית בחו\"ב<sup data-n=\"4700\">105</sup> כו', שהחכ' דאצי' מקורם הכללי וממנו שופע בתמידות האור ושפע הכללית אל כל העולמות והברואים להיות חיים וקיימים במציאותם המוגבל מאין ליש נפרד ב\"ג ותכלית בשכל ומדות שלהם עד גשמיות דארמ\"ע ודצח\"ם דעוה\"ז השפל (שע\"ז א' א\"ל נהירו דחכ'<sup data-n=\"4701\">106</sup> אדו\"ן על כל המעשים<sup data-n=\"4702\">107</sup> כו'). ואע\"פ שבודאי אין ערך כלל וכלל לברואים הגשמיי' וגם הרוחני' לבחי' החכ' שמחי' את הכל, מ\"מ הרי ממנו מקור התהוות מציאות[ם] מאין ליש בכל רגע מה שאין זה הכח בכל בחי' חכ' שבבריא' כחכ' דאדם (רק שיורד והולך<sup data-n=\"4703\">108</sup> בהשתלשלו' מחכ' דאצי' שנק' חכ' בראש בחכ' דדבור שנק' חכ' בסוף<sup data-n=\"4704\">109</sup> ומחכ' דמל' בחכ' דבריאה להוות חכ' דבריאה ומחכ' דבריאה לחכ' דיצי' עם חכ' ושכל האנושי ג\"כ כמ\"ש יהיב חכ' לחכימין<sup data-n=\"4705\">110</sup> כו' וד\"ל).\n<b>ונמצא</b> מובן עכ\"פ שאע\"פ שאנו מדמי' בכח דמיון וציור משכל וחכ' שלנו לומר למעלה כדוגמתו בחכ' דאצי' אין זה רק ע\"ד משל ודוגמא (ולא כמו הציור ודמות שממנו יושג בדמיון לבריאה אדם חי שיש לו דמיון עכ\"פ בציור אדם, שהרי אין לו ית' שום דמות ודמיון כמ\"ש אל מי תדמיונ\"י<sup data-n=\"4706\">111</sup> כו', ומ\"ש בצלמנו כדמותנו<sup data-n=\"4707\">112</sup> היינו בציור אדם דבריאה ויצי' <span data-k=\"pg\">376</span> ּ כאדה\"ר בהיותו קודם החטא שהי' בצלם אלקים ממש) וכמו\"כ במל' דאצי' בבריאה ויצי' שנק' מראה דמות כבוד הוי' ממש (וכה\"ג בכנ\"י במצות שמצויירים בזה בציור אדם העליון ונק' ציון המצויינת<sup data-n=\"4708\">113</sup> וכמ\"ש ומרא\"ך נאו\"ה<sup data-n=\"4709\">114</sup> כו' כמ\"ש במ\"א), דהיינו מה שישיגו ממנו בדוגמא בעלמא להשיג שיש מציאות שכל וחכ' באצי' אבל לא שיושג במהות ועצמות [ד]חכ' ומדות דאצי' (ואף לא במהות ועצמות דחכ' ומדות ומו\"ד דע\"ס דבריאה ויצי' ועשי' (רק הנביאי' כמשי\"ת) לא מיני' ולא מקצתי' כלל ולכך אמר החקר אלוה תמצא<sup data-n=\"4710\">115</sup> כו' דכל חקירה ודרישה הוא [ב]עין השכל והשגה",[["4698","103","<b>שבי\"מ</b>: שבי' מאמרות. א: שבחכ' שבמל'. ג: שבמל'. ט: מחק תיבת מל' ותיקן כבפנים."],["4699","104","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["4700","105","<b>בראשית בחו\"ב </b>[א: בחוכמתא. ב: בחכ']: בראשית א, א. וראה תרגום ירושלמי שם."],["4701","106","<b>א\"ל נהירו דחכ'</b>: ראה זהר לך צד, א. צו ל, ב. לא, א. אחרי סה, א. מאמרי אדה\"א דרושי חתונה ח\"א ע' קצ."],["4702","107","<b>א\"ל. . אדו\"ן על כל המעשים</b>: זהר תרומה קלב, א. ברכת יוצר לשבת. ראה הנסמן במ\"מ לשע\"ת קכג, א הערה 5."],["4703","108","<b>שיורד והולך</b>: אב: שהולך ויורד."],["4704","109","<b>חכ' בראש. . חכ' בסוף</b>: ראה זהר בראשית כו, ב. מאמרי אדה\"א ויקרא ח\"ב ס\"ע תצה ואילך. וש\"נ. קונטרסים ע' ריב. וש\"נ. תו\"ח וישב רא, ג."],["4705","110","<b>יהיב חכ' לחכימין</b>: דניאל ב, כא."],["4706","111","<b>אל מי תדמיונ\"י</b>: ישעי' מ, כה [ושם: ואל]."],["4707","112","<b>בצלמנו כדמותנו</b>: בראשית א, כו."],["4708","113","<b>ציון המצויינת</b>: לשון הושענא אבן שתי' (ליום ב')."],["4709","114","<b>ומרא\"ך נאו\"ה</b>: שה\"ש ב, יד. ראה מאמרי אדה\"ז תקס\"ו ע' קלח ואילך. מאמרי אדה\"א שמות ח\"ב ע' תרנג. וש\"נ."],["4710","115","<b>החקר אלוה תמצא</b>: איוב יא, ז."]]],[2300540351,"האנושי' ואיך יכול אדם שנברא בשכלו מאי\"ן ליש (רק מהבל הדיבור העליון כנ\"ל) לחקור ולידע בידיעה במהות האלקי' שהוא נבדל בערך מהשגתו באלף הבדלות כו' (יותר מערך דמישוש היד בשכל כו'<sup data-n=\"4711\">*116</sup>. וגם בחי' ידיעה בדרך שלילה<sup data-n=\"4712\">116</sup> א\"א לשכל האנושי להשיג רק במציאות האלקו' ולא במהות כלל כמו שידוע בהפשטות הגשמיות מן הרוחניות בתכלית איך שהרוחני מושלל ומובדל בתכלית מכל תואר[י] גדרי הגשם עכ\"ז אינו ידיעה במהות הרוחני כחיות האדם וכל חיות רוחני שאינו [יודע] מהותו כלל רק משיג ערך מציאותו לבד כו' (כמ\"ש במ\"א). וכך הוא ג\"כ בידיעת אלקות אע\"פ שיודע בדרך שלילה דהיינו איך שאין ערך כלל לבבע\"ג לגבי ב\"ג ויודע לשלול ולהפשיט מכח האלקי כל בחי' תואר בריאה מוגבלת שהוא מחודש והווה ונפסד כו' ולבורא אין לו תחלה ובלתי ב\"ג כו', עכ\"ז לא יוכל להשיג במהות<sup data-n=\"4713\">117</sup> האלקי' כלל איך הוא ומה [הוא] כו', וגם בהשגה זאת איך שהוא קדוש ומובדל בערך כו' אין זה ידיעה רק בהשגת מציאותו ית' שהוא מקור כל המציאות ואיך שמאמתת מציאותו נמצא כל הנמצאי'<sup data-n=\"4714\">118</sup> ונק' עה\"ע<sup data-n=\"4715\">119</sup> כו' וכה\"ג, אבל לא ידיעה וחקירה בעצם מהותו ית' דלית מחשבה תב\"כ<sup data-n=\"4716\">120</sup> במהותו וכמ\"ש החקר אלוה תמצא, וגם כל השגה שכליות של חכמי האלקי' כחכ' דנה\"א כל נשמה לפי שרשה אף נשמה גבוה ששרשו בחכ' שבמל' דאצי' בבריאה כחכמת שלמה<sup data-n=\"4717\">121</sup> לא השיג במהו\"ע מל' דאצי' רק בדרך נבואה לבד (כמשי\"ת). וזהו שא' מה פשפשת מה ידעת<sup data-n=\"4718\">122</sup> כו' שזהו מא' החכ[ם] שתכלית הידיעה שלא נדע<sup data-n=\"4719\">123</sup> דבהעדר הידיעה יש בו יותר ידיעה להיותה [מושללת] מידיעה הגשמיות מושללת הגשמיות<sup data-n=\"4720\">124</sup> עכ\"פ שהוא טוב יותר מן הידיעה בהשגה ותפיסא מטעם הנ\"ל וד\"ל). וכל זה הוא שנק' בשם ידיעת המציאות שהוא גם במה שלא ראה הדבר מעולם רק מדמהו בכח שכלו מרחוק בלבד כמו עד\"מ הסומא בתולדה בבטן אמו שלא ראה מאורות השמש ושום זיו ואור מימיו גם הוא יכול להבין ולהשכיל בשכלו ולצייר אופן מהות האור והזיו המאיר בכלי מוחו, וגם כאשר יסבירו לו אנשים שראו את האור איך הוא ומה הוא אופן מציאותו וישכיל ויבין מהם אמיתית מציאות האור כמו שהוא עכ\"ז לא יוכל להשיג מהות האור ממש כמו שהוא לעולם כמו שישיגנו הרואה את האור במהותו (כמו שאינו דומה שמיעה לראי'<sup data-n=\"4721\">125</sup> אף בדבר שיודע ומכיר [מ]כבר וכ\"ש אם לא ראה אותו הדבר מעולם לא יוכל להשיג רק שיש מציאת <span data-k=\"pg\">קפח</span> ּ דבר זה בעולם). וכך יובן ע\"ד כל זה בענין השגות אלקות שמשיגים כל הנשמות",[["4711","*116","<b>כו'</b>: כנצ\"ל: כו')."],["4712","116","<b>ידיעה בדרך שלילה</b>: ראה גם תו\"ח נח מח, ב. מאמרי אדה\"א נ\"ך ע' ס ואילך. וש\"נ. לקמן קג, ד. פקודי תמו, א. וש\"נ."],["4713","117","<b>במהות</b>: אב: במהו\"ע."],["4714","118","<b>שמאמתת. . הנמצאי'</b>: ראה רמב\"ם ריש הל' יסוה\"ת."],["4715","119","<b>עה\"ע</b>: ת\"ז בהקדמה (יז, א)."],["4716","120","<b>דלית מחשבה תב\"כ</b>: ת\"ז שם."],["4717","121","<b>בחכ' שבמל' דאצי' בבריאה כחכמת שלמה</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' תתסב. תו\"ח בראשית לב, ג."],["4718","122","<b>מה פשפשת מה ידעת</b>: ראה זהר בהקדמה א, ב."],["4719","123","<b>שתכלית הידיעה שלא נדע</b>: ראה בחינת עולם ח\"ח, פ\"ב. עקרים מ\"ב, ספ\"ל. של\"ה מס' שבועות בהג\"ה קצא, ב."],["4720","124","<b>מושללת הגשמיות</b>: אב: ליתא."],["4721","125","<b>שאינו דומה שמיעה לראי'</b>: נסמן לעיל פ' שמות כב, ב."]]],[2300540374,"ומלאכים העליונים בג' עולמות דבי\"ע שאין זה רק בבחי' השגות המציאות ולא בהשגות המהות כלל, דהיינו שגם בבחי' כח ואור אלקי המחיה אותם מאין ליש הוא משיג במהותו כמו שהוא והוא מה שנמשך מאור האלקי ע\"י צמצום דאותיות וצירופי' העליונים עליהם ולכך אומרים קדוש וברוך ואומרים שירה בתמידות כצבא השמים שסובבים והולכים בביטול תמיד, אבל באור האצי' שמלובש בצמצום זה או' איה מקום כבודו כי מהות אור האצי' קדוש ומובדל לגמרי מהשגתם ואין משיגי' רק בבחי' השגת המציאות בלבד ע\"ד הנ\"ל, וז\"ש השרפי' קדוש ה' צבאות וכה\"ג. ואם הי' אור דאצי' אף מבחי' האחרונה דמל' שבמל' דאצי' מתגלה על המלאכים היו מתבטלים ממציאותם לגמרי כענין שא' הושיט אצבעו הקטנה ביניהם ושרפ\"ן<sup data-n=\"4722\">126</sup> שהוא יו\"ד דשם אד'<sup data-n=\"4723\">127</sup> וכה\"ג) וכמ\"ש בזהר בבחי' בהמה רבה דרביע על אלף טורין ושתת לון בגמיעא חדא<sup data-n=\"4724\">128</sup> שנכללים בפי רוח הבל דיבור העליון כו', וגם הנשמות בג\"ע שנהנין מזיו השכינה<sup data-n=\"4725\">129</sup> שזהו מבחי' בינה שבמל' דאצי' כידוע, גם זה א\"א להיות שישיגו במהות ועצמות דאור האצי' כמו שהוא, שהיו מתבטלין ממציאותם לגמרי, רק ע\"י בחי' לבוש דחשמ\"ל שמלביש לנשמה<sup data-n=\"4726\">130</sup> ונק' זיהרא עילאה<sup data-n=\"4727\">131</sup> (והוא שנק' ג\"כ אספקלריא שעל ידו חזי אפי שכינתא כו').\n<b>אך</b> הנה ענין הנבואה בנביאים כו' זהו כמו גילוי שכינה ממש כמו שהי' גילוי שכינה בהיכל ק\"ק בבהמ\"ק שצמצם שכינתו בין בדי הארון<sup data-n=\"4728\">132</sup> ממש שנתפס מהו\"ע מל' דאצי' במקום זה כמו כי בענן אראה<sup data-n=\"4729\">133</sup> כו', רק<sup data-n=\"4730\">134</sup> היו רואים דור המדבר כבוד ה' ממש בענן וכה\"ג בנביאי' אף שהיו בחילוקי מדרגות שונות בכל א' לפי שרש נשמתו בכלים דע\"ס דבריאה או יצי' כו', מ\"מ הרי היו משיגים השגות המהות דאור האצי' כמו מל' דאצי' בראיית המהות כמו שרואה אדם בראיית עין הגשמי', כמו שא' ואראה את הוי' צבאות כו' שהי' רואה בגילוי גמור במהות ועצמות דשם הוי' דאצי' שהוא מל' דאצי' כמו שהיא בעולם הבריאה בלי לבוש והעלם כלל, וכן יחזקאל ראה במל' דאצי' ביצי' (ולא כמו השגת המרכבה דבריאה ויצי' שאנו משיגים רק בבחי' השגת המציאות ולא במהות ע\"כ או' איה כו' כנ\"ל, וז\"ש ואשמע אחרי קול, אחרי דוקא כו' כנ\"ל וד\"ל). והנה<sup data-n=\"4731\">135</sup> הגם שא' בנבואת הנביאים במראה אליו אתוודע בחלום אדבר בו וכן ביד הנביאים אדמה<sup data-n=\"4732\">136</sup> היינו כדמיון שבחלום הוא שר[ו]אה במהות ועצמות אלקות שמדבר בו כמו בהקול<sup data-n=\"4733\">137</sup> ממש אבל לא בהשגת",[["4722","126","<b>הושיט אצבעו. . ושרפ\"ן</b>: נסמן לעיל פ' שמות ל, ב."],["4723","127","<b>ביניהם. . אד'</b>: אב: (שהוא יו\"ד דשם אד') ושרפ\"ן כו'."],["4724","128","<b>בהמה רבה. . חדא</b>: ראה זהר בראשית יח, ב. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' יב."],["4725","129","<b>הנשמות. . מזיו השכינה</b>: ראה ברכות יז, א."],["4726","130","<b>לבוש דחשמ\"ל שמלביש לנשמה</b>: ראה הנסמן לעיל פ' וארא סב, ג."],["4727","131","<b>זיהרא עילאה</b>: ראה הנסמן לעיל פ' שמות ח, ב."],["4728","132","<b>שצמצם שכינתו בין בדי הארון</b>: ראה ב\"ר פ\"ד, ד. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א הערה 12."],["4729","133","<b>כי בענן אראה</b>: אחרי טז, ב."],["4730","134","<b>רק</b>: אב: וכן."],["4731","135","<b>והנה</b>: י: נסמן כאן פ\"ד."],["4732","136","<b>ביד הנביאים אדמה</b>: הושע יב, יא [ושם: וביד (וכ\"ה לעיל כז, ד) — ראה לעיל פ' שמות לח, ב. לקמן פ' בשלח קמח, ד. קצד, ג. רג, ג. מאמרי אדה\"א שמות ח\"ב ע' תקנא. וש\"נ. ש\"א לח, א. שע\"ת מו, ד הערה 32]."],["4733","137","<b>בהקול</b>: אב: בהקיץ."]]],[2300540395,"שכליי' בלבד כמ\"ש במ\"א בענין דניאל וחביריו<sup data-n=\"4734\">138</sup> שהם לא ראו את המראה וע\"כ<sup data-n=\"4735\">139</sup> חרדה גדולה נפלה עליהם משום דמזלי' חזי בהעלם דמקיף אבל דניאל נפל על פניו<sup data-n=\"4736\">140</sup> כי ראה בגילוי ולא בהעלם במזלי' לבד כו'. אך עכ\"ז הי' גילוי אור הנבואה בכל נביא כ\"א לפי שרש מדריגתו דוקא כי לא היו יכולים להשיג במהות ועצמות דאור המל' הנק' שכינה כ\"א ע\"י התלבשות בשרש ומקור נשמתו למעלה, אם בבחי' הכלים פנימיי' <span data-k=\"pg\">378</span> ּ די\"ס דבריאה כמו נשמת ישעי' שהי' שרש נשמתו בכלים די\"ס דבריאה (וע\"כ נמשל לבן כרך<sup data-n=\"4737\">141</sup> כו') או בכלים די\"ס דיצי' ועשי' כיחזקאל וזכרי' וכה\"ג, אבל ע\"י אותן בחי' הכלים דע\"ס דבריאה ויצי' הן<sup data-n=\"4738\">*142</sup> רואין מראה הנבואה במהות האורות דאצי' דהיינו במהות בחי' נו\"ה דז\"א דאצי' אע\"פ שמלובשי' בנו\"ה דמל' דאצי' [ו]בנו\"ה דבריאה או יצי' כו', משא\"כ מדרגת רוה\"ק וג\"א שיכול להיות בכל הנשמ[ות] זולת [ה]נביאי' כמו [רנב\"ה ו]ר\"א הגדול ור\"ע<sup data-n=\"4739\">142</sup> ורשב\"י<sup data-n=\"4740\">*143</sup> וכה\"ג [ורב המנונא סבא<sup data-n=\"4741\">143</sup> ובניו] שהן נק' נוני ימא רבא<sup data-n=\"4742\">144</sup> כו' שלא השיגו במהות ועצמות אורות דאצי' כלל, רק בבחי' השגות המציאות באור השכל והשגה האלקי' דבינה שבמל' דאצי' שמאיר בשרש נשמתם בדרך לבוש דחשמל כמו לנשמות בג\"ע כנ\"ל. וכך הוא ענין ר\"י כה\"ג שראה אכתריאל כו' בהיכלות דיצי' ועשי', וכן היכלות דרנב\"ה שזהו בהיכלות החיצוני' דיצי' שמלאכים דיצי' מקבלים שם דרך הסתר וצמצום גדול מאורות דאצי', כמו שמבחי' למ\"ד כלים דז\"א<sup data-n=\"4743\">145</sup> נתהוו נר\"נ דבי\"ע בהשתלשלו' עו\"ע בריבוי הצמצומים וד\"ל. ובזה יתורץ הקושיא דלעיל במה שמצינו באדרא<sup data-n=\"4744\">146</sup> שהשיגו רשב\"י וחביריו בכל פרטי הפרצופים דע\"י וא\"ק כו' שכל זה אינו אלא בהשגת המציאות לבד ולא בהשגת המהות כלל כנ\"ל וד\"ל.\n[ד] <b>ומעתה</b> יובן ג\"כ בבחי' המל' למעלה שהיא אחת ממדותיו ית' בבחי' ע\"ס דאצי' דאיהו וחיוהי חד<sup data-n=\"4745\">147</sup> כו' כידוע דאין לשכל אדם השגה במהות ועצמות דמדה זאת דמל' כמו שהיא למעלה הגם שאנו מדמין לפי אופן דמיון<sup data-n=\"4746\">148</sup> כח המדות האדם למטה במדה זו [ג\"כ] שה[י]א מד\"ת ההתנשאות ו[ה]ממשלה וההתפשטו' על זולתו אין בזה דמיון וערך להשיג עד\"ז לבחי' המל' למעלה רק בבחי' השגת המציאות לבד דהיינו שיש מציאות מדת ההתנשאות גם למעלה אבל לא שיושג מדה זו כמו שהיא במהותה ועצמותה ממש כו' לא מיני' ולא מקצתי'",[["4734","138","<b>בדניאל וחביריו</b>: דניאל י, ז. מגילה ג, א. ראה לקמן פ' ויקהל שפז, ב. מאמרי אדה\"ז תקס\"ח ח\"א ע' רכט ואילך וע' רלה. פרשיות התורה ח\"ב ע' תתטז ואילך. לקו\"ת במדבר טז, א. מאמרי אדה\"א שמות ח\"ב ע' תרסא."],["4735","139","<b>וע\"כ</b>: אב: ועכ\"ז."],["4736","140","<b>דניאל נפל על פניו</b>: דניאל שם, ט."],["4737","141","<b>ישעי'. . לבן כרך</b>: חגיגה יג, ב."],["4738","*142","<b>הן</b>: אב: היו."],["4739","142","<b>ור\"ע</b>: ראה גם סידור שער בהמ\"ז קה, א. לקמן פ' ויקהל תל, ג."],["4740","*143","<b>ורשב\"י</b>: ראה גם סידור שם. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רנו. לקמן פ' יתרו רסה, א. הערה 83. ויקהל תל, ג."],["4741","143","<b>ורב המנונא סבא</b>: ראה זהר בהקדמה ו, א. מאמרי אדה\"ז אתהלך לאזניא ר\"ע קנז. מאמרי אדה\"א בראשית ע' קנא. וש\"נ. שע\"ת מה, א הערה 7. לקמן פ' בשלח קסב, ג. רז, א."],["4742","144","<b>נוני ימא רבא</b>: זהר בלק קפז, א. ראה לקמן פ' יתרו רסה, א. הנסמן במאמרי אדה\"א שם."],["4743","145","<b>למ\"ד כלים דז\"א</b>: נסמן לעיל פ' שמות כד, ב."],["4744","146","<b>באדרא</b>: אב: באד\"ר. וראה לעיל צח, א ”באד\"ר ואד\"ז\"."],["4745","147","<b>דאיהו וחיוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["4746","148","<b>דמיון</b>: אב: ליתא."]]],[2300540415,"כלל כנ\"ל באריכות בכלל זה בכל השגות דנשמות בבחי' אור האצי'. דהנה<sup data-n=\"4747\">149</sup> גם לפי שאנו מדמין להשיג אף בבחי' המציאות דמדת מל' למעלה שהוא כמו בחי' התנשאות שיש באדם למטה א\"א לומר בו<sup data-n=\"4748\">150</sup> ממש במדת מל' למעלה שא' עלי' דלית לה מגרמה כלום כו' בב' אופנים הנ\"ל<sup data-n=\"4749\">151</sup> וב' פי' הנ\"ל [ש]שניהם אמת כנ\"ל. דהנה אנו רואים במהות טבע מדה זאת דהתנשאות באדם התחתון שהיא גדולה וחזקה בתוס' אור גדול ורב בנפש יותר מכל המדות שלה כמדת החס\"ד שנק' גדולה<sup data-n=\"4750\">152</sup> כו', להיות שיש במדת התנשאות זו תענוג גדול ואור וחיות בתוס' גדול בעילוי רב לנפש האדם כשיש לו ממשלה והתנשאות גדולה או קטנה על זולתו באיזה התמנות ממשלה, או כשינשא[ו]הו בכבוד גדול שירוממו נפשו מאד בזה עד שיהי' לו מזה חיות ותענוג מופלג בעצם נפשו יותר מכל תענוגי עוה\"ז הגשמי' כאכילה ושתיה ומעדנים רבים וגם יותר מחמדת ותענוג הממון וכל הון ויקר כלא חשיב נגד הכבוד וגדולה בהתנשאות, כמו בכבוד וגדולת השרים והמלכים שיפזרו כל הון וילחמו לנגד אויבם בהפקירות רק שיוגדל יותר כבוד ממשלתם בהתנשאות כו' (וכמ\"ש ברמב\"ם שהתענוג הגדול בגדולה והתנשאות שנק' כבוד<sup data-n=\"4751\">153</sup> הוא רוחני ברוחניות עצמות הנפש ומושלל מכל תאוה גופניות כמשגל ואו\"ש<sup data-n=\"4752\">154</sup> <span data-k=\"pg\">קפט</span> ּ וגם מקיבוץ הון ולבושים ובתים ופרדסים כו', ואפס קצה ממנו יובן ערך העונג הרוחני האלקי בג\"ע העליון לנשמות עד שגם עונג זה דכבוד והתנשאות גשם גמור יחשב שם<sup data-n=\"4753\">155</sup> כו'). להיות שההתנשאו' והרוממות על הכל בחי' מקיף הוא לנר\"נ שבאדם ע\"כ למעלה הוא גם מעונג שבחכ' ומדות באה\"ר בתענוגי' ולמעלה גם מהעונג שבכל רצון אלא הוא [ב]עונג הפשוט ועצמי שבעצם הנפש ממש וע\"כ פיקוח ותענוג גדול הוא לעצם נפש[ו] יותר מכל חיי תענוג[י'] זולתו כו' וד\"ל. אך עכ\"ז הגם ששרש מדה זאת מגעת [ב]תענוג העצמי ברוממות עצמות הנפש (וע\"כ אנו רואים [ש]בעת גדולתו ורוממותו יהפך לבבו להפוך מדות הטבעיות מן הקצה כו' כמו לעשות טוב לשונאו וכה\"ג) הרי לא יבא מהתנשאות ורוממות זו שום השפעה וחיות ממש לזולתו רק מרחוק מתנשא ואם מצד [זה] יגיע ממילא רב טובו כידו הגדולה לפ\"ע זה יכול להיות להיפך כידוע כו', שהרי אין אדם מקבל שפע חסד או שיבורך בברכה ע\"י התנשאו', משא\"כ במדת החסד והטוב מאיש הטוב וחסדן בעצם שישפיע רב טוב וחסד לכל ויחי' ויקיים נפשות רבות כו' וד\"ל.",[["4747","149","<b>דהנה</b>: ג: נסמן כאן: פ\"ד. ואולי מקומו לעיל בריש הפיסקא."],["4748","150","<b>בו</b>: אב: כן."],["4749","151","<b>הנ\"ל</b>: אב: ליתא."],["4750","152","<b>החס\"ד שנק' גדולה</b>: ראה לקו\"ת עקב יז, ד. מאמרי אדה\"א נ\"ך ע' תקלד. וש\"נ. תו\"ח ויצא קעה, ד ובהערה 14."],["4751","153","<b>ברמב\"ם שהתענוג. . כבוד</b>: ראה פיה\"מ סוף עוקצי'. הקדמה לפ' חלק ד\"ה ועתה אחל. מאמרי אדה\"א בראשית ע' כ. וש\"נ. שמות ח\"ב ע' תטז. קונטרסים ע' קי וע' שיד. לקמן פ' ויקהל תכח, ב."],["4752","154","<b>ואו\"ש</b>: א: ואכילה ושתי'."],["4753","155","<b>עונג זה דכבוד. . גשם. . שם</b>: ראה פיה\"מ שם. מאמרי אדה\"א בראשית ע' יב. וש\"נ. שמות שם. קונטרסים ע' קי."]]],[2300540435,"<b>והנה</b><sup data-n=\"4754\">156</sup> להבין מדוגמא זאת למעלה בבחי' המל' כמו שאנו משערי' בנפשינו מבחי' מדת ההתנשאות והגדולה ורוממות באדם כך יהי' במל' דאצי' שהוא ג\"כ בבחי' ההתנשאו' כזאת ודאי אין הנמשל דומה עם המשל, דבהתנשאות שלמטה הוא טבע האנושי' להתנשאות ולהתרומם שזהו משפלות לגדולה שיש בזה שינוי גדול, אבל למעלה א\"א לומר שיהי' חפץ להתנשא ולהתרומם כי כבר הוא ית' מרומם ומתנשא לבדו ואין עוד זולתו שיהי' מתנשא עליהם כי אין לך דבר זולתו כו' ומי יערוך אליו שיפול בזה לשון התנשאות, וגם<sup data-n=\"4755\">157</sup> הוא בבחי' המל' העליון ברוממות והתנשאות האלקי כמו שאין מלך בלא עם כך ה' מלך גיאות לבש בצמצום גדול כנ\"ל, הרי בהתנשאות זאת הוא מחיה את הכל מאין ליש כי במה שמתנשא בבחי' המל' נק' בחי' שם מלכותו עליהם ובזאת הוא עיקר ומקור שפע חיותם וקיום התהוות מציאותם בתמידות מאין ליש (כמו ומוראך עליהם<sup data-n=\"4756\">158</sup> כו' שביראה זאת האלקית עיקר חיותם ולכך המלאכים חיים וקיימים יותר מן הנשמות דבנ\"א לפי שיש בהם יראת אלקי' יותר כמ\"ש יראת ה' לחיים<sup data-n=\"4757\">159</sup> כו' כמ\"ש במ\"א). וא\"כ עכ\"פ אין המשל והנמשל דומים זע\"ז כלל [ע\"פ כל זה], כי הרי בהתנשאות שלמטה שאין מלך בלא עם הרי יש מציאות עם נפרד ממהות המלך בתחלה שהם חיים וקיימים במציאותם קודם שיקבלוהו עליהם למלך ואמנם בבחי' מלכותו עליהם [מ]נהיגם כרועה צאן בלבד, משא\"כ למעלה הרי התהוות הנבראים וחיותם הוא מבחי' ההתנשאות כנ\"ל, וא\"כ מהיכן [הי'] סיבת מדה זאת דהתנשאות שאינ[ה] רק על זולתו והרי לא הי' דבר זולתו כלל. וגם במה שאחר ההתנשאות נעשי' הברואים בבחי' יש נפרד האיך יתכן להיות שיתנשא ע\"ד<sup data-n=\"4758\">160</sup> שנעשה ממנו עצמו כו'. אלא צ\"ל בכ\"ז שאנו מדמים ומשערים בנפשינו למעלה באצי' אינו רק בדרך דוגמא ומשל שאינו בדומה לו ממש במהותו כמו שהוא ממש רק בדרך השגת המציאות לבד כנ\"ל, דהיינו מה שמתוך משל ודמיון זה דמדת ההתנשאו' באדם <span data-k=\"pg\">380</span> ּ למטה (להיותו בצלם ודמות לאדם העליון כו') יוכלו להשיג שיש מציאות כזאת בבחי' מדת ההתנשאות האלקי' דאצי' העליונה שנק' בשם מדת מל' אבל לא שידמה למהותה ועצמותה ממש כמו שהוא למטה, מאחר דאין בחי' ערך ודמיון כלל לנפש האדם ע[ם] כל כחותי' שהן מוגבלים ונבראים מאין ליש, ושרש התהוות כל עצם הנפש עם כח השכל שבה מבחי' מל' דאצי' המלובשת בבי\"ע לה[י]ות מאין ליש לבחי' נר\"נ כו' כידוע, וא\"כ איך ישיג בשכלו מהות בחי' המל' למעלה שהוא התנשאות האלקי' שלמעלה ממקור חוצב[ה] לגמרי כנ\"ל, והרי גם השכל שבנפש מקבל ממנה ואין בהתנשאות העליונה מהות שכל כלל (וכמו ויפח באפיו נ\"ח<sup data-n=\"4759\">161</sup> הרי מהבל פשוט נעשה",[["4754","156","<b>והנה</b>: י: נסמן כאן פ\"ה — פ\"ד נסמן לעיל על יד הערה 135."],["4755","157","<b>וגם</b>: א: וכך. ט: כתוב וכך וממעל לשורה כתוב: וגם."],["4756","158","<b>ומוראך עליהם</b>: פיוט אשר אימתך [מוסף ליו\"כ]."],["4757","159","<b>יראת ה' לחיים</b>: משלי יט, כג. ראה סידור שער הק\"ש פב, סע\"ג בשם הה\"מ. מאמרי אדה\"א ויקרא ח\"ב ע' תקלט. דברים ח\"ד ע' א'תיג. קונטרסים ע' שטו ובהנסמן בהנ\"ל. לקמן פ' תרומה שז, ג."],["4758","160","<b>ע\"ד</b>: א: על דבר."],["4759","161","<b>ויפח באפיו נ\"ח</b>: בראשית ב, ז."]]],[2300540455,"נפש שלימה בשכל ומדות כו' וכנ\"ל). וא\"כ לא יקשה ג\"כ ענין הנ\"ל במה שאין התנשאות העליונה בדומה למשל התנשאות שבאדם שיש דבר מה חוץ ממנו שיתנשא עליו משא\"כ למעלה שנתהוו מבחי' ההתנשאות העליונה כו', משום דאין מדה זאת דהתנשאות האלקי' למעלה כשאר המדות [ד]חו\"ג וכה\"ג שעצם מהות החסד כמו שהוא בלב הטוב של אדם הטוב הוא שנמשך לזולתו המקבל ממנו, שאם הי' התהוות העולמות מבחי' החסד העליון דאצי' כמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"4760\">162</sup> הרי הי' נמשך ממהות ועצמות דאור החסד דאצי' בבריאה ויצי' כו', וא\"כ לא הי' יכול להיות מציא[ו]ת בריאה ב[ע]\"ג כמיכאל שנמשך מחסד דמל' דבריאה וכה\"ג אלא הי' הכל בבחי' אצי' כו'. ומזה הטעם לא הי' באפשרי להיות השתלשלות העולמות מבחי' המדות דאצי' עצמן ומהותן כ\"א מבחי' התלבשותם במדת המל' דוקא, וכידוע דכל המדות דאצי' נמשכים לבחי' המל' שהוא בחי' [ה]התגלות של כל המדות שבלב [ו]ע\"כ א' דמדת המל' לית לה מגרמה כלום רק מה שנמשך לה מן המדות בלבד, כי בחי' המל' יש בה ב' מדרגות א' בבחי' מקיף והוא בחי' ההתנשאות שנמשך ג\"כ מן המדות שבלב ורצון וחכ' שבמוח (כמשי\"ת), והב' מה שהוא בבחי' או\"פ שזהו בחי' ההתגלות של המדות הבא באותיות הדיבור שיוצא נפרד לחוץ, ובחי' ההתנשאות דמדת מל' הוא מקור כל העולמות בבחי' מקיף מרחוק ובאותיות הדיבור שנק' דבר מל' הוא שנמשך אור וחיות לכל הנבראי' בגילוי גמור, כמו דבר מלך שלטון<sup data-n=\"4761\">163</sup> כו' כמו במאמר יהי רקיע<sup data-n=\"4762\">164</sup> נתהוה הרקיע מאין ליש ממש והוא לפי שהוא דבר מל' דוקא וכן במאמר יהי אור<sup data-n=\"4763\">165</sup> וגם במה שציוה לארץ כמ\"ש תדשא הארץ<sup data-n=\"4764\">166</sup> כו' הכל לפי שגזירת מלך הוא מבחי' מל' דאצי' שנק' מלך העולם כשמתצמצם להיות מלך כו', ובזה יתהוה מקור מציאות הנבראים אח\"כ באותיות הדיבור שלו, והוא הטעם שנעשה מקור העולמות ממדה זאת דבחי' המל' דוקא להיותה בבחי' נבדל ומרומם מן העולמות ולא נמשך ממהו\"ע [ית'] אור האצי' כלל רק מרחוק בהעלם דהתנשאות זאת בלבד, וגם זה בצמצום גדול כמ\"ש ה' מלך גיאות לבש כו' (ולבוש זה היינו ע\"י בחי' המסך<sup data-n=\"4765\">167</sup> שמפסיק בין אצי' לבריאה כידוע ומבואר במ\"א), וכל המדות דאצי' והמשכות<sup data-n=\"4766\">168</sup> לבחי' המ\"ל' דוקא כמו כל הנחלים הולכים אל הים<sup data-n=\"4767\">169</sup> כו').\n<b>והענין</b> הוא דבאמת עיקר ומקור של <span data-k=\"pg\">קצ</span> ּ השפעה והמשכה האלקי' הוא מבחי' החסד עליון דוקא כמ\"ש עולם חסד יבנה, ופי' אמרתי עולם כו'<sup data-n=\"4768\">170</sup> היינו כשעלה ברצונו<sup data-n=\"4769\">171</sup> שזהו בחי' רצון של חסד שמלובש בטעם וחכ' דחסד ומאיר ונמשך הארה",[["4760","162","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה גם לקו\"ת שה\"ש מג, ג. מאמרי אדה\"א נ\"ך ע' שטז. שמות ח\"א ע' קסב. תו\"ח ויצא קסד, ב."],["4761","163","<b>דבר מלך שלטון</b>: קהלת ח, ד."],["4762","164","<b>במאמר יהי רקיע</b>: בראשית א, ו. ראה גם שהיחוה\"א פ\"א."],["4763","165","<b>יהי אור</b>: בראשית שם, ג."],["4764","166","<b>תדשא הארץ</b>: בראשית א, יא."],["4765","167","<b>ה' מלך. . המסך</b>: ראה מאמרי אדה\"א במדבר ח\"ב ע' תריז וע' תש."],["4766","168","<b>והמשכות</b>: אב: נמשכים."],["4767","169","<b>כל הנחלים הולכים אל הים</b>: קהלת א, ז."],["4768","170","<b>עולם כו'</b>: אב: ליתא."],["4769","171","<b>אמרתי. . כשעלה ברצונו</b>: ראה גם מאמרי אדה\"א בראשית ע' טו."]]],[2300540475,"אחת לבד [מ]מדת חסד זה במדת המל' דוקא שהוא מ\"ש והוכן בחסד כס\"א<sup data-n=\"4770\">172</sup> דכס\"א המל' הוא בבחי' החסד דוקא. וא\"כ מה שמתעורר בחסד לבנין העולמות הוא ע\"י מדת המל' והוא מדת מלכותו ית' שמצמצם א\"ע להיות מלך על עולמות כנ\"ל, שבודאי מכח עצם מדה זו לא הי' מתעורר להתנשאות זו שיהי' ב\"ג וימלוך עליהם כו' שאין ערוך לו כלל כנ\"ל, כ\"א כאשר יבא ויומשך במדה זאת של ההתנשאות איזה רצון ועונג בזה דוקא (כי אין בהתנשאות כזאת תענוג ורצון מצד עצמו כי למעלה מדה זאת דהתנשאות הוא ברוממות והתנשאות שמצד עצמו דוקא שנק' מלך יחיד<sup data-n=\"4771\">173</sup> מרומם לבדו כו' כידוע כמו בבחי' מל' דא\"ס עצמו כידוע). ומאין יומשך בזה עונג ורצון א\"א כ\"א מצד בחי' החסד והטוב שבלב אדם העליון שרוצה להטיב חסדו כמו שמטבע הטוב להטיב<sup data-n=\"4772\">174</sup> ע\"כ יומשך מחסד זה לעורר הרצון למעלה במח' להיות מלך כו', וזהו שהוכן בחסד כסאו<sup data-n=\"4773\">175</sup> שמחמת חסד זה נק' מלך כמ\"ש וישב ה' מלך לעולם<sup data-n=\"4774\">176</sup> להמשיך מקור וחיות לכל העולמות בחן ובחסד כו'. וכמו\"כ נמשך מבחי' החכ' והרצון ותענוג שלמעלה מן החכ' לבחי' המל' עד בחי' נה\"י דז\"א ג\"כ ממשיכים למל' כמ\"ש לך ה' הגדולה<sup data-n=\"4775\">177</sup> והגבורה עד כי כל כו' וזהו בחי' יסוד<sup data-n=\"4776\">178</sup> ואח\"כ אמר לך ה' הממלכה כו' (ואמנם מה שאמר לך ה' הממלכה זהו כמ\"ש לך ה' הגדולה כו' דכמו שמדות דחג\"ת כו' דאצי' מתבטלים ממש בעצמות אוא\"ס דלאו מכא\"מ כלל<sup data-n=\"4777\">179</sup> כך מדת המל' מתבטלת בעצמו' המאציל, וא' לך ה' הממלכה שהוא מקור המלוכה עד רום המעלות גם בבחי' מל' דא\"ס שהוא בחי' התנשאו' שמצד עצמו שנק' מלך רב<sup data-n=\"4778\">180</sup> כו' מלך הקדוש<sup data-n=\"4779\">181</sup> כו' כי הרי אינו אלא אחת ממדות דא\"ס שמצד עצמו לאו מכא\"מ כלל כו', ועכ\"ז אמר והמתנשא לכל לראש דפי' לך ה' הממלכ\"ה הוא בהיפוך ג\"כ שממנו נמצא מקור כל [ה]ממלכה והוא להיות מלכותך מל' כ\"ע<sup data-n=\"4780\">182</sup> כו' ונק' מלך מלכי המלכים<sup data-n=\"4781\">183</sup> כו' (כענין המדרש במשל אגוסטוס יושב<sup data-n=\"4782\">184</sup> ומלך עומד כו' כמ\"ש נכון כסאך<sup data-n=\"4783\">185</sup> מאז מעולם כו') וע\"כ מתנשא לכל לראש לכל התנשאות וראש הוא מתנשא עליהם וכענין גאה גאה<sup data-n=\"4784\">186</sup> כו' גאה על גאה כו' (וזהו למעלה גם מבחי' מל' דא\"ס שנק' מקיף הכללי למטה להיות מקיף למקיף דהיינו שה\"ש<sup data-n=\"4785\">187</sup> שמקיף למקיף דשמים שהוא בחי' מח' ורצון הכללי דאבי\"ע שסובב הכל כא' ממש אצי' ועשי' יחד, ואמנם זהו כלל לפרט בבחי' מקיף עכ\"פ ע\"כ גם מקיף למקיף זה שנק' שה\"ש לא יכלכלוהו<sup data-n=\"4786\">188</sup> כו', וזהו המתנשא לכל לראש אף להתנשאות דראש לכל הראשונים כו'",[["4770","172","<b>והוכן בחסד כס\"א</b>: ישעי' טז, ה."],["4771","173","<b>מלך יחיד</b>: נוסח ברכת ישתבח:"],["4772","174","<b>שמטבע הטוב להטיב</b>: נסמן לעיל פ' שמות לד, ג."],["4773","175","<b>כסאו</b>: אב: כסא — ראה לעיל הערה 172."],["4774","176","<b>וישב ה' מלך לעולם</b>: תהלים כט, י."],["4775","177","<b>לך ה' הגדולה</b>: דהי\"א כט, יא."],["4776","178","<b>כי כל. . יסוד</b>: ראה זהר בראשית לא, א. לעיל פ' וארא נג, ד הערה 39."],["4777","179","<b>דלאו מכא\"מ </b>[א: מכל אינון מדות]<b> כלל</b>: ת\"ז בהקדמה (יז, ב)."],["4778","180","<b>מל' דא\"ס. . מלך רב</b>: ראה גם לעיל עה, ב ובהנסמן לשם."],["4779","181","<b>מל' דא\"ס. . מלך הקדוש</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תיז. נ\"ך ע' תקב ובהנסמן בהנ\"ל. לקמן קכב, ב. פ' בשלח קסח, ד. רכו, ד. רלג, ב. תצוה שלא, ד."],["4780","182","<b>מלכותך מל' כ\"ע</b>: תהלים קמה, יג."],["4781","183","<b>מלך מלכי המלכים</b>: ברכות כח, ב. וראה גם לקמן פ' בשלח קנט, ג. ש\"א נו, א. שע\"ת קמה, ד בהערה 41."],["4782","184","<b>במשל אגוסטוס יושב</b>: שמו\"ר ר\"פ כג. ראה שה\"א עו, א ובהנסמן במ\"מ שם לג, ב הערה 20. לקמן קכב, א. פ' בשלח קנט, ג. קסא, ד. ויקהל תו, ג."],["4783","185","<b>נכון כסאך</b>: תהלים צג, ב."],["4784","186","<b>גאה גאה</b>: בשלח טו, א."],["4785","187","<b>שה\"ש</b>: א: שמי השמים."],["4786","188","<b>שה\"ש לא יכלכלוהו</b>: נסמן לקמן רלד, ב."]]],[2300540493,"וד\"ל). וכל זה לפי שלך ה' הממלכה בבחי' מקיף דאו\"ח למעלה שזהו בחי' התנשאות שמצד עצמו בעילוי אחר עילוי עד אין שיעור למעלה שזהו הגבה למעלה יותר מכל התנשאות שעל ההשתל' שנק' עיגול הסובב בעומ\"ר ועומ\"ת כו'. ואמנם ב' מיני <span data-k=\"pg\">382</span> ּ מלוכה הללו דאו\"י ואו\"ח הן ב' מדות דחו\"ג בעומ\"ר ועומ\"ת הכלליים ביותר דהיינו מה דאוא\"ס למעלה מעלה עד אין כו' ולמטה<sup data-n=\"4787\">189</sup> [עד אין] כו' ששניהם שוים ממש קמי' עצמותו ומהותו ית' ממש דלאו מכא\"מ כלל אף לא בעונג הפשוט ועצמי שבמדת ההתנשאות מצד עצמו ממש כנ\"ל וד\"ל.\n[ה<sup data-n=\"4788\">190</sup> ] והנה בכל זה יובן בתוספת ביאור ענין הנ\"ל במא' דמל' לית לה מגרמה כלום ונק' אספקלריא דלא נהרא כו', דהיינו שמדה זאת מובדלת משאר המדות שהן מהות ועצם דבר מה בטבע גשמי' שא\"צ לעורר את המדה כ\"כ להיותה מוטבעת ונטועה בלב האדם מכבר, וא\"צ שיומשך בהם כח ועוז לעצם מציאותם בטבעם כמו למציאת מדת החסד בלב שישנו במציאותו מכבר ויש בנפש האדם תענוג ורצון להתחסד עם הבריות בדרך הטבע וא\"צ רק שיהי' כלי לזה לקבל והוא מי שמבקש החסד כעני וכה\"ג (ואע\"פ שהתעוררות החסד בלב נמשך דוקא מן השכל שבמוח שהוא הטעם לדבר חסד כרחמנות שיש על העני והנצרך לטובה וחסד כו', אין זה מעצם המדה דחסד שהוא עצם הטוב בלב הטוב שמטבעו להטיב לכל רק שהשכל מגלה לו אופן הדבר<sup data-n=\"4789\">191</sup> איך ומה ולמה כו' כמ\"ש במ\"א). אבל מדת ההתנשאות היא רוחניות כרוחניות עצם הנפש כנ\"ל ואינה באה בלב רק בדרך מעבר לפרקים, ואינה מתעוררת כלל מכח עצמה כשאר המדות שבלב, רק שהיא בחי' כלי לקבל מאשר יעוררו אותה ברצון זה להתנשאות מלמעלה, והוא מן המדות שבלב כחו\"ג ותפארת וניצוח וכה\"ג או מצד השכל והרצון והתענוג שבעצם הנפש כנ\"ל שאין זה רק בחי' ההתגלות של כל המדות שנק' י\"ס בכלל שמאיר[י'] במדה זאת מלמעלה, ואז תתחזק במציאותה בהתגלות כמו ברוממות והתנשאות שבא מן הלב בחיצוניות שנק' התפשטות בבחי' יש גדול ובהטלת אימה יתירה שיראה זו נמשך מבחי' הדין שבלב. ונמצא כלול בהתנשאות זו מב' המדות דחו\"ג דוקא וז\"ש מלך במשפט דכלול מחו\"ג דוקא יעמיד ארץ<sup data-n=\"4790\">192</sup> כידוע ומבואר במ\"א וד\"ל. וכך יובן למעלה במדת מל' דאצי' שהוא מדת ההתנשאות למעלה שבמדה זו מקיף לכל העולמות, כמו המתנשא מימו\"ע<sup data-n=\"4791\">193</sup> ובזה נמצא",[["4787","189","<b>דאוא\"ס למעלה. . ולמטה</b>: נסמן לעיל פ' שמות ד, ד."],["4788","190","<b>ה</b>: י: ו. טז: ג."],["4789","191","<b>שהשכל מגלה לו אופן הדבר</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' ג."],["4790","192","<b>מלך במשפט. . יעמיד ארץ</b>: משלי כט, ד. ראה גם מאמרי אדה\"ז על ענינים ע' שצג. ביאוה\"ז בשלח מה, א. פקודי נז, ג. שופטים קכא, ד. בד קודש פ\"ו (ע' 16 — נדפס גם באגרות קודש אדמו\"ר האמצעי ס\"ע רצו ואילך)."],["4791","193","<b>המתנשא מימו\"ע</b>: ע\"פ ברכת יוצר."]]],[2300540511,"מקור חיותם כנ\"ל ע\"ז א' לך ה' הממלכה כו' [ש]בחי' מל' זה מקבל ממדות עליונות דאצי' כמו בחסד שז\"ש והוכן בחסד כסא כנ\"ל, והוא מה שנתעורר רצון ועונג וחסד בלב אדם העליון לחדש אור ושפע חסד לעולמות כמ\"ש כי אמרתי עולם שיהי' עולם מאין ליש חסד יבנה מחסד העליון שמאיר במדת מל' בבחי' רצון למלוכה זו כנ\"ל, וכמו בכל ר\"ה ור\"ה שמתחדש בחי' כתר מל' למעלה שזהו חידוש אור ורצון ועונג העליון במל' דאצי' למעלה והעיקר מבחי' החסד דז\"א כו' (וכידוע שזהו עיקר בנין הנוק' דז\"א שנק' חוה אם כל חי<sup data-n=\"4792\">194</sup> למעלה מאחת מצלעותיו<sup data-n=\"4793\">195</sup> כמ\"ש דאו\"א תקינו לה כו' כמ\"ש ויבן ה' אלקי' את הצלע<sup data-n=\"4794\">196</sup> כו' כידוע דאבא יסד ברתא<sup data-n=\"4795\">197</sup> ואימא אוזיפת מאנהא<sup data-n=\"4796\">198</sup> ה\"ג מנצפ\"ך<sup data-n=\"4797\">199</sup> כו') והרי א' דבאתרהא שקיע רחמי דוקא וזהו ויסגור בשר תחתנה<sup data-n=\"4798\">200</sup> כו' כמ\"ש במ\"א בשרש ענין הנסירה בכלל ובפרט כו'). <span data-k=\"pg\">קצא</span> ּ וזהו שאו' י\"פ דמלכיות וא' אמרו לפני מלכיות שתמליכוני עליכם כו' כדי לעורר הרצון והעונג<sup data-n=\"4799\">201</sup> בהתנשאות על עולמו[ת] שאין ערך כלל אל מל' דאצי' כמו שהוא למעלה מעלה (במל' דא\"ס שנק' מלך מרומם [לבדו] מלך הקדוש כנ\"ל). ונמצא דאין בחי' מדת המל' מאירה בכחות די\"ס פרטי' דרצון ועונג וחו\"ב וחו\"ג וכה\"ג מכח עצמה כלל כשאר המדות כחסד שהוא מהות עצם בפ\"ע וא\"צ להתעוררות כ\"כ מלמעלה כנ\"ל, רק ע\"י המשכת האורות העליוני' דאצי' דוקא כנ\"ל ולכך א' דלית לה מג\"כ ולא נהרא מכח עצמה (כאור הלבנה שמקבלת מאור השמש), כ\"א מה שמשפיעי' לה מלמעלה שהוא בחי' הרצון ועונג דע\"י וא\"א ואו\"א וז\"א שזהו כללות הג' קוין דאצי' כידוע, ובחי' המל' עומדת למטה תחת קו האמצעי דת\"י<sup data-n=\"4800\">202</sup> שממנו נמשך כללות כל האורות העליונים כמו בר\"ה שנבנה המל' בחסד דאברהם ובגבורות דיצחק והעיקר בבחי' ת\"ת דיעקב כידוע בכוונות דר\"ה כו' וד\"ל.\n[ו] <b>ומעתה</b> יובן גם פי' הב' דלית לה מגרמה כלום דהיינו רק מה שמקבלת מלמטה מן המלאכי' ונשמות ועולמות דבי\"ע כנ\"ל, דהנה מאחר שמבואר למעלה במדה זו דהתנשאות האלקו' דמל' דאצי' למעלה דגם שהוא בבחי' ריחוק מקום בבחי' מקיף מלמעלה, עכ\"ז בהתנשאות זו נמשך עצם המקור לכל חיות העולמות כמ\"ש יראת ה' לחיים כו' שביראת ה' דמל' עיקר מקור כל החיים העליונים והתחתונים כו' כנ\"ל, א\"כ הרי יובן מזה דגם אחר שנתהוו כל ה[נ]בראים מאין ליש",[["4792","194","<b>חוה אם כל חי</b>: בראשית ג, כ [בדילוג]."],["4793","195","<b>מאחת מצלעותיו</b>: שם ב, כא. ראה ע\"ח שער הכללים פי\"ג."],["4794","196","<b>דאו\"א תקינו לה. . ויבן. . הצלע</b>: נסמן לעיל פט, ג."],["4795","197","<b>דאבא יסד ברתא</b>: נסמן לעיל פ' שמות מז, ב."],["4796","198","<b>ואימא אוזיפת מאנהא</b>: ראה זהר בהקדמה ב, א. מאמרי אדה\"א דברים ח\"א ע' רלו. וש\"נ."],["4797","199","<b>ה\"ג מנצפ\"ך</b>: נסמן לעיל פ' שמות יט, ג."],["4798","200","<b>דבאתרהא שקיע רחמי. . ויסגור בשר תחתנה</b>: בראשית ב, כא. זהר (אד\"ר) נשא קמב, סע\"ב. ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקד ואילך."],["4799","201","<b>הרצון והעונג</b>: א: העונג והרצון."],["4800","202","<b>המל' עומדת. . דת\"י</b>: נסמן לעיל צא, ג הערה 229."]]],[2300540529,"מבחי' דבר מלך שלטון כנ\"ל יכולים לעורר בהעלאת מ\"ן שלהם בביטול היש לאין בקבלת עומ\"ש שלימה להמשיך בחי' כתר מל' דאצי', דהיינו שיעוררו במדת מל' דאצי' בחי' הרצון ועונג למלוכה שהוא בחי' ההתנשאות על העולמות כמו וישב ה' מלך לעולם כו' כמו באמרם ה' מלך וימלוך<sup data-n=\"4801\">203</sup> כו', וכמו שידוע באדה\"ר שא' ה' מלך גיאות לבש כו' ביום הו' שנברא בו<sup data-n=\"4802\">204</sup> וקיבל עליו עומ\"ש שלימה כו' אז המשיך למעלה בחי' כתר מל' כו', וכמו שאו' כתר יתנו לך כו' ובפרט הנשמות שנק' אדם כו' כענין אמרו לפני מלכיות כו' ולכך או' ועמ\"י קבוצי מטה<sup data-n=\"4803\">205</sup> בציור אדם כמ\"ש במ\"א וד\"ל (ולפי כ\"ז יתפרש מה שא' דכתר מל' איהו כ\"ע בב' אופנים בבחי' או\"י מאור הכתר במל' משום דנתחב\"ס דוקא ובבחי' או\"ח מלמטלמ\"ע דנסב\"ת<sup data-n=\"4804\">206</sup> והוא בבחי' הרצון ועונג העצמות ממש כנ\"ל וד\"ל).\n[ז<sup data-n=\"4805\">207</sup> ] והנה אחר כל הקדמות הנ\"ל יש להבין שרש ענין פסח ומצה, בהיות ידוע בכללות הענין דפסח שהוא בחי' הדילוג<sup data-n=\"4806\">208</sup> כמ\"ש ופסח ה' על<sup data-n=\"4807\">209</sup> כו' (דמה שבשה\"ש א' קול דודי מדלג<sup data-n=\"4808\">210</sup> כו' מפורש בתו' להיכן דילג על הפתח שהוא בחי' המל'<sup data-n=\"4809\">211</sup> שה[י]א האמונה הפשוטה שנק' נקודה תח\"י<sup data-n=\"4810\">212</sup> ה\"א לחמא עניא די דלי\"ת יו\"ד<sup data-n=\"4811\">213</sup> כידוע), והוא מה שראה הדם על המשקוף וב' המזוזות<sup data-n=\"4812\">214</sup> שזהו<sup data-n=\"4813\">*215</sup> בחי' כח\"ב<sup data-n=\"4814\">215</sup> דמל' ששרשם בג\"ר כח\"ב דע\"י וא\"א כו') וענין הדילוג הזה זהו כמ\"ש קול דודי כו' מדלג על ההרים כו' דהיינו שהדילוג הוא שלא כסדר והדרגה בהשתלשלו' דע\"ס מעצמות המאציל שמוחי' דחו\"ב מאירים במדות ע\"י צמצום והעלם דבחי' מיצר הגרון (וכמשי\"ת), ודילוג הזה הי'<sup data-n=\"4815\">216</sup> מאור הכתר בחו\"ב מבחי' ג\"ר דכח\"ב שיאירו בדילוג גדול מן המוחין למדות שבלב שלא ע\"י צמצום והעלם דמיצר הגרון כו'. וז\"ש בצאת ישראל ממצרים<sup data-n=\"4816\">217</sup> <span data-k=\"pg\">384</span> ּ מבחי' מיצר מ\"י דגרון וכן נק' מיצר י\"ם<sup data-n=\"4817\">218</sup> שהן<sup data-n=\"4818\">219</sup> מוחין דחו\"ב שנק' י\"ם ומ\"י כידוע שמתצמצמי' מאד במיצר הגרון (שהוא הקול כידוע וית' בסמוך).\n<b>ואמנם</b> הנה תחלה יש להבין מהו בחי' המוחי' דחו\"ב דאצי' כמו שהן במקורם איך שנשתלשלו מעצמות המאציל שנק' חכים ולא בחכ' ידיעא<sup data-n=\"4819\">220</sup> כו', דהנה להבין מה שא' חכים ולא בחכ' כו' מבין ולא בבינה ידיעא שאיך יתפרש זה בחו\"ב שבעצמות א\"ס ב\"ה. הנה יובן בדרך ידיעת המציאות לבד מבחי'",[["4801","203","<b>באמרם ה' מלך וימלוך</b>: מוסף לר\"ה."],["4802","204","<b>באדה\"ר שא'. . ביום הו' שנברא בו</b>: תהלים צג, א. ראה פדר\"א פי\"א. מאמרי אדה\"א דברים ח\"ג ע' תשס. וש\"נ. תו\"ח וישלח קפא, ד ובהערה 64."],["4803","205","<b>כתר. . ועמ\"י </b>[א: ועמך ישראל]<b> קבוצי מטה</b>: קדושת כתר. ראה גם לעיל צז, ב ובהנסמן שם."],["4804","206","<b>דנתחב\"ס. . דנסב\"ת</b>: ראה ס\"י פ\"א, מ\"ז."],["4805","207","<b>ז</b>: טז: ד."],["4806","208","<b>דפסח. . הדילוג</b>: נסמן לעיל פז, א."],["4807","209","<b>ופסח ה' על</b>: בא יב, כג."],["4808","210","<b>קול דודי מדלג</b>: שה\"ש ב, ח [בדילוג]."],["4809","211","<b>הפתח. . המל'</b>: ראה לעיל צא, א ובהנסמן לשם. צב, ג (ספ\"ו)."],["4810","212","<b>המל'. . נקודה תח\"י </b>[א: תחת יסוד]: נסמן לעיל פ' וארא עא, ד הערה 30."],["4811","213","<b>ה\"א לחמא עניא די דלי\"ת יו\"ד</b>: נוסח ההגדה. ראה פע\"ח (שער חה\"מ) שכ\"א, פ\"ז. שה\"א פי\"ב."],["4812","214","<b>שראה הדם. . המזוזות</b>: בא יב, כג."],["4813","*215","<b>שזהו</b>: אוצ\"ל: (שזהו."],["4814","215","<b>המשקוף וב' המזוזות. . כח\"ב</b>: ראה לעיל צא, סע\"ג ואילך."],["4815","216","<b>הי'</b>: אב: הוא."],["4816","217","<b>בצאת ישראל ממצרים</b>: תהלים קיד, א."],["4817","218","<b>ממצרים. . מיצר מ\"י. . י\"ם</b>: נסמן לעיל פ' שמות לז, ב."],["4818","219","<b>שהן</b>: אב: שהוא."],["4819","220","<b>חכים ולא בחכ' ידיעא</b>: ת\"ז בהקדמה (יז, ב). ראה גם לקמן פ' יתרו רסו, סע\"ד ואילך."]]],[2300540547,"חו\"ב שבנפש האדם שהחכ' נק' אין ובינה נק' יש<sup data-n=\"4820\">221</sup>, והוא ענין הברקת אור השכל שנק' התחכמות וכה\"ג ממקורה מלמעלה מן השכל ונמשך לבינה להיות נתפס ומובן בהשגה ממש שנק' יש בהתפשטות אורך ורוחב כידוע. אך כ\"ז בחו\"ב שבאדם בדבר מה שיכול להשיגו בכלי מוחו ודעתו במהות שלו כמו חכ' ושכל שיבינו וישיגו ממש או שישיג בחכ' של חכם גדול שיש לו ערך ויחוס עם שכלו ודעתו. אבל למעלה באורות דאצי' וכה\"ג במה שנשתלשל בבי\"ע אין לחו\"ב שבאדם שום השגה ותפיסא במהות כלל כנ\"ל, רק בבחי' השגת המציאות לבד ולא במהות כלל כנ\"ל באורך, דהיינו שישיג שיש מציאות דחו\"ב גם למעלה באצי' אבל אין זה השגה במהו\"ע דחו\"ב דאצי' כלל כנ\"ל, וכך כ\"ש וק\"ו א\"א לומר שישיג אדם בחו\"ב שבנפשו לאא\"ס עצמו כמו שהוא רק בדרך השגת המציאות לבד כנ\"ל. דהנה כמו שבחו\"ב דאדם למטה לא ישיג למהו\"ע נפשו ממש כמו שהיא להיותה למעלה הרבה מכח החו\"ב שנמשך ונסתעף מן עצם הנפש עד שנק' נפש השכלי'<sup data-n=\"4821\">*222</sup>, כי הנפש עצמה למעלה גם מן כח הרצון ועונג כידוע שהנפש עצמה אור פשוט והיולי בתכלית מושלל לגמרי מן כל הכחות המסתעפי' ממנה כו', וא\"כ איך יכול להשיג בחו\"ב שבנפשו לבחי' אור עצמות נפשו ממש רק שיכול הוא להשיג איכותה בבחי' השגת המציאות לבד דהיינו איך שהנפש היא רוחניות ומושללת מכל תואר גשם והגבלה בכלי כו' וכה\"ג וגם זה עצמו איך שכחות שלה אף חו\"ב ורצון כלא חשיבי לגבה כו'.\n<b>וע\"ד</b> כ\"ז יובן ג\"כ למעלה בדוגמא דדוגמא עכ\"פ בבחי' חו\"ב דאצי' שנמשכו בגילוי מן ההעלם דחו\"ב שבעצמו' המאציל שנק' חכים ולא בחכ' כו' כנ\"ל דהגם שבחי' אורות הללו דחו\"ב דאצי' אף שהן בבחי' כלים מוגבלים (כמו חכ' מוחא<sup data-n=\"4822\">222</sup> כו' דמוחא זה היינו כמו כלי מוח החכ' באדם שהוא קר ולח<sup data-n=\"4823\">223</sup> ומסוגל לצורה זו דאור החכ' להשכיל כל שכל מן ההעלם לגילוי כמו נקודה כנ\"ל), עכ\"ז הרי א' דאיהו וחיוהי וגרמוהי כו' כולא חד בבחי' א\"ס שהן או\"כ, ובפרט או\"כ דחו\"ב במוחי' דחו\"ב שע\"ז א' קנה חכ' קנה [בינה<sup data-n=\"4824\">224</sup> ב\"פ קנה] גימ' ש\"י<sup data-n=\"4825\">225</sup> ששרשם מאור הכתר שהחכ' מאין תמצא<sup data-n=\"4826\">226</sup> כו' כידוע. וחו\"ב הללו הן מקוריים כלליים לכל בחי' חו\"ב שנמצא למטה עד חו\"ב שבנפש אדם כמו חכמת שלמה שא' וה' נתן חכמה לשלמה הרבה מאד<sup data-n=\"4827\">227</sup> בבחי' א\"ס<sup data-n=\"4828\">228</sup> כח\"ע דאצי' כו' (דחכמת שלמה הוא בחי' ח\"ת<sup data-n=\"4829\">229</sup> ששרשה בח\"ע<sup data-n=\"4830\">*230</sup> דחכ' בראש כידוע). אך א\"א לומר דחו\"ב הללו הן",[["4820","221","<b>שהחכ' נק' אין ובינה נק' יש</b>: ראה מאמרי אדה\"א בראשית ע' ב. וש\"נ. דרושי חתונה ח\"ב ע' תעג."],["4821","*222","<b>נפש השכלי'</b>: ראה גם לקמן קא, ד. קלב, ג. וש\"נ. פ' בשלח רב, א. יתרו רסז, ג. תרומה שיד, א. תצוה שמא, ג. פקודי תנג, א. תס, ג."],["4822","222","<b>חכ' מוחא</b>: נסמן לעיל כח, ד."],["4823","223","<b>מוח החכ'. . קר ולח</b>: נסמן לעיל כז, ג."],["4824","224","<b>קנה חכ' קנה [בינה</b>: משלי ד, ה."],["4825","225","<b>ב\"פ קנה] גימ' ש\"י</b>: נסמן לעיל פ' שמות לג, ג."],["4826","226","<b>שהחכ' מאין תמצא</b>: איוב כח, יב. ראה מאמרי אדה\"א דברים ח\"ג ע' תשעט. וש\"נ. תו\"ח בראשית ז, ד ובהערה 49. לקמן פ' בשלח רה, ג. תרומה שיב, ב. תצוה שמז, א. שסא, ג. ויקהל תלו, ג."],["4827","227","<b>וה' נתן חכמה לשלמה הרבה מאד</b>: חיבור ב' כתובים מלכים-א ה, כו. ט."],["4828","228","<b>חכמה לשלמה. . בבחי' א\"ס</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תנח."],["4829","229","<b>דחכמת שלמה. . ח\"ת</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תנט. וש\"נ. תו\"ח בראשית לב, ג ובהערה 26."],["4830","*230","<b>ח\"ת ששרשה בח\"ע</b>: ראה גם ביאוה\"ז וירא י, ג. אמור פא, ב. מאמרי אדה\"ז על מארז\"ל ע' רו. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תקס ואילך. דברים ח\"ב ע' שפז."]]],[2300540564,"בבחי' החו\"ב להבין ולהשכיל דבר מה שחוץ לעצמו כמו דוגמא דחו\"ב בנפש אדם כחכמת שלמה שדיבר דברי חכמה בכל הדברים כמ\"ש וידבר ג\"א משל<sup data-n=\"4831\">230</sup> כו' וידבר על העצים<sup data-n=\"4832\">231</sup> מן הארז כו', שהרי <span data-k=\"pg\">קצב</span> ּ למעלה באצי' הוא תכלית היחוד האמיתי בא\"ס עצמו דאיהו וחיוהי חד כיחוד עצם אורות דחו\"ב בעצמות הנפש דאדם ואין דבר חוץ מעצמו' המאציל כו' (כשלהבת הקשורה בגחלת וכה\"ג), וא\"כ איך שייך לומר לשון חכים ומבין באיזה דבר מה כו' (ואם הכוונה על עצם אור החו\"ב שבא\"ס עצמו דלתבונתו אין מספר<sup data-n=\"4833\">232</sup> כלל שהוא בחי' כח חכמתו העצמי שבחכ' דתורה הקדומה<sup data-n=\"4834\">233</sup> שנק' משל הקדמוני<sup data-n=\"4835\">234</sup> שלמעלה מאורות דחו\"ב שנאצלו בכלים [ב]חכ' מוחא כו', הרי ע\"ז א' חכים ולא בחכ' ידיעא כו' (כמשי\"ת), אלא צריך לומר דהכוונה הוא בבחי' חו\"ב דאצי' שהוא שנאצל אור הח[ו\"ב] להשכיל ולהבין בעצמות אור א\"ס כמו דוגמא דחו\"ב שבאדם שיכול להשיג באמיתת אור עצמות הנפש כנ\"ל, אך זהו רק בבחי' השגת המציאות לבד ובדרך שלילה לבד כנ\"ל, כך יובן למעלה דמה שנק' חכים באו\"כ אינו אלא להשיג בכח החכ' דאצי' (שנק' אור אבא<sup data-n=\"4836\">235</sup> ) בהשגת המציאות לבד בעצמות אוא\"ס דהיינו במה שיש מציאות דאוא\"ס פשוט בתכלית כו' ולא שישיגו בחי' חו\"ב למהות ועצמות דא\"ס כלל שהרי אמר לית מח' תפיסא בי' כלל, ופי' [מחשבה] חש\"ב מ\"ה<sup data-n=\"4837\">236</sup> דחכ' כולל ב' בחי' דחו\"ב דלית שום מח' ת\"ב אפי' מח' הקדומה [דח\"ע הקדומה] שלפני האצי' כו' אלא רק בהשגת המציאות לבד כנ\"ל, מאחר שגם בחי' חו\"ב שלפני האצי' נמשך מעצמות אוא\"ס הפשוט בתכלית שלמעלה מכל מציאות דבר מה אף לא בהעלם דחכ' ורצון ועונג וכה\"ג וכנ\"ל וכמ\"ש ולאו מכא\"מ כלל כנ\"ל, וא\"כ איך יושג מהו\"ע ית' בחו\"ב דאצי' ואף לא בחו\"ב הקדומה שכלול בעצמות (כחו\"ב שכלולים בעצמות הנפש דכלא חשיבי רק שמתלבשת בהם בבחי' עצמיות (כמשי\"ת) (ועכ\"ז בחו\"ב דתושב\"כ ושבע\"פ נתפס מהו\"ע ית' ממש כמ\"ש ואהי' אצלו אמון שעשועי'<sup data-n=\"4838\">238</sup> עצמי' כו' בנפש<sup data-n=\"4839\">237</sup> השכלית שנק' עצם הנפש ע\"ש כח השכל דהוא המדע<sup data-n=\"4840\">239</sup> כו') שהוא שדיבר ג\"א משל שהן הכל בתוה\"ק שנק' משל הקדמוני כו', וגם בחו\"ב זו שנק' חו\"ב דלא ידיעא כלל כי המה כלולים בעצמות א\"ס ממש כמ\"ש והחכמה מאין כו' כלומר מאין והיכן שרשה דלא נודע שרש מציאותה כלל ואיזה מקום בינה<sup data-n=\"4841\">240</sup> בשרשה הראשון, אך אלקים הבין דרכה דחכ' כמו שהיא בשרשה העצמית והוא ידע את מקומה<sup data-n=\"4842\">241</sup> דבינה כו' כמו שיודע",[["4831","230","<b>וידבר ג\"א משל</b>: מלכים-א ה, יב."],["4832","231","<b>וידבר על העצים</b>: מלכים-א ה, יג."],["4833","232","<b>דלתבונתו אין מספר</b>: תהלים קמז, ה."],["4834","233","<b>דתורה הקדומה</b>: נסמן לעיל ב, ד."],["4835","234","<b>דתורה. . משל הקדמוני</b>: נסמן לעיל ח, ב."],["4836","235","<b>החכ'. . אור אבא</b>: ראה ע\"ח (שער עתיק) שי\"ב, פ\"א. מאמרי אדה\"א בראשית ע' א. וש\"נ. ש\"א ד, א הערה 9."],["4837","236","<b>[מחשבה] חש\"ב מ\"ה</b>: נסמן לעיל פ' וארא ע, ג."],["4838","238","<b>ואהי' אצלו אמון שעשועי'</b>: משלי ח, ל [בדילוג]."],["4839","237","<b>(ועכ\"ז. . בנפש</b>: אב: ועכ\"ז. . (כנפש."],["4840","239","<b>דהוא המדע</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ב, ה\"י. שמונה פרקים להרמב\"ם בסופו."],["4841","240","<b>והחכ' מאין. . ואיזה מקום בינה</b>: איוב כח, יב."],["4842","241","<b>אלקים הבין דרכה. . והוא ידע את מקומה</b>: איוב שם כג."]]],[2300540580,"אדם בחו\"ב [שבנפשו] בידיעת עצמות הנפש, ואמנם<sup data-n=\"4843\">242</sup> למעלה נק' [חכים] ולא בחכמה ידיעא דא\"י להשיג בידיעת עצמות אוא\"ס ממש רק במציאות לבד כנ\"ל וד\"ל, ועכ\"ז יש בכח דחו\"ב שבעצמות אוא\"ס שבנפשו<sup data-n=\"4844\">243</sup> שנאצלו באצי' לידע כל מה שעתיד להיות באבי\"ע בגילוי מן ההעלם ע\"י קו\"ח שנק' קו המדה כו' כמ\"ש במ\"א ששיער בעצמו בכח<sup data-n=\"4845\">244</sup> כל מה שעתיד להיות בפועל בגילוי מן ההעלם כו', שזהו בחי' המח' וחכ' הכללי' כמו שכולם בחכ' עשית בחכ' דמע\"ב כך הוא בכללות דקו\"ח כידוע, ועד\"ז הוא גם בחו\"ב דאצי' לגבי בי\"ע כו' שזהו שרש חו\"ב דמע\"ב, ועכ\"ז א' דלמחת\"ב כלל להשיג במהו\"ע ית' (אע\"פ שבידיעת עצמו דוקא הוא יודע את הכל ולא בידיעה שחוץ ממנו כמ\"ש הרמב\"ם<sup data-n=\"4846\">245</sup> ומבואר במ\"א) וד\"ל.\n[ח<sup data-n=\"4847\">246</sup> ] והנה מעתה יש להבין בפרט ענין דב' מדרגות דחו\"ב דאצי' ומהו ההפרש בין חכ' <span data-k=\"pg\">386</span> ּ לבינה שנק' אי\"ן וי\"ש כנ\"ל, דהנה ידוע שהחכ' היא בבחי' ראי'<sup data-n=\"4848\">247</sup> מקרוב [כ]ראיית העין שרואה במהו\"ע של הדבר (וע\"כ נק' החכמים בשם עיני העדה<sup data-n=\"4849\">248</sup> כו' וא' איזהו חכם<sup data-n=\"4850\">249</sup> הרואה את הנולד מה שעתיד להיות הוא רואה בכח שכלו וחכמתו שזהו כרואה בעין ממש ונק' עין השכל כידוע וד\"ל), וזהו ענין ההשגה במהות הדבר כנ\"ל שזהו ע\"י בחי' החכ' דוקא שהיא בבחי' ראי' מקרוב שרואה במהות הדבר עצמו כמו שהוא ממש. אבל בחי' בינה הוא בבחי' שמיעה<sup data-n=\"4851\">250</sup> מרחוק בלבד שאינו רואה במהות ועצם הדבר כמו שהוא כלל, רק שע\"י ששומע ומבין כל אשר יאמרו ויסבירו לו פרטי אותו<sup data-n=\"4852\">251</sup> הדבר עד שיכוין בדעתו ושכלו להשיג במציאות הדבר כמו שהוא רואה אותו כו', דאע\"פ שיוכל להשיג הדבר בשכלו ע\"פ השמועה ששומע ומבין כמו שהוא באמיתת מהותו ממש, מ\"מ אינו דומה שמיעה מרחוק לבחי' הראי' בעין מקרוב שרואה מהו\"ע הדבר ממש כמו שהוא, וכמו שאינו דומה מי שראה את המלך כמו שהוא בכבודו ובעצמו עם מי ששמע מאופני פרטי כבודו וגדלו, דאע\"פ שיכול להיות שגם ע\"פ השמועה ששמע מזולתו<sup data-n=\"4853\">252</sup> שראה את המלך בכל פרטי אופני איכות ומהות המלך ממש כמו שהוא באמתתו יוכל להבין ולהשכיל ולעמוד על ידיעת עצם ומהות המלך כמו שהוא, עכ\"ז אינו דומה שמיעה זו לראי' בעין מקרוב כשרואה למהות המלך ממש אע\"פ שאין לו",[["4843","242","<b>ואמנם</b>: י: נסמן כאן פ\"ח."],["4844","243","<b>שבנפשו</b>: אב: קודם."],["4845","244","<b>ששיער בעצמו בכח</b>: מובא לקמן פ' בשלח קעח, ג בשם הע\"ח. ראה מק\"מ לזהר בראשית טו, א. מאמרי אדה\"א קונטרסים ע' רא. וש\"נ."],["4846","245","<b>שבידיעת עצמו. . הרמב\"ם</b>: הל' יסוה\"ת פ\"ב, ה\"ט ואילך. ראה גם מאמרי אדה\"א שם. שעה\"י קכג, א."],["4847","246","<b>ח</b>: י: ראה לעיל הערה 242. טז: ה."],["4848","247","<b>שהחכ' היא בבחי' ראי'</b>: נסמן לעיל פ' שמות כז, ג."],["4849","248","<b>נק' החכמים בשם עיני העדה</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א פ' בשלח ע' רסד ובהנסמן במ\"מ לשם. מאמרי אדה\"א נ\"ך ע' קסד. וש\"נ. ש\"א מ, א. שה\"א מג, ב. צג, א. לקמן פ' תצוה של, א."],["4850","249","<b>איזהו חכם</b>: ראה גם לעיל יא, א. וש\"נ."],["4851","250","<b>בינה הוא בבחי' שמיעה</b>: נסמן לעיל כז, ג."],["4852","251","<b>אותו</b>: א: אופן."],["4853","252","<b>מזולתו</b>: א: גדולתו ממי."]]],[2300540596,"תוספת וחידוש במוחו ולבו דבר וח\"ד<sup data-n=\"4854\">253</sup> כלל במה שראהו מכמו שהבין וידע בתחלה ע\"פ השמועה, מ\"מ אינו דומה שמיעה מרחוק לראי' מקרוב שא\"א להשיג בשמיעה מרחוק כמו שהוא במהו\"ע ממש רק בהשגת מציאותו לבד ולא במהותו כלל כו'. וכך יובן ענין ההפרש בין ראי' דחכ' לשמיעה דבינה דבבחי' בינה במוח והשגה<sup data-n=\"4855\">254</sup> והתפיסא יוכל להבין ולהשכיל הדבר רק במציאותו מרחוק לבד ולא במהותו כלל, אבל בבחי' מוח דחכ' שהוא בחי' הברקת עין השכל הרי הוא למעלה מהבנה והשכלה בהשגה ותפיסא שאינו עדיין בבחי' השגה שכלי' כלל, רק בהברקת אור השכל שנק' אור המאיר שרואה בו במהות ועצמות הדבר, ומה שצריך להבינו בשכל והשגה נסקר בו בראי' מקרוב בעצם הדבר שלא יוכל לכוין לאמתת עצם הדבר ע\"י השגה והבנה כלל כנ\"ל. וכמו החכם הרואה בעי\"ן השכל מה שעתיד להיות כו' שא\"א להיות זה בהשגה והבנה דבינה כ\"א בראיית עין השכל, וכך מה שהחכמים נק' עינ\"י העד\"ה, וכך הי' מדרגת משה שהי' בבחי' ראי' עי\"ן דחכמה כמ\"ש וירא ראשית<sup data-n=\"4856\">255</sup> כו' שהי' רואה במהו\"ע אלקות בעין השכל למעלה מהשגה והבנה כו' (כמ\"ש בו אשר ידעו ה' פא\"פ<sup data-n=\"4857\">256</sup> כו') וא' בר\"מ דבעין השכל דבלבא<sup data-n=\"4858\">257</sup> אתחזי כולא כו'. ואע\"פ שמבואר למעלה דא\"א להיות השגת המהות בעצמות אוא\"ס וגם לא באורות דע\"ס דאצי' אף לא במל' דאצי' רק בהתלבשות בבי\"ע ע\"י מסך כו'. אמנם הרי מבואר למעלה בשרש ענין הנבואה שהי' בבחי' השגת המהות דאצי' דוקא רק שהוא בבחי' נו\"ה דאצי' לבד שמלובש בנו\"ה דבריאה ויצי' כ[מו ב]ישעי' ויחזקאל כו' בלי העלם ולבוש דמסך כלל, רק שנק' מראה דמות כבוד הוי' דאצי' כאספקלריא דלא נהרא רק כפי המראה הנראה בה בבחי' או\"ח כמו אור <span data-k=\"pg\">קצג</span> ּ הנכפל<sup data-n=\"4859\">258</sup> כידוע שאינו רואה עצם הדבר ממש רק דמותו וצלמו בלבד (וכמו הפנים הנראים במים צלולים כמ\"ש כמים הפא\"פ<sup data-n=\"4860\">259</sup> כו'). ומה שיש כמה צדיקים בדור דחזו אפי שכינה בכל יום והן ל\"ו<sup data-n=\"4861\">260</sup> כו', וכן מ\"ש לחזות בנועם ה'<sup data-n=\"4862\">261</sup> כו' וכמו במ\"ת שראו פב\"פ<sup data-n=\"4863\">262</sup> פני הוי' כו' כמ\"ש<sup data-n=\"4864\">263</sup> וכל העם רואים<sup data-n=\"4865\">264</sup> כו' כל זה<sup data-n=\"4866\">265</sup>, וכה\"ג ויראו את אלקי ישראל<sup data-n=\"4867\">266</sup> ויחזו את האלקי'<sup data-n=\"4868\">267</sup> כו' וכמו בקי\"ס שא' זה אלי<sup data-n=\"4869\">268</sup> כו' אע\"פ שאין זה בהשגת המהות כמראה הנבואה, מ\"מ זהו בבחי' הראי' בעין השכל בראי' מקרוב עכ\"פ שהוא כמו בראיית העין ממש כמו כי עין בעין<sup data-n=\"4870\">269</sup>",[["4854","253","<b>דבר וח\"ד [ וחצי דבר]</b>: א: דבר מה. ב: אפי' דבר אחד."],["4855","254","<b>והשגה</b>: א: ההרגשה. ב: ההשגה."],["4856","255","<b>וירא ראשית</b>: ברכה לג, כא. ראה גם לעיל פ' שמות מו, ד. וש\"נ."],["4857","256","<b>אשר ידעו ה' פא\"פ</b>: ברכה לד, י."],["4858","257","<b>דבעין השכל דבלבא</b>: נסמן לעיל עט, ג."],["4859","258","<b>אור הנכפל</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשמא. ס\"ע תשעח. תקע\"א ע' מ (בשם ס' האלם). וש\"נ. ש\"א מד, ב. נא, א. מאמרי אדה\"א שמות ח\"א ע' קסג."],["4860","259","<b>כמים הפא\"פ</b>: משלי כז, יט [ושם: לפנים — ראה לקמן פ' בשלח קצט, א. משפטים רצ, ב. תרומה שיב, א. שטז, ד. תצוה שעד, ג. שע\"ת טו, ד. מאמרי אדה\"א נ\"ך ע' ע. וש\"נ]."],["4861","260","<b>צדיקים. . ל\"ו</b>: ראה להלן קב, ד. שע\"ת נו, ד. תו\"ח ח\"ש קלא, ד."],["4862","261","<b>לחזות בנועם ה'</b>: תהלים כז, ד."],["4863","262","<b>במ\"ת שראו פב\"פ</b>: ואתחנן ה, ד."],["4864","263","<b>כמ\"ש</b>: ב: (וכמ\"ש. וראה בסמוך הערה 270."],["4865","264","<b>וכל העם רואים</b>: יתרו כ, טו. ראה גם מאמרי אדה\"א במדבר ח\"ב ע' תיח."],["4866","265","<b>כל זה</b>: א: ליתא."],["4867","266","<b>ויראו את אלקי ישראל </b>[א: ניתוסף: כו']: משפטים כד, י."],["4868","267","<b>ויחזו את האלקי'</b>: משפטים שם, יא."],["4869","268","<b>זה אלי</b>: בשלח טו, ב."],["4870","269","<b>כי עין בעין</b>: שלח יד, יד [בדילוג — ראה לקמן פ' יתרו ערב, א. שע\"ת קמב, ד. מאמרי אדה\"א שמות ח\"א ע' כב. וש\"נ. נ\"ך ע' תנח. וש\"נ]."]]],[2300540611,"נראה אתה כו', וכמו<sup data-n=\"4871\">270</sup> שמצינו רבים בכתובים שא' וירא כבוד ה'<sup data-n=\"4872\">271</sup> אל כל העם כו' אע\"פ שאין זה כ[מו] מראה הנבואה ואדרבה זהו ביתרון מעלה במ\"ש עין בעין כו' ומראה הנבואה הוא בחלום וחזיונות הלילה או כמראה וחידוש<sup data-n=\"4873\">272</sup> כו').\n<b>אך</b> באמת לפי הכלל הנ\"ל בבחי' החכ' שהוא בבחי' ראי' מקרוב במהותו<sup data-n=\"4874\">273</sup> דוקא כנ\"ל, א\"כ הרי יכול [להיות] בחי' ראי' זו בכל ניצוץ מישראל שיש בו בחי' חו\"ב בנה\"א כידוע ובחי' החכ' הוא בחי' הראי' מקרוב במהו\"ע אלקות שנק' לאסתכלא ביקרא דמלכא<sup data-n=\"4875\">274</sup> כו' כידוע. וזהו ג\"כ בבחי' עין השכל שבלב שרואה בראיית עין השכל איכות ומהות אור העצמות אלקות בבחי' ממלא וסובב כו', למעלה מבחי' ההשגה וההשכלה בהסבר דבינה כו', כמו שמסביר איך שמחי' את הכל מאין ליש כמשל גילוי החיות דנפש בגוף או בצרופי אותיות הדבור וכה\"ג, שמשל זה אע\"פ שמקרב אל השכל יותר זהו בא בהשגה והבנה במהות השכלה מדבר המשל הזה שזהו עצמו בחי' לבוש גס להעלים אמיתת הדבר כמו שהוא למעלה באמת, אע\"פ שמכוון אופן המשל הזה כמו שהוא למעלה באותיות שבורא מאין ליש שזהו גילוי אור וחיות האלקי בעולמות כידוע, מ\"מ אינו דומה שמיעה לראי' מקרוב, שהשכל והשגה זו עפ\"י משל למעלה נק' שמיעה מרחוק שמשיג איכות המציאות דאלקות לבד, ולא שישיג במהו\"ע האלקו' כמו שהוא מחי' את הכל באותיות העליונים האלקיים, רק ע\"פ בחי' ראיית עין השכל שבלב זהו כרואה במהו\"ע האלקי' כו' שזהו ענין לאסתכלא כו' כמ\"ש במ\"א באריכות וד\"ל.\n<b>וע\"פ</b><sup data-n=\"4876\">275</sup> הפרש זה בין חכ' לבינה שהחכ' נק' אין בראי' המהות ובינה נק' יש בהשגה מרחוק בלבד כמו שא' שמעתי שמעך יראתי<sup data-n=\"4877\">276</sup> כו', ע\"כ יש הפרש בתולדות המדות שמתהווה מחכ' או מבינה, דמבחי' השמיעה בהתבוננות מרחוק כמו ע\"פ משלים ודמיונות השכל יולד התשוקה מורגשת בלב להיות נכלל ודבוק באלקי' חיים שמחיה את הכל כי משיג בטוב שהוא עיקר ומקור הכל כו', ובכל דבר שמרחוק דוקא יגבר התפעלות התשוקה אליו כמו השומע הפלאת רוממות וגדולת ושבח המלך יתאוה ויחשוק מאד לראותו כמו שא' מה תשתוחחי נפשי<sup data-n=\"4878\">277</sup> כו' מתי אבא ואראה<sup data-n=\"4879\">278</sup> פני אלקים וכן צמאה לך נפשי<sup data-n=\"4880\">279</sup> כו', מחמת שהשמיעה דבינה הוא מרחוק ממהות ועצמות הדבר ממש ע\"כ",[["4871","270","<b>וכמו</b>: א: (וכמו. וראה לעיל הערה 263."],["4872","271","<b>וירא כבוד ה'</b>: שמיני ט, כג."],["4873","272","<b>כמראה וחידוש</b>: אב: במרא[ו]' וחידות."],["4874","273","<b>במהותו</b>: אב: במהו\"ע."],["4875","274","<b>לאסתכלא ביקרא דמלכא</b>: נסמן לעיל פ' שמות לג, ד."],["4876","275","<b>וע\"פ</b>: י: נסמן כאן פ\"ט. פ\"י כמו שנסמן לקמן בפנים."],["4877","276","<b>שמעתי שמעך יראתי</b>: חבקוק ג, ב."],["4878","277","<b>מה תשתוחחי נפשי</b>: תהלים מב, ו. יב. מג, ה."],["4879","278","<b>מתי אבא ואראה</b>: תהלים מב, ג."],["4880","279","<b>צמאה לך נפשי</b>: תהלים סג, ב."]]],[2300540625,"תשוקתו אליו ביותר כידוע. אבל בבחי' ראי' דחכ' שבנשמה שהוא [ב]עין השכל שבלב שרואה במהו\"ע אלקות כמו שהוא מקרוב למעלה מן השגה והשכלה דבינה <span data-k=\"pg\">388</span> ּ מרחוק, אזי הוא נעשה בבחי' הביטול ממציאותו לגמרי שהוא ענין העדר ההרגשה בעצמו בתכלית מכל וכל מחמת שעומד מקרוב, כמו העומד מקרוב ורואה פני מלך שמתבטל ממציאותו לגמרי ונעשה כאבן דומם בלי הרגשת עצמו כלל מחמת שרואהו ואין לו כח בעצמו להיות בבחי' התפעלות תשוקה ואהבה בהתלהבות אליו כלל רק עומד מקרוב בתכלית הביטול (וכמו בשמ\"ע שעומד בקירוב בלי הרגשה בעצמו ע\"כ לא יוכל להרים קול וא' אד' שפתי תפתח כו' כמו אין מלה בלשוני<sup data-n=\"4881\">281</sup> כו' רק בלחש<sup data-n=\"4882\">280</sup> קול דממה דק\"ה כו' כמ\"ש במ\"א) (ובמ\"א מבואר להיפוך דהאהבה נולד מצד הריחוק והיראה נולד מצד הקירוב<sup data-n=\"4883\">282</sup> כמו וירא העם וינועו<sup data-n=\"4884\">283</sup> בבחי' שוב לאחור וסותר למ\"ש שמעתי שמעך יראתי כו', התירוץ הוא שיש הפרש בין יראה פנימי' ליראה חיצוניות<sup data-n=\"4885\">*284</sup>, ובחי' אהבה דבחי' רץ לבך<sup data-n=\"4886\">284</sup> ויראה בשוב זהו [ב]דו\"ר תתאי', אבל בדו\"ר עילאין<sup data-n=\"4887\">285</sup> דחילו קודם לרחימו והיינו יראה עילאה דבחי' החכ' בבחי' ביטול דמ\"ה בעצם כמ\"ש הן יראת ה' היא חכ'<sup data-n=\"4888\">286</sup> כו' ורחימו עילאה כאה\"ר בתענוגים בפנימית דבינה כו').\n<b>ואמנם</b> באמת א\"א לומר על בחי' חכ' שבנפש האלקי' בכאו\"א שיהי' בבחי' ראי' מקרוב בהשגות המהות דאוא\"ס באצי' שהוא בחי' סובב וממלא כו' כמו שהוא למעלה ממש שהרי נא' כי לא יראני האדם וחי<sup data-n=\"4889\">287</sup> כו' (ואפי' צדיקים גמורים אמרו בחייהן אינם רואים<sup data-n=\"4890\">288</sup> במיתתן בלבד רואי', שזהו בהסתלקות אור נשמתו בדביקה וחשיקה גדולה עד כלות נפשו בא' כר\"ע שיצאה נשמתו בא'<sup data-n=\"4891\">289</sup> ובב\"ע א' הציץ ומת<sup data-n=\"4892\">290</sup> וכה\"ג (שזהו מיתת נשיקה ע\"פ ה'<sup data-n=\"4893\">291</sup> שאינו אלא בצ\"ג יח\"ס, ומה שא' דל\"ו צדיקי' חזו אפי שכינתא כו' זהו ע\"י רוה\"ק וג\"א וגם זה ע\"י בחי' לבוש ומסך שנק' חשמ\"ל כמ\"ש בע\"ח). ואפי' ר\"ע ורשב\"י וחבריהם בכל עומק חכמתם בסודות הקבלה בפרצופי' העליונים כמו באד\"ר ואדר\"ז לא השיגו במהו\"ע אור האצי' רק בבחי' השגות המציאות לבד כנ\"ל באורך, ואף שגם הם הי' בהם בחי' ראי' עין השכל מקרוב שלמעלה מן השגה והשכלה דבינה כו' (כמו שא' לשון<sup data-n=\"4894\">292</sup> אסתכלנא ברזא דחכ'<sup data-n=\"4895\">293</sup> כו' בחי' הסתכלות זאת ברזא דחכ' היינו בחי' ראי' דעין השכל בבחי' אין דחכ' שנק' כח",[["4881","281","<b>אד' שפתי. . אין מלה בלשוני</b>: תהלים נא, יז. קלט, ד. נסמן לעיל מז, ג הערה 172."],["4882","280","<b>בשמ\"ע. . בלחש</b>: ראה מאמרי אדה\"א בראשית ע' צט. וש\"נ. תו\"ח נח נב, א ובהערה 4."],["4883","282","<b>דהאהבה. . הריחוק והיראה. . הקירוב</b>: ראה מאמרי אדה\"ז תקס\"ו ע' שיא ואילך. מאמרי אדה\"א דברים ח\"א ע' קעו ואילך. וש\"נ. לקמן פ' בשלח קמט, ד ובהנסמן שם."],["4884","283","<b>וירא העם וינועו</b>: יתרו כ, טו."],["4885","*284","<b>הפרש. . יראה פנימי'. . חיצוניות</b>: ראה גם לקמן פ' בשלח רכה, א."],["4886","284","<b>רץ לבך</b>: נסמן לקמן פ' בשלח קמט, ד."],["4887","285","<b>[ב]דו\"ר תתאי'. . עילאין</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' רעח. ח\"ב ע' תקמז ואילך ובהנסמן במ\"מ לשם. תקס\"ח ח\"ב ע' תרמז. מאמרי אדה\"א בראשית ע' לד. וש\"נ. ש\"א מ, א ואילך. לקמן פ' תצוה שסח, ג."],["4888","286","<b>הן יראת ה' היא חכ'</b>: איוב כח, כח. ראה גם לקמן קפח, ד."],["4889","287","<b>כי לא יראני האדם וחי</b>: תשא לג, כ."],["4890","288","<b>בחייהן אינם רואים</b>: ראה תו\"כ ר\"פ ויקרא. מאמרי אדה\"א דברים ח\"א ע' שכד. וש\"נ. הנסמן במ\"מ ללקו\"ת אחרי כז, ג. קדושים לה, ג."],["4891","289","<b>כר\"ע שיצאה נשמתו בא'</b>: ברכות סא, ב."],["4892","290","<b>ובב\"ע א' הציץ ומת</b>: חגיגה יד, ב. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' מה (בהערה). תו\"ח בראשית מ, סע\"ב ובהערה 27. לקמן פ' בשלח רטו, א. ויקהל תיד, א."],["4893","291","<b>מיתת נשיקה ע\"פ ה'</b>: ראה בבא בתרא יז, א."],["4894","292","<b>לשון</b>: א: לו. ב: לי'. דט: ליתא."],["4895","293","<b>אסתכלנא ברזא דחכ'</b>: כ\"ה בכ\"מ — ראה שה\"א צג, א ובהערה 7. לעיל הערה 81. לקמן (קז, רע\"ד). פ' בשלח רטו, ד. תצוה של, א."]]],[2300540639,"מ\"ה<sup data-n=\"4896\">294</sup> כמו מה פשפשת כו' שא\"א להביא הדבר בהשגה ברוב הסבר דברים רק בראי' עין השכל שבלב (שנק' חכ\"ם ומבין מדעתו<sup data-n=\"4897\">295</sup> ), וכמו שא' לר\"ח נושא עון חמית<sup data-n=\"4898\">296</sup> שזהו בחי' תיקון הט'<sup data-n=\"4899\">297</sup> די\"ג ת\"ד דא\"א כמבואר שם ולא דרש בו ר\"ח בפנים מסבירות איך הוא ומה הוא רק א' אסתכלנא כו'. והענין הוא דזהו בחי' פנימית דחכ' שאינו נתפס בהשגת שכל והוא בחי' הרוחניות דחכ' כמו שהיא בבחי' אין ממש ([כמו] ע\"ד דוגמא ממה שמצינו בשבחי האריז\"ל<sup data-n=\"4900\">298</sup> שהי' רואה בחלום כמה סודות עמקי החכ' בקבלה שהי' צריך להביא בכתב כמה שנים רבות כמבואר [שם ו]כה\"ג). וכך הוא בבחי' כ\"ח מ\"ה דחכ' <span data-k=\"pg\">קצד</span> ּ גם בכל א' לפי ערכו שבה יראה בעין השכל הרוחני בחי' הרוחניות של כל השגה שכל שצריך להביא בהסבר כמה שעות ולא יוכל לכוין לאמתתו כמו שהוא, רק בבחי' ראי' עין השכל דחכמה זו שנק' כ\"ח מ\"ה כו' שמכוין בעצם הדבר כמו שהוא, אבל כל זה אינו בהשגות מהות ועצמות אלקות ממש, רק במה שצריך לבא בהשגה ודעת כמו ענין הסבר דממלא וסובב כו' כנ\"ל יכיר ויראה בעין השכל לעצם תמצית הענין הזה בבחי' רוחניות של ההשגה שא\"א להביאו בהשגה. וכך הי' השגת הנשמות הגבוהות ברז\"א דחכ' בסודות הקבלה למעלה שדברו גם בפרצופי' דע\"י וא\"א וא\"ק ועכ\"ז לא ראו במהות הדבר כמו שהוא למעלה כלל ואף הנביאי' לא ראו רק בנו\"ה כנ\"ל וד\"ל. אך הנה יהי' איך שיהי' עכ\"ז יש הפרש בין חכ' לבינה שבבחי' חכ' כ\"ח מ\"ה דראי' מקרוב כנ\"ל הוא בקירוב יותר למהו\"ע הדבר ע\"כ יהי' בבחי' ביטול ממש כנ\"ל, משא\"כ בשמיעה דהשגה דבינה מרחוק שיתפעל בתשוקה אליו כנ\"ל. וכך הוא בחו\"ב שבאדם בהפרש זה בכלל שע\"י כ\"ח מ\"ה דחכ' בראי' מקרוב לאסתכלא כו' הרי יהי' ביטול בעצם נפשו כו', וכמו\"כ ע\"י הכח דחכ' שנמשך מעצם הנפש יש לו הכרה והשגה במהו\"ע נפשו הרוחניות כמו שהוא אף שהיא למעלה מן החכמה וגם מן הרצון ותענוג כנ\"ל, משא\"כ בכח הבינה שבנפשו שמשיג בריחוק כנ\"ל גם בעצם נפשו אינו משיג בהשגת שכלו רק מרחוק בבחי' השגת המציאות ולכך ע\"י הבינה דוקא תתפעל במורגש יותר ולא בביטול להיותה רחוק יותר מעצם הנפש כמו שהיא ברוחניות ממש כו' וד\"ל.\n<b>והדוגמא</b> מזה יובן ג\"כ למעלה בבחי' חו\"ב דאצי' שנק' או\"א<sup data-n=\"4901\">299</sup> דמוח החכ' דאבא זהו שנאצל באו\"כ",[["4896","294","<b>דחכ' שנק' כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["4897","295","<b>חכ\"ם ומבין מדעתו</b>: חגיגה יא, ב (במשנה)."],["4898","296","<b>נושא עון חמית</b>: נסמן לעיל הערה 81."],["4899","297","<b>נושא עון. . תיקון הט'</b>: כ\"ה גם בהכת\"י. ראה זהר (אד\"ר) נשא קלא, ב. קול ברמה לאד\"ר שם קלב, ב (נד, א ואילך בדפי הספר). ע\"ח (שער א\"א) שי\"ג, פ\"ט. מבו\"ש ש\"ג ח\"ב פי\"א. פע\"ח (שער הסליחות) שי\"ב, פ\"ח. סידור אדה\"ז סדר תשליך."],["4900","298","<b>בשבחי האריז\"ל</b>: ראה פע\"ח (שער קשעהמ\"ט) שט\"ז, פ\"א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רסד ובהנסמן במ\"מ לשם. שה\"א צג, א ובהערה 9. לקמן הערה 461. פ' תצוה של, רע\"א."],["4901","299","<b>חו\"ב. . או\"א</b>: ראה תניא פ\"ג."]]],[2300540651,"להשיג ולהכיר בבחי' ראי' מקרוב יותר לעצמות אוא\"ס, הגם שאוא\"ס עצמו למעלה גם מן הכתר אך כשנאצלו מאורו הפשוט בחי' החכ' שנק' כח מ\"ה דראי' הרוחניות כמו בכח מה דאדם יוכל לבוא בקירוב יותר לאוא\"ס ובבחי' ביטול, כמו במשה שהי' שרשו בפנימי' אור אבא דמ\"ה דח\"ע בראי' מקרוב כנ\"ל הי' בביטול תמידי בעצם בלי הרגשה בעצמו כלל כו' מצד הקירוב לאוא\"ס יותר להשיג במהו\"ע כו', אבל בחי' בינה שנאצל, שנק' מוחי' דאימא, זהו בבחי' ההשגה והבנה בהתבוננות באור הא\"ס איך הוא ומה הוא כו' בבחי' שמיעה מרחוק כמו מרחוק ה' נראה לי<sup data-n=\"4902\">300</sup> כו', כי בחי' בינה דאצי' נאצלה בריחוק מקום יותר מאור א\"ס כו'. ולזה הטעם בבחי' קו הימין דחכ' דאבא הוא מקור כל החסדים<sup data-n=\"4903\">301</sup> שאין בה בחי' גבורות שהוא ההתלהבות ותשוקה למעלה לגבי המאציל כי עומד מקרוב בביטול עצמי דמ\"ה דחכ' כנ\"ל להיותו בראי' מקרוב כנ\"ל, אבל בחי' בינה בהשגה מרחוק נולד ממנה בחי' גבורות בקו השמאל כמ\"ש אני בינה לי גבורה<sup data-n=\"4904\">302</sup> כו', שזהו בחי' ההתלהבות והתשוקה לצאת מן הכלי ליכלל במאציל, וזהו דבינה מינה דיני'<sup data-n=\"4905\">303</sup> מתערי' בסופה בגבורות קשות דפני שור מהשמאל<sup data-n=\"4906\">304</sup> שנמשך לנוגה (כמו ביו\"ט שהוא במוחי' דאימא<sup data-n=\"4907\">305</sup> מועדי' לשמחה<sup data-n=\"4908\">306</sup> דבינה<sup data-n=\"4909\">307</sup> נק' ח\"ג ה' בהתלהבות<sup data-n=\"4910\">308</sup> התענוג ושמחה ויש פרש חגיכם<sup data-n=\"4911\">309</sup> משא\"כ בשבת שהוא בקדש<sup data-n=\"4912\">310</sup> דח\"ע כו'). וזהו בחי' אוי\"ר שיש יראה עילאה בפנימיות <span data-k=\"pg\">390</span> ּ חכמה דת\"ד<sup data-n=\"4913\">311</sup> כביטול העצמי כנ\"ל שלמעלה מרחימו עילאה דרשפי אש דאה\"ר בתענוג[י'] דבינה ה\"א עילאה דיראה עילאה קדמה לאהבה כדו\"ר עילאי' כנ\"ל מטעם כל הנ\"ל וד\"ל.\n[ט<sup data-n=\"4914\">312</sup> ] והנה אחר כל הנ\"ל בביאור ענין דחו\"ב דאצי' איך שנאצלו מעצמות המאציל שנק' חכים ולא בחכ' ידיעא כו', [כך] יובן ג\"כ עד\"ז גם בחו\"ב שבעצמות המאציל הגם שאינו בחו\"ב ידיעא כו', והוא כמו חו\"ב דתורה הקדומה שקדמה לעולם אלפים שנה<sup data-n=\"4915\">313</sup> שז\"ש ואהי' אצלו אמון ונק' חש\"מ ובינה ש\"מ, ובחי' הנובלות דחש\"מ היא תורה<sup data-n=\"4916\">314</sup> הנגלית לנו באותיות דתנ\"ך (שנק' כ\"ד ספרים דאורייתא כמ\"ש ותמלא כד\"ה<sup data-n=\"4917\">315</sup> כו' כמו ששואבים מים הגדול בכד קטן כו' כמ\"ש במ\"א), ונובלות דבינה ש\"מ שכינה<sup data-n=\"4918\">316</sup> עילאה כו' ושכינתא תתאה<sup data-n=\"4919\">317</sup> שהן",[["4902","300","<b>מרחוק ה' נראה לי</b>: ירמי' לא, ב."],["4903","301","<b>דאבא הוא מקור כל החסדים</b>: נסמן לעיל צד, ד."],["4904","302","<b>אני בינה לי גבורה</b>: משלי ח, יד."],["4905","303","<b>דבינה מינה דיני'</b>: נסמן לעיל פ' וארא פה, ג הערה 843."],["4906","304","<b>דפני שור מהשמאל</b>: יחזקאל א, י."],["4907","305","<b>ביו\"ט שהוא במוחי' דאימא</b>: ראה פע\"ח (שער מקרא קודש) ש\"כ, פ\"א. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'מד."],["4908","306","<b>מועדי' לשמחה</b>: נוסח תפילת העמידה וקידוש ליו\"ט."],["4909","307","<b>מועדי'. . דבינה</b>: נסמן לקמן פ' בשלח קמט, ג."],["4910","308","<b>ח\"ג ה' בהתלהבות</b>: ראה גם סידור שער המועדים רכא, ג. מאמרי אדה\"א דברים ח\"ג ע' תתי. וש\"נ. נ\"ך ע' שפה. דרושי חתונה ח\"ב ע' תקפד. וש\"נ. לקמן קטו, ד."],["4911","309","<b>פרש חגיכם</b>: נסמן לקמן קכ, ג."],["4912","310","<b>בשבת. . בקדש</b>: ראה זהר אמור צד, א. פע\"ח שם. שעה\"י קכח, א ובהערה 12."],["4913","311","<b>דת\"ד</b>: אב: דיו\"ד."],["4914","312","<b>ט</b>: ג: מציינו להלן בתיבת וזהו (ראה לקמן הערה 321). וכנראה מקומו כאן. טז: ו."],["4915","313","<b>שקדמה לעולם אלפים שנה</b>: נסמן לעיל פ' וארא פא, ג."],["4916","314","<b>הנובלות דחש\"מ. . תורה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["4917","315","<b>ותמלא כד\"ה</b>: נסמן לעיל פ' וארא פ, א."],["4918","316","<b>ונובלות דבינה ש\"מ שכינה</b>: נסמן לעיל פ' שמות ג, ב."],["4919","317","<b>שכינה עילאה. . תתאה</b>: ראה זהר בראשית כו, א. כז, א. נ, ב. הנסמן במ\"מ ללקו\"ת פקודי ד, ד. שה\"ש א, ב."]]],[2300540663,"נש\"י שהוא בחי'<sup data-n=\"4920\">318</sup> המל'<sup data-n=\"4921\">319</sup> דלית לה מגרמה כלום כנ\"ל והוא תושבע\"פ מל' קרינן לה<sup data-n=\"4922\">320</sup> כידוע. וזהו<sup data-n=\"4923\">321</sup> הנסתרות לה' אלקינו בחי' חו\"ב<sup data-n=\"4924\">322</sup> שלמעלה כו' שזהו שנק' חכים כו' ומבין כו' והיינו כמו דוגמא דחו\"ב העצמי' [ש]באדם, שבחי' כח החכ' הוא עצם כח השכל להשכיל כל שכל מן בחי' ההעלם לגילוי בבחי' אין הרוחני כנ\"ל דזהו בבחי' ראי' מקרוב יותר לעצמות הנפש ממש, וכך הוא באור דח\"ע דתושמ\"ע שהוא בקירוב יותר לעצמות אוא\"ס וז\"ש ואהי' אצלו כו' אצלו ממש. אבל בחי' בינה ש\"מ הוא כמו בינה שבנפש האדם שהוא מרחוק יותר מעצמות הנפש כו', והוא תושבע\"פ שבא בהשגת שכל וטעם דוקא בבחי' שמיעה מרחוק כו', ולמטה הן כנס\"י שהן בבחי' בינה ומל' כמ\"ש שמע ישראל<sup data-n=\"4925\">323</sup> כו' ולכך יתכן בהם בחי' האהבה והתשוקה כמו ואל אישך תשוקתך<sup data-n=\"4926\">324</sup>, וזהו לפי שנק' נובלות בינה ש\"מ כו'. ועכ\"ז יש יתרון מעלה בגילוי דנובלות דחו\"ב ש\"מ יותר כשבאים בהתלבשות בגילוי דתו\"מ בפו\"מ דוקא וכמ\"ש והנגלות לנו כו' שהן בחי' ו\"ה דשם הוי' ובחי' חו\"ב בחי' י\"ה<sup data-n=\"4927\">325</sup>, ואע\"פ ש[בחי'] ו\"ה למטה מי\"ה מ\"מ נעוץ תחב\"ס דוקא, והוא מה שנמשך מי\"ה דחו\"ב לבחי' המדות ודו\"מ שזהו וי\"ו מדות דתורה וה\"א לעשות המצות בפו\"מ דסוף מעשה דוקא עבמח\"ת<sup data-n=\"4928\">326</sup> כידוע וד\"ל.\n<b>והנה</b> ידוע מארז\"ל ע\"פ זה שמי<sup data-n=\"4929\">327</sup> כו' דשמי עם י\"ה<sup data-n=\"4930\">328</sup> גימט' שס\"ה והן שס\"ה ל\"ת וזכרי עם ו\"ה רמ\"ח הן רמ\"ח מ\"ע<sup data-n=\"4931\">329</sup>, והיינו רמ\"ח אברים ושס\"ה גידים דרמ\"ח מצות נק' רמ\"ח אברים דמלכא<sup data-n=\"4932\">330</sup> כידוע ושס\"ה ל\"ת הן בבחי' שס\"ה גידים<sup data-n=\"4933\">331</sup> כו', ולפ\"ז שרש הל\"ת בי\"ה דחו\"ב דשם הוי' שנק' נסתרות לה' אלקינו עד רום המעלות בחו\"ב ש\"מ כנ\"ל, ושרש המ\"ע בו\"ה שנק' נגלות כמ\"ש והנגלות לנו כו'. כי המ\"ע הן באים בבחי' כלים לאורות העליונים שזהו ברמ\"ח אברים (וכל אבר כלול מג' בשר וגידים ועצמות<sup data-n=\"4934\">332</sup> כידוע והגידים הוא בחי' הממוצע המחבר לבשר בעצמות<sup data-n=\"4935\">333</sup> (שהן בחי' העצמיות<sup data-n=\"4936\">334</sup> דלובן ממנו עצמות<sup data-n=\"4937\">335</sup> ואודם ממנו בשר כו' כמ\"ש במ\"א באריכות) והיינו ג' מדרגות דכוונה במוח ולב ומעשה שהכוונה ה[י]א המחבר[ת] המוח עם הלב והלב עם המעשה וכך הוא בחי' הגידי' שהוא הכוונה המחבר[ת] המוח והלב באוי\"ר למעשה המצות שזהו לחבר בחי' בשר בעצמות כו') (וכמ\"ש בע\"ח דגידול האברים הוא מבחי' ה\"ח המגדילי' והוא בט\"ס דז\"א שג\"פ טפ\"ט עולה רמ\"ג ועם ה\"ח",[["4920","318","<b>שכינה. . בחי' המל'</b>: נסמן לעיל א, ד."],["4921","319","<b>נש\"י. . המל'</b>: ראה זהר בלק קצז, א."],["4922","320","<b>תושבע\"פ מל' קרינן לה</b>: ת\"ז בהקדמה (יז, א)."],["4923","321","<b>וזהו</b>: ראה לעיל הערה 312."],["4924","322","<b>הנסתרות. . חו\"ב</b>: נצבים כט, כח. ראה ת\"ז ת\"י (כה, ב)."],["4925","323","<b>שמע ישראל</b>: ואתחנן ו, ד."],["4926","324","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["4927","325","<b>והנגלות לנו. . ו\"ה. . י\"ה</b>: נצבים שם. ראה ת\"ז ת\"ע (קכט, א). לקו\"ת פקודי ג, ב ובהנסמן במ\"מ לשם."],["4928","326","<b>דסוף מעשה. . עבמח\"ת</b>: ע\"פ פיוט לכה דודי."],["4929","327","<b>זה שמי</b>: שמות ג, טו."],["4930","328","<b>דשמי עם י\"ה</b>: נסמן לקמן קיד, א."],["4931","329","<b>שס\"ה ל\"ת. . רמ\"ח מ\"ע</b>: מכות כג, סע\"ב."],["4932","330","<b>רמ\"ח. . אברים דמלכא</b>: נסמן לעיל פ' שמות מו, ב."],["4933","331","<b>ושס\"ה ל\"ת. . שס\"ה גידים</b>: זהר וישלח קע, ב."],["4934","332","<b>אבר. . בשר וגידים ועצמות</b>: רמב\"ם הל' טומאת מת פ\"ב, ה\"ג."],["4935","333","<b>והגידים. . המחבר לבשר בעצמות </b>[א: ועצמות]: ראה ד\"ה להבין. . בשר וגידין ועצמות במאמרי אדה\"א דברים ח\"ג ע' תתקטו ואילך. וראה גם לקמן פ' פקודי תנה, א."],["4936","334","<b>בעצמות. . בחי' העצמיות</b>: ראה ביאוה\"ז שופטים קכב, א. הנסמן במאמרי אדה\"א דברים שם."],["4937","335","<b>דלובן ממנו עצמות</b>: ראה נדה לא, א. מאמרי אדה\"ז תקס\"ו ע' שפח ואילך."]]],[2300540675,"<span data-k=\"pg\">קצה</span> ּ המגדילי' עולה רמ\"ח<sup data-n=\"4938\">336</sup> כו' שהן גידול דרמ\"ח מ\"ע דוקא, אבל בחי' שס\"ה גידים דשס\"ה ל\"ת הוא מה\"ג<sup data-n=\"4939\">337</sup> דאימא כו'). והנה הטעם בשרש ל\"ת שגבוה ממ\"ע<sup data-n=\"4940\">338</sup> הגם שאינה רק בשב ואל תעשה בלבד רק בסומ\"ר בפו\"מ כו', הענין מבואר במ\"א שזהו מצד של\"ת הוא רק בבחי' מנגד לרצונו ושנאוי ותעוב אצלו שמזה יכולים לידע יותר מה שהוא ית' בפנימי' עצמותו מאחר שזהו המנגד לעצמותו ממש. וזהו שנק' ידיעה בדרך שלילה עכ\"פ שאע\"פ שא\"י במהותו ממש יש לו ידיעה קצת באיכותו ומהותו מן היפוכו שמושלל ממנו כו', כמו שיודעי' במקצת במהות הרוחניות במה שיכולים להפשיט הרוחניות מהיפוכו מכל תוארי הגשמה (וכמו שמפשיטי' רוחניות הנמשל מן המשל כו'), כמ\"ש במ\"א באריכות שידיעה זו שבדרך שלילה אע\"פ שנק' ידיעה במקצת רק בהעלם ולא בידיעת המהות לגמרי מ\"מ הוא למעלה מידיעה שבבחי' השגת המציאות לבד הנ\"ל. וזהו ההפרש בכלל בין ל\"ת למ\"ע שבמ\"ע בא בלבוש וכלי שאינו מושג העצם דאור העצמות ממש רק מרחוק כו', שזהו בו\"ה מדות ומעשה שנמשך מבינה וזהו אדם<sup data-n=\"4941\">339</sup> בגידול האברים כו'. אבל בחי' ל\"ת בלאו שקודם להן הוא בידיעה שבשלילה מהיפוכו כנ\"ל ע\"כ שרש הל\"ת בי\"ה דחכ' שבהעלם ואין, שהוא בקירוב יותר להעצמות, ע\"כ הוא בבחי' הביטול במציאות [ב]לבד בהעדר הכלי דוקא כנ\"ל, והוא בחי' הגידי' שהן בהעצם<sup data-n=\"4942\">340</sup> ואין הרוחני דחכ' כח מ\"ה כו' (כמשי\"ת), וז\"ש דשמי עם י\"ה שס\"ה ל\"ת שהן שס\"ה גידים המחברים לבשר בעצמות שהן רמ\"ח מ\"ע כו' והנגלות<sup data-n=\"4943\">341</sup> לנו כנ\"ל וד\"ל.\n[י] <b>והנה</b> אחר הקדמה זו יש להבין בשרש ענין יצ\"מ שהוא בחי' הדילוג הגדול שמדלג על ההרים כו' והוא מ\"ש בכוונות במ\"ש בצאת ישראל שהן המדות דז\"א ממיצר מי דבינה שהוא מיצר הגרון כנ\"ל, להיות ידוע שביצ\"מ הי' עיקר מדריגת דכנ\"י הי' רק בבחי' אמונה פשוטה העצמי' דהיינו כמו שהוא בעצם נקודת יהדותו בלבד בלא התפשטות עדיין במוחי' ומדות כלל. וזהו שרש כללי לענין חג הפסח שהוא בבחי' חסד<sup data-n=\"4944\">342</sup> דאברהם<sup data-n=\"4945\">343</sup> כידוע, והוא בבחי' חסד דקטנות דאבא במצה<sup data-n=\"4946\">344</sup> זו שאנו אוכלים שנק' מיכלא דמהימנותא<sup data-n=\"4947\">345</sup> לבד כמו התינוק שא\"י לקרות או\"א<sup data-n=\"4948\">346</sup> עד שיטעום טעם לחם ונק' לחם עני<sup data-n=\"4949\">347</sup> שלמטה מן הדעת די אכלו כו', וכמ\"ש זכרתי לך חסד",[["4938","336","<b>שג\"פ טפ\"ט. . רמ\"ח</b>: ראה ע\"ח (שער פרקי הצלם) שכ\"ד, פ\"ו. הנסמן בשע\"ת מב, ב הערה 13."],["4939","337","<b>דשס\"ה ל\"ת הוא מה\"ג</b>: ראה קו\"א לתניא (להבין מ\"ש בפע\"ח) קנח, ב."],["4940","338","<b>ל\"ת שגבוה ממ\"ע</b>: ראה לקמן פ' פקודי תמו, א ואילך. תנד, ג ואילך. מאמרי אדה\"א נ\"ך ע' רלו ואילך. וש\"נ."],["4941","339","<b>אדם</b>: אב: א' ד\"ם."],["4942","340","<b>בהעצם</b>: אב: בהעלם."],["4943","341","<b>כו' והנגלות</b>: אב: בו\"ה הנגלות."],["4944","342","<b>הפסח. . חסד</b>: נסמן לעיל צד, ב."],["4945","343","<b>הפסח. . דאברהם</b>: ראה זהר (רע\"מ) פינחס רנז, ב. טור או\"ח הלכות ר\"ח סתי\"ז."],["4946","344","<b>דקטנות דאבא במצה</b>: ראה שה\"א ח, ב ובהערה 7."],["4947","345","<b>במצה. . מיכלא דמהימנותא</b>: נסמן לעיל צב, א."],["4948","346","<b>התינוק. . או\"א</b>: נסמן לעיל צה, ב."],["4949","347","<b>לחם עני</b>: פ' ראה טז, ג. פסחים קטו, סע\"ב."]]],[2300540687,"נעורייך<sup data-n=\"4950\">348</sup> דוקא שהוא בחי' קטנות דאה\"ר הטבעי' שנמשך לשרשו בלבד, וזהו לכתך אחרי<sup data-n=\"4951\">349</sup> כו' באמונה פשוטה שנק' אירוסין בבחי' מקיף בהעלם כמ\"ש וארשתיך לי באמונה<sup data-n=\"4952\">350</sup> כו'. והיינו כמו הגר שנתגייר שאין בו רק מה שנעשה כמו בריה חדשה וכבע\"ת אמיתי שאין בו רק ההתחלה שמתחיל לצאת מאפילה לאור [אע\"פ] שאין כאן רק בחי' סו\"מ<sup data-n=\"4953\">351</sup> בלבד, אבל זהו עצם נקודת יהדותו והוא גודל השמחה בנפש עצמה למעלה מן הדעת ולכך א' למען תזכור<sup data-n=\"4954\">352</sup> כו', דיצ\"מ באמונה זו אע\"פ שאין בה רק מה שלא נשקעו בנש\"ט דמצרים בלבד כי לא שמעו וקיבלו עדיין התו\"מ כלל<sup data-n=\"4955\">353</sup> עכ\"ז בזה דוקא גנוז ונעלם מבחי' העצמות דיחידה שלהם שהוא הכח ועוז למס\"נ על קדה\"ש. וז\"ש בדמייך חיי<sup data-n=\"4956\">354</sup> כו' שנכלל בזה כל מה שהי' ביכולתם לעמוד פב\"פ במ\"ת בגדלות המוחי' דאבא כו' כמ\"ש במ\"א באריכות וד\"ל. <span data-k=\"pg\">392</span> ּ וז\"ש זכרתי לך חסד נעורייך דוקא לכתך אחרי במדבר בארץ לא זרועה, שאין שם גילוי אלקות בפנימי' כמו במ\"ע רק לכתך אחרי בארץ לא זרועה<sup data-n=\"4957\">355</sup> [ד]לאו דל\"ת בסומ\"ר בלבד, אמנם כשהלאו<sup data-n=\"4958\">356</sup> דל\"ת קודם להן דמ\"ע מטעם הנ\"ל.\n[יא<sup data-n=\"4959\">357</sup> ] והנה להבין זה בדרך פרט מה הי' ענין הדילוג דמוחי' דחו\"ב במדות שלא ע\"י מיצר מי דבינה בגרון כנ\"ל, הנה יש להקדים הקדמה א' בענין הגידי' שא' בס' הרפואה שיש ג' מיני גידים<sup data-n=\"4960\">358</sup> ובפרט הן ד', הא' גידי הדם והב' גידי' שנק' עורקי' שאין בהם דם כלל והן ב' הפכי' בתכלית, כי כללות ענין הגידים הוא שנק' בשם צנורות השפע כמו גידי הארץ שמחברים הים עם הארץ, והן בחי' כח המחבר בכלל לעצם הנפש הרוחניות כמו שהיא בבחי' הרוחניות בתכלית ההפשטה מכל תואר גשמי, וצריך שיומשך ממנה דוקא להיות בבחי' חיי בשר גשמי להחיות כל האברים חיצוני' ופנימי' בבחי' חיות מורגש בגשמיות בכל אבר לפי מזגו וטבעו, א\"כ בהכרח שצ\"ל ע\"י ממוצע המחבר אותם, וראשית גילוי האור וחיות הרוחני שבנפש מתגלה בכלי המוח שבראש ונמשך ללב ומן הלב נמשך ומתפשט [ל]כל האברים. אמנם בדרך פרט יש ג' מוחי' חב\"ד ומוח החכ' הוא קר ולח ומוח הבינה הוא חם ויבש ומוח הדעת ממוצע ממוזג משניהם, וכנגדן יש ג' כלים שהן הקנה וושט וורידין<sup data-n=\"4961\">359</sup>, ומוח החכ' שהוא קר ולח כו' נמשך בקנה ללב בחלל הימני ששם משכן רוח החיים הרוחני שאין בו דם כלל כידוע, ומוח הבינה שהוא חם ויבש נמשך בושט ללב בחלל השמאלי<sup data-n=\"4962\">360</sup>",[["4950","348","<b>זכרתי לך חסד נעורייך</b>: ירמי' ב, ב."],["4951","349","<b>לכתך אחרי</b>: ירמי' שם."],["4952","350","<b>וארשתיך לי באמונה</b>: הושע ב, כב. ראה גם לקמן קי, א."],["4953","351","<b>סו\"מ</b>: סור מרע."],["4954","352","<b>למען תזכור</b>: פ' ראה טז, ג."],["4955","353","<b>לא שמעו. . התו\"מ כלל</b>: ראה רש\"י בא יב, ו. רמב\"ם הל' מלכים פ\"ט, סה\"א. לעיל פ' וארא ס, א. וש\"נ. מאמרי אדה\"א במדבר ח\"ב ע' תשסה. וש\"נ."],["4956","354","<b>בדמייך חיי</b>: יחזקאל טז, ו."],["4957","355","<b>זרועה</b>: א: כו'. ב: ליתא."],["4958","356","<b>כשהלאו</b>: אב: שרש לאו."],["4959","357","<b>יא</b>: טז: ז."],["4960","358","<b>ג' מיני גידים</b>: ראה ע\"ח (שער פנימיות וחיצוניות) ש\"מ, דרוש יב. (שער החשמ\"ל) שמ\"א, פ\"א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקכט ואילך. מאמרי אדה\"א דברים ח\"ג ע' תתקיז ואילך. הנחות תקע\"ז כאן (ע' כט) ובהנסמן בהנ\"ל."],["4961","359","<b>הקנה וושט וורידין</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' רכח."],["4962","360","<b>ללב בחלל הימני. . השמאלי</b>: ראה גם לקמן פ' תצוה שמח, ב. ש\"א י, ב ובהערה 19."]]],[2300540699,"שבלב ששם הוא הדם המובחר שנמשך לתוכו מן הגוף בסיבוב הילוך הדמים מלמטה למעלה בגידי הדם שהן הורידים בכלל (שבהן נמשך מבחי' מוח הדעת שהוא כח ההרגשה<sup data-n=\"4963\">361</sup> כמשי\"ת.\n<b>והנה</b> הממוצע הא' לחבר רוחניות החיות להיות נמשך ומתלבש בחיות גשמיות הוא ע\"י גידי הדם שהדם הוא הנפש<sup data-n=\"4964\">362</sup>, דהיינו שמשתנה בו מהות הרוחניות דנפש לגשמיות החיות והוא אשר יחי' לכל אבר ואבר לפי מזגו ונק' חיי בשר הגשמיי', וגידי' הללו הן המביאים וממשיכי' חיות גשמיות לחלל השמאלי שבלב ממוח בינה. וזהו אדם א' ד\"ם<sup data-n=\"4965\">363</sup> רוחניות שבגשמיות דוקא שנמשך מגשמיות שברוחניות הנפש ע\"י התלבשות בשינוי המהות כמ\"ש במ\"א (ויש בזה בחי' העלא' מלמטה למעלה בהילוך הדמים עם הנפש שבו דרך גידי הדם שהולכים מן הרגל לראש, וכמו\"כ יורד ונמשך<sup data-n=\"4966\">*364</sup> מלמעלה למטה בירידה והמשכה בגידי הדם שיורדי' ממוח ללב ומן הלב לאברים שכללותו הוא במוח בינה כנ\"ל (שהוא חם ויבש בגבורות ונמשך לחלל השמאלי כנ\"ל). ובכלל גידי הדם הללו נכלל ענין כח ההרגשה שהוא בגידי ההרגשה והוא מה שמרגיש אדם בחיי עצמו בכל אבר בפרט בחיות מורגש ובפרט מהיפוכו כאשר יארע קלקול או מכה באבר א' ירגישנו במוח שבראש (והוא במוח הדעת כמ\"ש יוסיף דעת יוסיף מכאוב<sup data-n=\"4967\">364</sup> שיוסיף להרגיש במכאוב, וראי' ממה שהבהמה לא תרגיש הכאב דהכאה כאדם ובאדם עצמו מרגיש בפנים יותר מאחורי[י'], וכן ברגלים שרחוקים מן המוח יותר נתמעט שם ההרגשה, כי גידי הדם שמתפשטים שם הן בריחוק מקום מן הלב והמוח וממילא גם גידי ההרגשה נתמעט שם <span data-k=\"pg\">קצו</span> ּ יותר, אך הרגשה דהסתלקות החיות כמו הקור והתעלפות מרגיש ברגליו תחלה מטעם זה עצמו כו'). ועכ\"ז עיקר ענין גידי ההרגשה מה שמרגיש הכאב אינו אלא במוח בינה ולא במוח החכ' שהרי אינו מרגיש כאב המכה שבריאה לפי שהריאה נמשך מן הקנה שהוא במוח החכ' כנ\"ל (וע\"כ הריאה שואבת כל לחלוחית<sup data-n=\"4968\">365</sup> ומנשבת תמיד על הלב<sup data-n=\"4969\">366</sup> לקררו מחומו ויש בה כיווץ והתפשטות תמיד[י] באונות שלה לפי שיסודה העצמי הוא מבחי' רוח החיים שבלב שממנו העורקים (כמשי\"ת), וכן בלב בחלל הימיני שבו, ועיקר יסוד הלב הוא מבחי' רוח החיים שהוא כח הרוח שמורכב מגידי הרוח שהן העורקים שאין בהם דם, וגם מה שנמשך מובחר הדם בחלל השמאלי הרי יוצא ונכנס ברו\"ש תמידי' והן ב' דפיקו' שבלב, א'",[["4963","361","<b>הדעת. . ההרגשה</b>: ראה תניא ספמ\"ו. לקמן פ' משפטים רפא, ד. תצוה שנח, ב. שעז, ג. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' רנו."],["4964","362","<b>שהדם הוא הנפש</b>: פ' ראה יב, כג. ראה גם ש\"א צד, ב ובהנסמן במ\"מ לשם. לקמן פ' תרומה שיג, ג. תצוה שמח, ב."],["4965","363","<b>אדם א' ד\"ם</b>: נסמן לעיל פ' וארא עב, ד."],["4966","*364","<b>ויש בזה בחי' העלא'. . יורד ונמשך</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תלט."],["4967","364","<b>יוסיף דעת יוסיף מכאוב</b>: קהלת א, יח [ושם: ויוסיף — ראה לקמן פ' משפטים רפא, ד. מאמרי אדה\"א ויקרא ח\"א ע' כא. שמות ח\"א ע' צח ובהנסמן בהנ\"ל]."],["4968","365","<b>הריאה שואבת כל לחלוחית</b>: ברכות סא, ריש ע\"ב."],["4969","366","<b>הריאה. . ומנשבת תמיד על הלב</b>: ראה זהר (רע\"מ) פינחס רלד, א. תו\"ח מקץ ריב, ג ובהערה 16. ש\"א י, ב."]]],[2300540711,"מה שמסתלק, כי מהדם הנבחר שבחה\"ש<sup data-n=\"4970\">367</sup> יוצא ומסתלק ונכלל ברוח החיים וכידוע דנפש מרכבה לגבי רוח<sup data-n=\"4971\">368</sup> כמקבל לגבי המשפיע, ודפיקו הב' מה שהרוח שבחה\"י<sup data-n=\"4972\">369</sup> נמשך לחה\"ש בהתפשטו' לכל האברים (כמשי\"ת). ואע\"פ שגידי ההרגשה נמשכים ממוח הרוחני והן גידים דקים מאד שמתפשטים עד צפורן הרגל (ויש בהן גם בחי' הרגשה רוחניות להרגיש בחיי נפשו הרוחניות וגם ברצון ושכל ותענוג הרוחני (כמשי\"ת). מ\"מ הרי הן בבחי' החיות המורגש שבדם הוא הנפ\"ש כאשר משתנה מרוחניות לגשמיות דוקא, כי כמו שהנפש היא בבחי' הרוחניות ממש לא שייך בה ענין הרגשה גשמית כהרגשת כאב או להיפך בתענוג מורגש גופני בחוש המישוש כסיכה ורחיצה וכה\"ג גם בהרגשה רוחניות כבשורה טובה או רעה כו' (כמשי\"ת).\n<b>אך</b> הנה גידי' שנק' עורקי' שאין בהם דם כלל עצם יסודם הוא מבחי' הרוחניות שבנפש עצמה ונק' גידי הרוח ואינם באים במורכב בדם שהוא החיות חיי בשר הגשמי', ושרשם הראשון הוא במוח החכ' שהיא רוחניות בעצם (ששם משכן הנשמה<sup data-n=\"4973\">370</sup> בבחי' החכמה כמו שהיא מאין כו'), שהוא למעלה מהרכבה הרוחניות דנפש בגשמיות והוא גידים דקים מאד (שנק' נערווין או מוסקלין וכה\"ג) שמלובשים במוח הגשמי דחכמה [ש]הוא קר ולח, ומתפשטי' לחלל הימיני שבלב שאין בו דם כלל ומשם נמשכי' לחה\"ש ולכל האברים להחיותם באור וחיות הרוחניות שמעצם החיות הרוחניות שבנפש שנק' רוח החיים (והוא הדפק שביד שדופק בבחי' הרוחניות דחכמה שלמעלה עדיין מהתפשטות דבינ\"ה ליש בחי[ו'] מורגש[ת] והוא מלובש במי\"ם שבד\"ם כו' כמ\"ש במ\"א בענין נגע צרעת שהוא ע\"י סגירו דנהורא עילאה<sup data-n=\"4974\">371</sup> שהוא הסתלקות אור אבא [וכ]שהוא בהתלבשותו בא' ד\"ם נק' דפ\"ק קפ\"ד<sup data-n=\"4975\">372</sup> אחוריים דאבא<sup data-n=\"4976\">373</sup>, וז\"ש קול דודי דופ\"ק<sup data-n=\"4977\">374</sup> כו' כמ\"ש במ\"א), כמו שאנו רואים בענין התחזקות כח האדם אחר שיעור עיכול ו' שעות<sup data-n=\"4978\">375</sup> שניתוסף דם בחה\"ש ועולה לחה\"י שאז דוקא נמשך מרוח החיים שבחה\"י לכל האברים כידוע. והגידים הללו הן עיקר ענין הנק' בשם צנורות השפע והוא בחי' ממוצע הב' שמחבר לעצם הנפש הרוחניות כמו שהוא שתאיר במוח ולב וכל האברים כו' בלי שינוי המהות מרוחניות לגשמיות ממש בגידי הדם כנ\"ל (וכמשי\"ת), <span data-k=\"pg\">394</span> ּ להיות שרשם בבחי' אי\"ן והעלם דחכ' כח מ\"ה הנ\"ל שהוא קרוב יותר לבחי' עצמ[יות] הרוחניות דיחידה שבנפש כנ\"ל, משא\"כ בבחי' מוח בינה ודעת שהוא בריחוק מקום יותר כנ\"ל ע\"כ משם הן גידי הדם שהוא לחבר הרוחניות בגשמיות דוקא כנ\"ל וד\"ל.",[["4970","367","<b>שבחה\"ש</b>: שבחלל השמאלי."],["4971","368","<b>דנפש מרכבה לגבי רוח</b>: ראה זהר לך פג, ב."],["4972","369","<b>שבחה\"י</b>: שבחלל הימני."],["4973","370","<b>במוח החכ'. . משכן הנשמה</b>: ראה גם לקמן פ' פקודי תמה, ג. תס, א [ושם: כידוע]. ש\"א י, ב."],["4974","371","<b>נגע צרעת. . סגירו דנהורא עילאה</b>: נסמן לעיל פ' שמות מב, ג."],["4975","372","<b>דפ\"ק קפ\"ד</b>: ראה גם טעה\"מ שבהערה הבאה. מאמרי אדה\"א שמות ח\"ב ע' תמה. וש\"נ. נ\"ך ע' רפח. הנחות תקע\"ז ע' ע ואילך."],["4976","373","<b>קפ\"ד אחוריים דאבא</b>: ראה טעה\"מ [להאריז\"ל] פ' וירא."],["4977","374","<b>קול דודי דופ\"ק</b>: שה\"ש ה, ב. ראה לקמן פ' פקודי תמה, ג ואילך. לקו\"ת פקודי ה, ד. מאמרי אדה\"ז תקס\"ב ח\"ב ע' שס. מאמרי אדה\"א דברים ח\"ג ע' תתקכב. נ\"ך ע' קה ובהנסמן בהנ\"ל. שערי אורה צה, א."],["4978","375","<b>שיעור עיכול ו' שעות</b>: ראה זהר (רע\"מ) פינחס רלה, א. וראה גם רמב\"ם ספ\"ט מהל' מאכלות אסורות. שו\"ע יו\"ד רספ\"ט ובנ\"כ שם. שע\"ת סט, א. מאמרי אדה\"א שמות ח\"א ס\"ע קמג ואילך. הנחות תקע\"ז ריש ע' עא."]]],[2300540723,"<b>והנה</b> אפס קצהו של גידים שנק' עורקי' המחברים מעצמות הנפש ממש (כמשי\"ת) יוכר בפעולתן הרוחניות בבחי' כח התנועה שבאדם שהוא ע\"י גידים הללו שנק' עורקי', והוא מה שיניע אדם בכל אבר כרצונו לקמץ או לפשט בזריזות ובמהירות גדולה לא לפ\"ע החיות המורגש באבר מגידי הדם הנ\"ל (שהרי יוכל להיות קלקול בתנועה שביד ורגל ואין ריעותא כלל בעצם החיות שביד ורגל כמו בחולי שנק' מאניא<sup data-n=\"4979\">376</sup> או שהוכה בחץ בנערווי\"ן שנק' מוסקלין), שהן גידי הרצון הרוחני שמלובש במח' דמוח החכמה ונק' בשם תנועה רצונית או תנועה נפשית כמו התנועה בשינה וכה\"ג, אע\"פ שאין תנועה בלא רצון אבל הרצון הוא בגידי המוח הרוחני' מאד דהיינו בהעלם בלתי מורכב בדם הוא הנפש החיונית כו' וד\"ל.\n<b>והנה</b><sup data-n=\"4980\">377</sup> מובן מכל זה עכ\"פ שיש ב' מיני התחברות בנפש הרוחניות עם הגוף והאברים, א' ע\"י גידי הדם הוא הנפש החיונית שמלובשת בחום הטבעי שבדם כו', והיינו ג\"כ בחי' גידי ההרגשה כנ\"ל והוא ממוח בינה ללב ומלב לאברים שביותר הן מורגשים בחוש המישוש כמו בכל תאוה גשמי' כאו\"ש ומשגל כידוע כו'. ואמנם כמו שמגשמיות המוח דבינה יומשך הגידים הגשמיי' למלאות רצון הנפש הטבעית החיוני' שבא במורכב בגוף בד\"י גשמיי' ממש, כך הוא ענין חיבור הב' שמחבר מרוחניות הנפש עצמה באברי הגוף, דהיינו מה שיושלח רוחניות השפע מרוח החיים שבנפש (שנק' רוח ולא נפש) בעורקי' הנ\"ל שאין בהם [דם] רק בחי' רוחניות בהעלם גדול מאד בדקות ורוחניות ובצמצום כצנור דק מאד עד שנמשך גם בכל האברים ע\"י הרוח החיים שבלב כנ\"ל (והיינו שרואי' גם בחושי' המורגשי' הנ\"ל מבחי' רוחניות כמו בהתעוררות לתאוות המאכל או לשתי' וכן למשגל וכה\"ג אף שהוא נמשך בלא\"ה מחום הטבעי שבדמים, עכ\"ז בלא התעוררות הרוח החיונית מבחי' הגידים שנק' עורקים אין כח בחום הטבעי להתאוות תאוה וכמ\"ש בס' הטבע כשימצא קלקול בגידים שנק' עורקי' שזהו חלישת הנערווי\"ן) כידוע.\n[יב] <b>והנה</b> ע\"ד הנ\"ל בב' מיני שפע רוחניות וגשמיות בב' מיני גידים הנ\"ל<sup data-n=\"4981\">378</sup> שבתוכם נכלל ב' מיני כחות כח ההרגשה וכח התנועה (ששרש יסודם בב' מוחי' הנ\"ל דחו\"ב שנמשכים בקנה וושט לב' חללים שבלב כנ\"ל) בהמשכת החיות לאברי הגוף בנפש החיונית בב' מדרגות דרוח ונפש כנ\"ל, כך הוא ממש בבחי' נפש השכליות (שנק' צורה לחומר לנה\"ט",[["4979","376","<b>בחולי שנק' מאניא </b>[א: מאניע. ב: מאנייא]: ראה גם לקמן פ' תצוה שמ, א. תו\"ח ח\"ש קכב, ד ובהערה 42. שע\"ת קיז, ג ובהערה 19."],["4980","377","<b>והנה</b>: טז: נסמן כאן פ\"ח. מכאן ואילך לא רשם פרקים."],["4981","378","<b>הנ\"ל</b>: אב: הגשמי'."]]],[2300540735,"החיונית בכלל כידוע), והוא מה שיש בנפש הרוחניות שכל ומדות, ובחי' אור השכל הרוחני שבנפש השכליי' הוא שורה בחומר המוחי' דחו\"ב הנ\"ל, בחי' כח החכ' הרוחניות כמו שהיא בנפש השכלי' שורה במוח החכ' שהוא קר ולח כו' ובחי' אור הבינה שבנפש שורה במוח הגשמי דבינה שהוא חם ויבש כו' כנ\"ל. והנה אנו רואים שמב' מוחי' דחו\"ב החומריי' נשלח ב' מיני חיות רוחני וגשמי להחומר של <span data-k=\"pg\">קצז</span> ּ הלב בב' החללים ומהם לאברים כנ\"ל, כך הוא ג\"כ בבחי' המשכות האור הרוחני שבשכל הרוחני שבמוחי' הנ\"ל שנשלח אור ושפע רוחניות ממש להיות התפעלות המדות בלב, כמו להתפעל באהבה ותשוקה מחמת אור השכל שבמוח בינה כ[מו] שמתבונן באיזה דבר שהוא טוב ויפה לו מיד יתפעל באהבה הרוחנית אל הדבר הזה, ומתפעל תחלה במוח ואח\"כ נמשך ללב, וכמו משמועה טובה שיבשרנו בשורה טובה מאד ישמח במוח בינה ברוחניות מאותו<sup data-n=\"4982\">379</sup> הדבר הטוב ההוא ומיד יומשך מן המוח ללב להתפעל בלב בשמחת הלב בהרגשה בגשמיות, וכן להיפך בצער ויגון מבשורה רעה יתפעל במוח ברוחניות בצער ונמשך מיד בלב להתפעל ביגון הלב בהרגשה גשמי', וכמו\"כ במדרגה<sup data-n=\"4983\">380</sup> דחסד במוח ולב או בדין ורוגז או יראה ופחד שכל אלה נשלח ע\"י גידים רוחני' שמביאים השפע הזאת מן המוח ללב. והיינו ג\"כ ע\"י ב' קנים קנה וושט שמחברים המוח ללב שע\"י הקנה נמשך ג\"כ בחי' הרוחניות של המדות דאוי\"ר מן המוח דחכמה ללב וע\"י הושט נמשך בבחי' הגשמיות דמדות בלב ממוח בינה והיינו ג\"כ ע\"י ב' מיני גידים הנ\"ל, כמו גידי הדם הנ\"ל שנשלח על ידם חיצוניות החיות שנמשך מן המוח אל האברים דהיינו כמו מגשמיות המוחי' להיות מורגש במוח ביותר כל התפעלות גשמיות החיות של האברים (וכן ע\"י העורקים נשלח כל בחי' הרוחניות דרוח החיים שבנפש כמו להניע כל תנועה מאליו, וכמו ברוח התעוררות שעושה ברצון במוח להניע כל תנועה כו' ו[ב]התעוררות לתאוה גופני' כו' כנ\"ל), כך הוא ממש בהמשכת החיות הרוחניות דמוח להתפעלו' המדות בלב כמו בשמחה וחדוה וחסד ואהבה שבמוח שנמשך ללב, או להיפוך צער ומרירות פחד ויראה וכעס ורוגז שבמוח שנמשך ללב, בודאי יש ג\"כ בזה ב' מיני גידים הנ\"ל, דהיינו שבחי' גידי הדם הנ\"ל ממשיכים בחי' חיות הגשמי' שבאהבה וחדוה שבמוח בינה להיות אהבה וחדוה בהרגשה בלב בגשמיות ובגידי הרוח שנק' עורקי' כנ\"ל נמשך בחי' הרוחניות של האוי\"ר שבמוח שלמעלה מן ההרגשה אף במוח (שהוא בחי' רוחניות ההתפעלות שבמוח החכ' עד שניזוז ממקומו שההתפעלות הרוחניות במוח הוא מחמת שגידי המוח מזדעזעי' ביותר (בל\"א צו רייצט<sup data-n=\"4984\">381</sup> די נערוין), ויש ב' מיני גידים במוח א' גידי ההרגשה שהוא במוח בינה כנ\"ל, וא' גידי הרוח שבהעלם דמוח החכמה ק\"ר ול\"ח כו' שנק' רוח חכמה, וכך בחי' רוח של",[["4982","379","<b>מאותו</b>: אב: מאיכות."],["4983","380","<b>במדרגה</b>: אב: במד[ו]ת."],["4984","381","<b>רייצט</b>: ב: היצט."]]],[2300540747,"האהבה וחדוה שבמוח שהוא בבחי' אין כמו בחי' אין דחכמה ממש (שנק' הברק\"ת אור הרוחניות של השכל טרם שבא לכלל השגה והבנה במוח בינה וכך הוא ברוחניות והעלם דמדות אוי\"ר דחכמה). וכאשר נמשך האור הרוחני דמדות דאוי\"ר שבמוח ללב ניכר שם ג\"כ הפרש זה בין התפעלות האוי\"ר ברוח החיים שבחה\"י שבלב שהוא בבחי' אין הרוחני בלתי מורגש אדרבה הוא בהעדר הרגשה בבחי' ביטול כו', וכן<sup data-n=\"4985\">382</sup> התפעלות אוי\"ר בלב במורגש שמרגיש החיות זו ע\"י בחי' גידי הדם שבמוח (וגידי הרוח הנ\"ל שבעורקי' המניעי' כל תנועה נפשי' ורצוני' בגשמיות בפועל, כך הוא הנמשך על ידם בבחי' תנועה רוחניות גם באור החכמה ורוח החיים שבחה\"י בבחי' התנועה הרוחניות להתפעל בשכל <span data-k=\"pg\">396</span> ּ הטוב (שנק' בל\"א בליצט דער שכל או<sup data-n=\"4986\">383</sup> קוועלט כו') כתנועת הח\"י שהחכמה נק' חי בעצם כמ\"ש והחכ' תחי'<sup data-n=\"4987\">384</sup> כו' ובינה נק' חיים בגילוי התפשטות החיות [כו')]. וכן ברוח [ה]מדות שבלב שמתנענעת ברו\"ש כנראה בלומד בעיון שמנענע ראשו וכהתפעלות רוח האהבה או [רוח] היראה ופחד שלא יוכל לעמוד אלא הולך אנה ואנה לפי שניזוז ממקומו בתנועה הרוחניות שבנפש עצמה שהוא בבחי' רו\"ש כו', והוא ג\"כ סיבת מה שהולך ועולה ממדרגה למדרגה בעילוי השכל להמציא חדשות כמעיין<sup data-n=\"4988\">385</sup> המתגבר מן ההעלם בלי הפסק כלל, כמו שהחכמה נק' מעיין שנובע מן ההעלם דרך גידי הארץ הנעלמי' משא\"כ בינה שנק'<sup data-n=\"4989\">387</sup> נהר<sup data-n=\"4990\">386</sup> שהן מים הנמשכים בגילוי כו'<sup data-n=\"4991\">388</sup> ), והוא מה שא' אך בצלם יתהלך איש<sup data-n=\"4992\">389</sup> הילוך זה בתנועה בהילוך גשמי שהולך ועולה, כך הנפש במוחי' דנר\"נ יש בה ענין הילוך רוחני שהוא גילוי מן ההעלם דמקיף דנר\"נ שבא בבחי' צלם ע\"י גידי הרוח הנ\"ל (כמשי\"ת). אבל בחי' גידי ההרגשה הרוחניות הוא להיפוך, שהוא מה שמרגיש במוח בינה איכות טוב הדבר לאהוב אותו או ליראה ולפחוד ממנו וכן בכעס וקפידא מורגשת (משא\"כ בגבו' דמוח<sup data-n=\"4993\">390</sup> החכמה הוא רק שאינו סובל היפוכו), וכן בהיפוך בבשורה טובה ישמח וירגיש התפעלות השמחה וכן ירגיש מאד להתפעלות האהבה וכ\"ש בהרגשת צער או כאב, והוא בהבל החזה דלב שמורכב בו מגידי הדם שהוא הנפש הטבעיות כנ\"ל בהרגשת החיות הגשמי שבאברי' (והוא ענין כיווץ והתפשטות שבלב מצער או שמחה משא\"כ ברוחניות שבחה\"י כנ\"ל). וכמו\"כ גם היותר רוחני בנפש כמו התענוג והרצון הפנימיות וכח ומקור החכ' שנק' כח המשכיל ההיולי נמשך מן המוח ללב ע\"י בחי' הגידים הנ\"ל ברוחניות וגשמיות בהעלם ובמורגש, לפי שבחי' גידים הללו הן הצנורות המחברי' לעצם הנפש שיתעורר ברצון או תענוג או להשכיל ולאהוב וכה\"ג, כמו שרואי' שינויי העתים בכל אלה בכל יום שלא בכל עת ושעה שוה באופן הארה זאת מן המוח ללב בהמשכת התפעלות המדות ופרטי אופניהם, וגם בהארת אור הרצון",[["4985","382","<b>וכן</b>: אב: וכמו. ג: ובין."],["4986","383","<b>או</b>: א: און."],["4987","384","<b>והחכ' תחי'</b>: נסמן לעיל פ' שמות ב, ב."],["4988","385","<b>שהחכמה נק' מעין</b>: ראה זהר בא מב, ב. מאמרי אדה\"א דברים ח\"ג ע' תתצב. וש\"נ. שה\"א צ, א הערה 12. לקמן פ' בשלח רנ, ב."],["4989","387","<b>שהחכמה נק' מעין. . נהר</b>: ראה גם סידור שער בהמ\"ז קד, א. שעה\"י קט, א הערה 21."],["4990","386","<b>בינה שנק' נהר</b>: ראה זהר (אדרא דמשכנא) משפטים קכג, ב."],["4991","388","<b>כו')</b>: א: כו'. ואולי התחלת הסוגר הוא בתיבת כמו (שבשו\"ה כמו)."],["4992","389","<b>אך בצלם יתהלך איש</b>: תהלים לט, ז."],["4993","390","<b>דמוח</b>: אב: דאור."]]],[2300540759,"והתענוג והחכמה שלפעמי' אין לבו ודעתו מוכנים לזה ולפעמים מוכנים (כמו שרואה אדם בנפשו שלפעמים הוא בחדוה ורוממות ולפעמים בשפלות ומורת<sup data-n=\"4994\">391</sup> רוח ועוצב) שלפי אופן זה ישתנה מחסד לדין או מדין לחסד. וכן באוי\"ר במוח וממוח ללב והכל ע\"י הגידים הנ\"ל שנק' צנורות ברוחניות ובגשמיות בהעלם וגילוי במורגש (שאין זה רק לפי אופן העלאה מן הדמים טוב או רע בגידי הדם או לפי ההמשכה בעורקים מן ההעלם דצלם הנפש כו' והא בהא תליא, וזהו סיבת השינויים תמיד וד\"ל) (וכך הוא גם בעבודה שבלב ומוח בנשמה האלקי' בתפלה שכלולה ג\"כ מנרנח\"י ומבחי' כלים דרמ\"ח אברים ושס\"ה גידים כו'), ונשלח הארת אור השפע האלקי' הרוחניות במוחי' דחו\"ב דנשמה כנ\"ל בראי' מקרוב ושמיעה מרחוק במדות שבלב באוי\"ר האלקי' בחדוה ומרירות שיש בזה הרגשה שמרגיש ההתפעלות הזאת כנ\"ל, וגם בחי' האין הרוחני שברוח החיים האלקי' שבמוח חכ' <span data-k=\"pg\">קצח</span> ּ שנמשך לחה\"י ע\"ד כל הנ\"ל, ויש בזה שינויי' רבים לעיתים גם בעונג ורצון וחו\"ב כו' כנ\"ל). והנה מכ\"ז יובן עכ\"פ שא\"א שיבא התפעלות המדות באוי\"ר ושמחה וצער בלב כ\"א ע\"י הגידים הנ\"ל המחברים המוח עם הלב שזהו הולך בסדר והדרגה מתחלה במוח יתפעל באהוי\"ר וכה\"ג ואח\"כ נמשך ללב ג\"כ ע\"י בחי' גידים הנ\"ל.\n[יג] <b>אך</b> הנה אנו רואים בחוש שיש התפעלות יתירה לפרקים ביתר מכפי המדה שנתפעלו המוח והלב יחד בלי הקדמה למוח על הלב כלל, והוא לפי שזהו התפעלות עצמיות הנפש ממש שהוא בבחי' מקיף דחי' יחידה שלמעלה מהגבלתה במוחי' ומדות כו'. והוא כמו שאנו רואי' שיבא בחי' התפעלות שמחה גדולה בלב האדם פתאום כשמבשרים אותו בשורה טובה ונפלאה ביותר שמגעת בעצמיות נפשו ממש, כמו שבישרו לשרה מיצחק<sup data-n=\"4995\">392</sup> וליעקב מיוסף וכה\"ג שבשורה כזו מגיע בעצמיות הנפש ממש וכמו ותחי רוח יעקב<sup data-n=\"4996\">393</sup> כו', שאז נראה בעליל שיספוק האדם בידיו כף אל כף במהירות התנועה מאד בלתי בחירה ברצונו ומוחו בתחלה אלא תומ\"י בלי עיכוב אפי' במעט רגע מאליו וממילא יבא תנועה גדולה זו בסיפוק וטיפוח בידיו זע\"ז. ובודאי כל תנועה בכח פתאום ביתר מכפי המדה הטבעי' כזו באה מחמת החדוה הרוחניות שבלבו ברוח החיים שבחה\"י, הגם שאין ערך כלל לתנועה גשמי' בידיו לכח רוחני הזה שבחדוה הרוחניות שבלב ומוח, שהרי גם כל התנועות הגשמיות שמניע בידיו וברגליו הכל הוא נמשך ומסתעף מן גידי המוח שנק' גידי התנועה כנ\"ל והוא ג\"כ ע\"פ המח' ורצון שעולה במוח ולב כך יניע באופן פרטי כידוע, אך זהו בא מן הרוחני אל הגשם בסדר והדרגה ע\"פ הרצון ומח' המורכב בגידי המוח כנ\"ל. אבל כאן בסיפוק הידים כף אל כף שבאה תנועה גדולה וחזקה כזו<sup data-n=\"4997\">394</sup>",[["4994","391","<b>ומורת</b>: אב: ומרירות."],["4995","392","<b>שבישרו לשרה מיצחק</b>: נסמן להלן בהערה 398."],["4996","393","<b>ותחי רוח יעקב</b>: ויגש מה, כז."],["4997","394","<b>כזו</b>: א: כמו."]]],[2300540771,"ממילא ומאליו פתאום יתנענעו במהירות עצומה כנ\"ל בלי הכנה כלל ברצון ומח' שבמוח כשאר התנועות וכנ\"ל, כי הרי מיד שיבא השמחה בלבו פתאום תומ\"י יתנענעו הידים בסיפוק ממילא ומאליהן או בריקוד ברגל כו', וכמו\"כ בהיפוך כו' באיזה בשורה רעה שהוא צער גדול שנוגע לעצמות חיי נפשו יספוק בידיו ג\"כ באופן של עצבות ובכי' מעוצם היגון ואנחה כמו המתאבל על המת פתאום וכה\"ג מאיזה היזק וצער כשריפת כל הון שלו וכה\"ג. וכל הסיפוק הוא בידים דוקא (לפי שהידים בסופן הן שרשם במקיף דיחידה שלמעלה מראשו<sup data-n=\"4998\">396</sup><sup data-n=\"4999\">395</sup> ). ושרש הענין הוא לפי שכמו שיש כח המחבר<sup data-n=\"5000\">397</sup> לעצם הנפש שבמוחי' דחו\"ב למדות שבלב וכל האברים שזהו בבחי' נר\"נ שבמוח ולב כידוע, כך יש חיבור עליון יותר והוא לחבר לעצמות הנפש דבחי' מקיפים דחי' יחידה שנק' צלם הנפש שלמעלה מנר\"נ שבמוח ולב כו' [ו]למעלה גם מן הרצון שמורכב במוחי' כו', ונק' התפעלות עצמיות הנפש כנ\"ל, שזהו שמחת הנפש בעצמה ומהותה ממש עד כלותה כו' כשמחת הנפש בשרה מבשורת יצחק עד שפרחה נשמתה<sup data-n=\"5001\">398</sup> כו' וכמו ותחי רוח יעקב ממש מבשורת יוסף וכה\"ג, שמזה יבא התפעלות השמחה ביתר מכפי המדה המוגבל במוח ולב אשר לא יכילנו כלי המוח וכלי הלב כלל ואז יושלח <span data-k=\"pg\">398</span> ּ תומ\"י בלי עיכוב כלל התנועה בסיפוק בידים ממילא ומאליו כנ\"ל בלי הכנה ברצון ומח' במוח כלל כנ\"ל, לפי שמה שלא יכ[י]ל המוח והלב, הוא שנעשה בתנועה זו דסיפוק בידיו דוקא לפי שבידים יש הארת אור המקיף דיחידה שלא [יוכל] להתיישב כלל במוח ולב, כידוע בענין נשיאת כפים שהוא למעלה מראשו<sup data-n=\"5002\">399</sup> כו', כענין המאמר דרישא דמלכא בחו\"ג אתתקן<sup data-n=\"5003\">400</sup> שהן בידים דוקא (כמשי\"ת). וא\"כ הרי רוחניות התנועה שבידים בסיפוק הוא הנמשך דרך העורקי' דוקא ששרשם במוח החכ' וברוח החיים שבלב, וע\"כ מגודל החדוה הרוחניות פתאום שבחה\"י שבלב ברוח החיים שבא מעצמות הנפש ממש כנ\"ל עד שלא יכילנו המוח והלב כלל כנ\"ל מיד יתפעל ויספוק בידיו בלי שהי' כלל אפי' רגע קטנה, ואין זה כ\"א שגם רוחניות המוח דחכ' ורוח החיים שבלב לא יכילנו ע\"כ נשלח בעורקי' דקים שבידיו דוקא לעשות הסיפוק הזה בפו\"מ. ודוקא לכל[י] הידים יותר מכל האברים, כי יש בהן שרש כח הרוחניות דעצמות הנפש דיחידה כנ\"ל, ע\"כ הן קרובי' יותר לקבל התפעלות השמחה דנפש עצמה באופן כזה דוקא שהוא בתנועות משונות כאלה דוקא להכות כף אל כף זה על זה, שיש בזה אופנים שונים גם בשמחת הנפש שהוא להרים קול רינה לבד או לרקד גם ברגל ולהניע הראש והגוף כמו דוד מפזז ומכרכר בכל עוז<sup data-n=\"5004\">401</sup> מרוב שמחת הנפש עצמה כו'. וכמו\"כ תנועת הרקידה ברגליו פתאום ע\"י התפעלות הרוחניות שבמקיף דמוח ולב כנ\"ל אינה באה לאדם כ\"א כאשר תגבור ההתפעלו' בעצמות הנפש ביותר מכפי המדה דמוח ולב",[["4998","396","<b>במקיף דיחידה שלמעלה מראשו</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקכ."],["4999","395","<b>שהידים. . שרשם. . שלמעלה מראשו</b>: ראה גם לעיל פ' וארא עב, ב. צ, סע\"ד ואילך."],["5000","397","<b>כח המחבר</b>: א: חיבור."],["5001","398","<b>בשרה. . שפרחה נשמתה</b>: ראה ריב\"א ר\"פ ח\"ש ד\"ה ולבכותה."],["5002","399","<b>נשיאת כפים שהוא למעלה מראשו</b>: ראה גם לעיל פ' וארא עב, ב ובהנסמן שם."],["5003","400","<b>דרישא דמלכא בחו\"ג אתתקן</b>: נסמן לעיל צ, סע\"ד."],["5004","401","<b>דוד מפזז ומכרכר בכל עוז</b>: שמואל-ב ו, טז. יד. ראה תו\"ח בראשית מא, ג הערה 26."]]],[2300540782,"כנ\"ל, ויש בזה אופנים רבים כידוע, וגם בעצבות גדולה יש סיפוק וטיפוח הידים באופן אחר ותנועה אחרת בחיבוק ידיו זה על גב זה כו'. וכ\"ז החיבור שנעשה מעצם שמחת הנפש בידי' הנולד פתאום במוח ולב יחד זהו ודאי ע\"י הגידי' שנק' עורקי' הרוחני' שהן נק' צנורות השפע המחברי' גם לבחי' אורות המקיפי' דחי' יחידה דבחי' צלם דנפש בגילוי באברי', שזהו הנק' התחברות רוחני שבהעלם דוקא כמו דוגמת בחי' התחברות הגשמי' שע\"י גידי הדם וגידי ההרגשה במוח [ל]לב וכל האברי' וכנ\"ל וד\"ל.\n[יד] <b>והנה</b> כמו\"כ יובן בעבודה שבלב ומוח בתפלה שיש בזה ב' מדרגות, א' בבחי' או\"פ שמתיישב בכלי הלב וכלי המוח כשהולך בסדר והדרגה במוח ומן המוח אל הלב באמצעות של חיבור הגידי' הנ\"ל, והן האהוי\"ר שבמוח כפי אשר יוכל שאת בכלי מוחו מאור עצמות הנשמה האלקי' בחו\"ב שבה כנ\"ל, ומן<sup data-n=\"5005\">402</sup> המוחי' להתפעלות המדות שנק' דו\"ר שכליים שנתפעל אח\"כ בלב הכל כפי המדה דוקא. אבל יש עוד מדרגה ב' שהוא במקיף דנר\"נ דצלם הנ\"ל שהוא התפעלות עצמיות דנשמה האלקי' בשמחה רבה והתפעלות יתירה בלתי מוגבלת כלל אף לא בהתפעלות רצון ועונג וכ\"ש בחו\"ב (לפי שהתפעלות הרצון והתפעלות התענוג האלקי עד שתכסף וגם כלתה נפשו ליכלל ולידבק בה' אחד יש לו הפסק וגבול לפ\"ע הרכבת רצון ועונג זה במוחו <span data-k=\"pg\">קצט</span> ּ ולבו משא\"כ התפעלות עצמיות דיחידה כו'). וזהו התפעלות אה\"ר דעצמיות הנפש שבאה פתאום במוח ולב יחד למעלה מכפי הגבלת כלי המוח והלב לגמרי, כי בחי' עצמו' דיחידה אינו מאיר כלל במוח ולב אף לא ברצון ועונג שבמוח ולב, להיות שהתפעלות הרוחניות דעצמיות הנפש ממש שנק' יחידה היא למעלה הרבה מערך ומהות הרוחניות החיות של הנפש שבאה במורכב בכלי המוח והלב אף בבחי' מקיף דחי' כידוע שהוא בחי' מ\"ם דצל\"ם<sup data-n=\"5006\">403</sup> כמ\"ש במ\"א וד\"ל (וזהו התפעלו' עצמיות דיחידה שבבע\"ת האמיתי' כראב\"ד שיצאה נשמתו בבכי'<sup data-n=\"5007\">404</sup> ובעי\"ת שגם הקלים ישברו לבבם<sup data-n=\"5008\">405</sup> באמת מבלי נודע מאין בא לו זאת כו', וכן השמחה עצמי' בשמחה ש\"מ<sup data-n=\"5009\">406</sup> וכמו ביציאתו מנש\"ט דמצרים כנ\"ל. וכשירת הים שהיתה בשמחת הנפש עצמה, וכך בכל מועדי' ושמחה שיש בזה משמחה עצמי' כמ\"ש וישמחו ב\"ך<sup data-n=\"5010\">407</sup> ממש כו', ומבחי' יחידה זו נמשך הכח לקדה\"ש<sup data-n=\"5011\">408</sup>, וכידוע שאין כל רע דנר\"נ פוגם בה וכמ\"ש מיד",[["5005","402","<b>ומן</b>: אב: והן."],["5006","403","<b>יחידה. . מ\"ם דצל\"ם</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תצט ואילך."],["5007","404","<b>כראב\"ד שיצאה נשמתו בבכי'</b>: נסמן לעיל פ' שמות מ, ד."],["5008","405","<b>ובעי\"ת שגם הקלים ישברו לבבם</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' פג. הנחות תקע\"ז ע' ק ובהנסמן בהנ\"ל. לקמן פ' תצוה שמח, א. וש\"נ."],["5009","406","<b>ש\"מ</b>: א: של מצוה."],["5010","407","<b>וישמחו ב\"ך</b>: נוסח תפלת העמידה ליו\"ט."],["5011","408","<b>ומבחי' יחידה. . הכח לקדה\"ש</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שלז. תק\"ע ע' קכח. עט\"ר ע' יט. תו\"ח ויצא קעו, ג. מאמרי אדה\"א קונטרסים ע' יא. ד\"ה ושבתי בשלום תשל\"ח פי\"א הערה 97 [סה\"מ מלוקט ח\"ב ע' קסו]."]]],[2300540793,"כלב יחידתי<sup data-n=\"5012\">409</sup> כו'), וז\"ש כולך יפה רעייתי<sup data-n=\"5013\">410</sup> כו' אע\"פ שהיא חיגרת או סומא בפגם דנר\"נ כו' כמ\"ש במ\"א כו'). וא\"כ הרי בהכרח לומר שיש עכ\"פ בחי' ממוצע בזה לחבר התפעלות יתירה זאת שהוא בכל העצמיות דיחידה שיומשך במוח ולב בגילוי מן ההעלם, כמו שיש ממוצע לחבר המוחי' במדות בבחי' הגבלה בכלים דמוח ולב כנ\"ל. וזהו ענין הגידים שנק' עורקי' רוחניים שבמוח שהן בחי' צנורות שבהן נשלח השפע התפעלות כל עצמיות בהעלם דרוח החיים שבלב דוקא, שהוא חלל ריקן מדם הוא הנפש הטבעיות, ושם דוקא מאיר ומלובש מבחי' או\"מ העליון דבחי' יחידה שנק' תעלומות הלב<sup data-n=\"5014\">411</sup>, ומשם נמשך בלי עיכוב כלל [ל]כח התנועה שבידים דוקא מטעם הנ\"ל. וזהו שבאה ההתפעלות העצמיות פתאום דוקא מבלי הכנה ברצון ומחשבה במו\"ח בינה<sup data-n=\"5015\">412</sup> תחלה ועושה התנועה בסיפוק הידים ממילא ע\"י כח הרוחני שבעורקי' המחבר ביניהן כנ\"ל באורך וד\"ל.\n<b>ודוגמא</b> לזה [יש] בבחי' אה\"ר בתענוגי' שהוא בבחי' מקיף דחו\"ב ומדות שבלב כמו אה\"ר דמשפיע אל המקבל כתאובתא דדכורא לגבי נוק'<sup data-n=\"5016\">413</sup> שמגודל עוצם האה\"ר יבא לענין החיבוק ונישוק, שהחיבוק ביד ימין מקרבת הוא בבחי' מקיף של האה\"ר שבלב שלא תתיישב בלב. וכן הנישוק באהב[ת] אב לבנו הקטן שמפני גודל התלהבות התשוקה בלב שלא יכיל הלב אז יבא לכלל נשיקין שיוצא מהבל הלב ממילא ומאליו כו' (שזהו שנק' זיווג רוחני במקיף דנר\"נ שמעלה יתירה יש בזה יותר מזיווג גופני, ועכ\"ז אין תולדה נולד רק מזיווג גופני כידוע בע\"ח דמזיווג הרוחני דחיבוק ונישוק יולדו מלאכים ומזיווג גופני יולדו הנשמות<sup data-n=\"5017\">414</sup> שהן בבחי' עצמיות דאור הזרוע לצ\"ע<sup data-n=\"5018\">415</sup> כו'), וכך כל יחו\"ע שמן המצות שנקראו תולד[ות]. משא\"כ באה\"ר בתענוגי' לבד שאין תולדה מזה כלל כמו מה יפית ומה נעמת אהבה בתענוגי'<sup data-n=\"5019\">416</sup> באו\"י ואו\"ח, דכמו שמן המשפיע למקבל יש אה\"ר שלמעלה מהגבלת המוחי' ומדות שבלב שזהו ע\"י בחי' כח המחבר דעורקי' שמחבר לעצם הנפש ממש (עד שיכול להיות בבחי' חולת אהבה<sup data-n=\"5020\">417</sup> כמו מעשה בא' שהעלה <span data-k=\"pg\">400</span> ּ בלבו<sup data-n=\"5021\">418</sup> כו'), כך הוא מן המקבל אל המשפיע כמו בתאובתא דנוק' לגבי דכורא<sup data-n=\"5022\">419</sup> כמ\"ש ואל אישך תשוקתך כו' כתשוקה דכנ\"י לידבק בה' באה\"ר דכל נפשך ומאדך כו', שזהו כמו שמלמעלה א' וימינו תחבקני<sup data-n=\"5023\">420</sup> יחבק לה בעלה<sup data-n=\"5024\">421</sup> כו' וכן ישקני",[["5012","409","<b>מיד כלב יחידתי</b>: תהלים כב, כא. ראה בהערה הבאה."],["5013","410","<b>כולך יפה רעייתי</b>: שה\"ש ד, ז. ראה לקמן פ' בשלח קפ, ג. מאמרי אדה\"א ויקרא ח\"א ע' יא ואילך־ דברים ח\"א ע' מט־ ח\"ב ע' תקד ובהנסמן שם. דרושי חתונה ח\"ב ע' תקפא. ע' תרנז. שערי אורה מה, א."],["5014","411","<b>תעלומות הלב</b>: תהלים מד, כב. ראה גם לקמן קז, א. פ' בשלח רכה, ב. רכו, ד. רכט, ד. משפטים רפח, ג. ויקהל תג, א. תלו, ב. מאמרי אדה\"א שמות ח\"ב ע' שצב. וש\"נ. ש\"א יג, א. שע\"ת ז, א ובהערה 3."],["5015","412","<b>בינה</b>: אב: ליתא."],["5016","413","<b>כתאובתא דדכורא לגבי נוק'</b>: ראה זהר נח סו, ב. לך פה, ב. תרומה קסה, סע\"א."],["5017","414","<b>דמזיווג הרוחני. . מלאכים ומזיווג גופני. . הנשמות</b>: ראה ע\"ח (שער מ\"ן ומ\"ד) של\"ח, דרוש ד. (שער פנימיות וחיצוניות) ש\"מ, דרוש י."],["5018","415","<b>הנשמות. . דאור הזרוע לצ\"ע</b>: ראה לקמן פ' בשלח רמ, ג."],["5019","416","<b>מה יפית. . בתענוגי'</b>: שה\"ש ז, ז."],["5020","417","<b>חולת אהבה</b>: שה\"ש ב, ה."],["5021","418","<b>מעשה בא' שהעלה בלבו</b>: סנהדרין עה, א."],["5022","419","<b>בתאובתא דנוק' לגבי דכורא</b>: ראה זהר בראשית לה, א. נח ס, ב. לך פה, ב."],["5023","420","<b>וימינו תחבקני</b>: שה\"ש ב, ו. ח, ג."],["5024","421","<b>יחבק לה בעלה</b>: זמירות ליל שבת (אזמר בשבחין)."]]],[2300540803,"מנשיקות פיהו<sup data-n=\"5025\">422</sup> כו', כך מן המקבל אל המשפיע תגדל התשוקה מפנימי' נקודת הלב עד שלא יכילנו כלי הלב והמוח כלל, ויהי' בזה ג\"כ בחי' התפעלות כל העצמיות דנש\"י שנק' יחידה כנ\"ל וכמ\"ש בכל נפשך<sup data-n=\"5026\">423</sup> כו' וכמ\"ש דוד לבי ובשרי<sup data-n=\"5027\">424</sup> כו' כלה שארי ולבבי<sup data-n=\"5028\">425</sup> כו' וכה\"ג. כי גם מלמטה למעלה יהי' ג\"כ התפעלות כל עצמיות הנפש הרוחניות כאשר יתפעל הלב ביתר מכפי המדה שאינה נצרך לקבל מן המוח כפי הכלי שלו, כי מאיר בנקודת פנימית הלב מבחי' עצמות דיחידה ממש, שאז עולה מלמטה למעלה בבחי' או\"ח לעורר לבחי' יחידה עצמה ויגרום ג\"כ ענין סיפוק הידים ממילא הנ\"ל (או הנישוק מהבל הלב הפנימי והחיבוק כאשה שמחבקת לבנה פרי בטנה ומנשקת אותו מקירות הלב כו', וכן בשמחה מבשורה טובה או הצלה ונס גדול פתאום שיגיע תחלה בנקודת הלב שיעורר מלמטה למעלה ביחידה ממש כנ\"ל), וממילא מובן מזה שבהעלאה דנקודת הלב מלמטה למעלה לחבר לעצם הנפש שתשמח בעצמה או להיפוך בצער גדול שיגיע בקירות הלב כמו חנה שהיתה מרת נפש<sup data-n=\"5029\">426</sup> בעצם וכחזקיהו שהתפלל מקירות לבו<sup data-n=\"5030\">427</sup> בבכי' רבה כו' שמגיע בעצמות הנפש ממש כנ\"ל, הנה כ\"ז הוא בבחי' גידי ההרגשה דוקא. לפי שגם בגידי ההרגשה שמחבר המוח עם הלב במדה והדרגה כנ\"ל ימצא בהן בחי' כח המחבר כזה גם לבחי' עצמיות הנפש דיחידה בדרך ממוצע כמו בחי' הממוצע דעורקי' הרוחני' הנ\"ל, והיינו בבחי' התפעלות מורגשת בנקודת הלב בעומק לעומק ביותר עד שמרגיש הרגשה יתירה בכל עצמות חיי נפשו בהתפעלות כל העצמיות ממש, כמו נכספה וגם כלתה נפשי<sup data-n=\"5031\">428</sup> כו' כלה שארי כו' כמה לך בשרי<sup data-n=\"5032\">429</sup> כו' וכאה\"ר דכל נפשך כנ\"ל, כמו שיש חיבור כזה בעורקים הרוחנים שיבא בהן בחי' רוח התעוררות חזקה מאד ביתר מכפי המדה ברוח החיים שבלב שנק' רוח ממש, וכמו נפשי אויתיך<sup data-n=\"5033\">430</sup> אף רוחי בקרבי כו' וכן אם ישים אליו לבו רוחו ונפשו<sup data-n=\"5034\">431</sup> אליו יאסוף כו' וכה\"ג, שכ\"ז הוא בחי' כח החיבור שיש לכל עצמות הנפש דחי' יחידה ג\"כ מן ההעלם לגילוי שזהו התפעלות הרוחניות העצמיות דנפש שנשלח ג\"כ ע\"י הגידים הנ\"ל. רק בעורקים הוא מלמעלה למטה ע\"י רוח החיים שבלב ובגידי ההרגשה הוא מלמטלמ\"ע מנקודת הלב למעלה כנ\"ל (וכן יש גם ברוח דעורקי' הנ\"ל כמו תשוקת המקבל אל המשפיע וכהתעוררות תשובה שנתעורר בחזקה מן המיצר וכתפלת מר נפש וכה\"ג וכ\"ז למעלה מן המדה דנר\"נ בכלים דמוח וכנ\"ל וד\"ל).",[["5025","422","<b>ישקני מנשיקות פיהו</b>: שה\"ש א, ב."],["5026","423","<b>בכל נפשך</b>: ואתחנן ו, ו [ושם: ובכל]."],["5027","424","<b>וכמ\"ש דוד לבי ובשרי</b>: תהלים פד, ג. ראה מאמרי אדה\"א שמות ח\"א ע' רפח בהערה."],["5028","425","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["5029","426","<b>חנה. . מרת נפש</b>: שמואל-א א, יא."],["5030","427","<b>וכחזקיהו שהתפלל מקירות לבו</b>: מלכים-א ב, ג. ישעי' לח, ב. ג."],["5031","428","<b>נכספה וגם כלתה נפשי</b>: תהלים פד, ג."],["5032","429","<b>כמה לך בשרי</b>: תהלים סג, ב."],["5033","430","<b>נפשי אויתיך</b>: ישעי' כו, ט [בדילוג]."],["5034","431","<b>אם ישים. . ונפשו </b>[א: ונשמתו]: איוב לד, יד."]]],[2300540812,"[טו<sup data-n=\"5035\">432</sup> ] והנה כדוגמא זאת של חיבור הנ\"ל לעצמות הנפש דיחידה ע\"י גידים הנ\"ל בחיבור רוחני בהעלם המקיף שלמעלה מן המוח ולב וכן בחיבור גשמי במדה ושיעור בהדרגה מן המוח ללב כנ\"ל, הנה אנו מוצאים שיש עוד בחי' כח המחבר כזה ביתר שאת ויתר עז גם בין המוח והלב וכל האברים בבחי' הרוחניות יותר וכ\"ש בחיבור דעצמות הנפש ממש כנ\"ל, והוא ע\"י הקול שיוצא מן <span data-k=\"pg\">ר</span> ּ הגרון והקנה. דהנה ידוע במה שאמרו דקול מעורר הכוונה<sup data-n=\"5036\">433</sup>, דהיינו ב' מיני כוונה א' מלמעלה למטה שמעורר הכוונה שבמוח, והב' מלמטה למעלה שמעורר בחי' הכוונה שבלב בנקודת הלב כו' כמו אם כיון לבו<sup data-n=\"5037\">434</sup> כו', לפי שקול היוצא מן הקנה והגרון הוא מורכב מאמ\"ר<sup data-n=\"5038\">435</sup> שיוצא מהבל הלב וגם מן המח' שבמוח שיוצא דרך הקנה הזה עצמו בלב ונמצא מורכב הוא הקול מן המוח והלב כו'. והנה לבד ענין התעוררות הכוונה שבמוח ע\"י הקול הנה יותר מזה אנו רואים דרך<sup data-n=\"5039\">436</sup> הפלא דאע\"פ שהקול הוא רק קול גשמי מורכב מאמ\"ר גשמיי' מהבל הלב שמורכב אמ\"ר רוחני' מעורר לכל עצמות הנפש ממש שלמעלה גם מן הכוונה שבמוח ולב כנ\"ל בהתפעלות עצמיות הנפש דיחידה ממש בסיפוק הידים ממילא כו', הרי כמו\"כ ממש אנו רואים בקול זה היוצא מהגרון שכאשר יתפעל אדם בעצמות נפשו ממש, שהרי כשנוגע לחייו העצמיי' ביותר אז יצעק בצעקת קול פשוט היוצא מן הגרון פתאום בלא בחירה ודעת ורצון שבמוח כלל וכלל, וכמו ויצעקו אל ה' בצר להם<sup data-n=\"5040\">437</sup> וכמו צעק לבם<sup data-n=\"5041\">438</sup> כו' שצעקה זאת בקול פשוט באה פתאום דוקא, או בדיבור [הוא] בלתי כוונה במוח ולב כלל, להיותו למעלה מהכיל במוח ולב ע\"כ יבא סיבת הצעקה הזאת, כמו במצרים דכתיב ותעל שועתם<sup data-n=\"5042\">439</sup> אל האלקי' מן העבודה כו' שזהו מחמת גודל המיצר שנגע עד הנפש ממש וכן ויזעקו בקול גדול<sup data-n=\"5043\">440</sup> כו'. וזהו ענין הקול דגרון שמורכב הוא מאמ\"ר דמוח ולב יחד שבא פתאום מצד שלא יכיל הכלים דמוח ולב כלל, וכן בהיפוך בשיר וניגון של שמחה ותענוג בקול פשוט ועצמי דוקא שנק' שיר פשוט כידוע בענין ההפרש בין בחי' שיר פשוט ובין שיר כפול ומשולש<sup data-n=\"5044\">441</sup> כו', דשיר כפול הוא בכוונה שבמוחי' דחו\"ב כשיר הלוים<sup data-n=\"5045\">442</sup> שהיו אומרים בבהמ\"ק ע\"פ כוונה שכלית בהשגות אלקות כפי הנצרך לכוין בהעלאת מ\"ן דקרבנות כמ\"ש ועבד הלוי הוא<sup data-n=\"5046\">443</sup> כו' כמ\"ש בזהר (וכמשי\"ת). אבל בחי' שיר פשוט הוא ע\"י התפעלות כל עצמיות הנפש בעצמות התענוג להתענג על ה' באה\"ר בכלות הנפש ממש או בדביקות הרצון",[["5035","432","<b>טו</b>: גי: נסמן פט\"ו בסמוך (בתיבת הנה בשו\"ה בהדרגה). ואולי צ\"ל כאן."],["5036","433","<b>דקול מעורר הכוונה</b>: ראה ר\"ח שער הקדושה ספט\"ו. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' נה ובהנסמן במ\"מ לשם. תו\"ח נח נב, ד הערה 37. לקמן פ' משפטים רפח, א."],["5037","434","<b>אם כיון לבו</b>: ברכות יג, א (במשנה)."],["5038","435","<b>שקול. . מורכב מאמ\"ר</b>: ראה זהר (רע\"מ) בא מג, ב. תצוה קפד, ב. מאמרי אדה\"א ויקרא ח\"ב ס\"ע תרנא. וש\"נ. תו\"ח בראשית לט, ד ובהערה 26."],["5039","436","<b>דרך</b>: אב: דבר."],["5040","437","<b>ויצעקו אל ה' בצר להם</b>: תהלים קז, ו. כח."],["5041","438","<b>צעק לבם</b>: איכה ב, יח."],["5042","439","<b>ותעל שועתם</b>: שמות ב, כג."],["5043","440","<b>ויזעקו בקול גדול</b>: נחמי' ט, ד."],["5044","441","<b>ההפרש בין. . שיר פשוט. . כפול ומשולש</b>: ראה זהר (רע\"מ) פינחס רכז, ב. תו\"ח בראשית לז, ד ואילך. מאמרי אדה\"א נ\"ך ע' תקנח. וש\"נ. לקמן פ' בשלח קפג, א. רלט, ב. תצוה שסח, ב."],["5045","442","<b>כשיר הלוים</b>: סוף תמיד. ר\"ה ל, ב ואילך. ראה גם שער האמונה עז, ב. מאמרי אדה\"א נ\"ך ע' שה. וראה גם לקמן פ' בשלח קסא, ד. פקודי תמה, ב. תנח, ד."],["5046","443","<b>ועבד הלוי הוא</b>: קרח יח, כג. ראה זהר קרח קעח, ב. ביאוה\"ז שם (צה, ב)."]]],[2300540821,"האמיתי מכל עצמיות הנפש, ואז יתעורר בניגון ושיר פשוט היוצא מאליו וממילא בגרון שלא ע\"פ בחירה וסדר הכוונה בשכל והשגה כלל וכלל, להיותו למעלה מבחי' התפעלות הרצון ועונג המורכב בשכל וטעם והשגה אלא למעלה מן הטעם לגמרי, כידוע בענין תפלת השבת כמ\"ש אז תתענג על ה' צלותא דמ\"ש<sup data-n=\"5047\">444</sup> והוא בחי' שיר אל דנשמה מאלי' כו'. אך כ\"ז הוא כשבא השיר הפשוט הזה בקול פשוט (בלתי מורכב בתנועות שונות בסדר והדרגה כלל כידוע) ממילא ומאליו דוקא בלי הכנה כלל מצד התפעלות עצמיות הנפש דיחידה, תחלה בתענוג נפלא כמו בעצמיות דאה\"ר בתענוגי' הנ\"ל ש[י]בא מזה לסיפוק בידים וכמו בעונג ושמחה יתירה כשבאה פתאום מבשורה טובה כנ\"ל שכח המחבר הזה ע\"י העורקים כו', כך הוא החיבור הזה מעצמות התענוג שבנפש בקול זה היוצא מהגרון ממילא ומאליו כנ\"ל וד\"ל.\n<b>אך</b> מה שא' דהקול מעורר הכוונה רצונו בזה שלא הי' לו עדיין שום התפעלות כלל בנפש ולא במוח ולב כלל רק שע\"י בחי' קול פשוט <span data-k=\"pg\">402</span> ּ זה שיוצא מהגרון בקול רם דוקא הוא שעושה התעוררות חדשה במוחו ולבו והוא שמעורר הכוונה שבמוח ולב מלמעלה למטה ומלמטלמ\"ע כו' כנ\"ל. וגם פי' כוונה זאת הוא גם למעלה מן הכוונה שבמוח ולב, והוא בכוונה הפנימי' ועצמיות דיחידה שבנפש כנ\"ל באה\"ר בתענוגי' שנוגע בתענוג העצמי' דיחידה ממש שיקרא ג\"כ בשם כוונה. אך אין זה נק' כוונה שכליית ולא כוונה שבלב במדות שנולדים מן השכל, אלא הכוונה הזאת כמו אם כיון לבו כו' שהוא בנקודה פנימית ועצמית ממש כך הקול מעורר הכוונה שבעצמות הנפש יהי' איך שיהי' וד\"ל. וכמו שאנו רואים בחוש דבר הפלא זה שגם בהיות האדם בלתי בחירה ורצון בעבודת ה' בתפלה וק\"ש וכה\"ג, אם יתחיל לדבר דבורו בקול רם אף בחיצוניות רק שיהי' מתעורר בלבו לזה לכוין לדבוק נפשו בה' בקול שיר וזמרה או לצעוק אליו בצר לו, גם שעדיין אין בלבו שום התפעלות יבא לכלל התפעלות גדולה בעצמות הנפש ע\"י הרמת קול זה שיוצא מן הגרון כו'. והיינו לפי שקול זה יוצא מהבל הלב ויש בהבל הלב מבחי' פנימי' נקודת שנק' תעלומות הלב וכמ\"ש שאגתי מנהמת לבי<sup data-n=\"5048\">445</sup> כו', וע\"כ קול זה מעורר הכוונה הפנימי' ועצמי' אף בעצם הנפש ממש לפי שעי\"ז דוקא יוצא מן ההעלם דהעלם שמוסתר אור האה\"ר בנקודת הלב לגילוי עד שיכול לעורר גם להתפעלות העצמיות דכל נפשו ממש. וזהו הטעם שא' דקול מעורר הכוונה שהוא מלמטה למעלה שעולה ממיצר הגרון מהבל הלב כנ\"ל, וכך הוא גם בבחי' המשכה וירידה מלמעלמ\"ט במח' דחכ' מאין והעלם דמקיף דיחידה שנמשך ע\"י קול זה דוקא לפי שיש לו שרש שם וד\"ל.",[["5047","444","<b>אז תתענג. . צלותא דמ\"ש </b>[א: דמעש\"ב דמעלי שבתא]: נסמן לעיל פ' וארא עו, א."],["5048","445","<b>שאגתי מנהמת לבי</b>: תהלים לח, ט."]]],[2300540830,"<b>והנה</b><sup data-n=\"5049\">446</sup> ע\"ד כ\"ז יובן ג\"כ בחיבור הב' דמוח אל הלב במה שא' דקול מעורר הכוונה שזהו בכוונה שבמוח (כמו בחי' שיר כפול דחו\"ב), דהנה אנו רואים בכל עבודה אלקי' בקול ושיר כמו בפסוד\"ז וכה\"ג שאומר בפיו<sup data-n=\"5050\">447</sup> שירות ותשבחות בשבחו ש\"מ כמו הללו את ה' מן השמים<sup data-n=\"5051\">448</sup> הללו אל בקדשו<sup data-n=\"5052\">449</sup> וכה\"ג [דודאי] שבחי' אלה [הוא] בא בדיבור ע\"י התבוננו' במוחו בהעמקת הדעת היטב, והנה כשמתבונן אדם ומעמיק באיזה ענין פרטי בגדולת ה' בשכל והשגה בטוב טעם לא בכל העיתים יש עת ושעת הכושר שיתפעל מחמתה בלב באוי\"ר וכה\"ג, אע\"פ שמשיג בעומק בכלי מוחו ונתאמת הענין ההוא אצלו מכבר כמו ביחוד אלקות דממכ\"ע איך שבורא יש מאין כו' וגם בבחי' סוכ\"ע, ואמנם כאשר העמקת השגה זאת האלקי' נשארה בכלי מוחו לבד בעיון המח' לבד יכול להיות שלא יתפעל ממנה בלב כלל ואף גם במוח הוא עולה בהעברה בעלמא בבחי' הודאה מרחוק בלבד ולא יתפעל מזה גם במוח כו'. אך הנה כאשר אותו אור השכל והשגה האלקי' עצמו יאמר וידבר אותו בקול ודיבור בפה בשבחו ש\"מ [כמו] בפסוד\"ז ובק\"ש באמרו ה' אחד ובשכמל\"ו רק שידבר בקול רם בשיר וניגון יהי' איך שיהי', אזי יתפעל בהתפעלות יתירה במוחו ולבו במאד מאד. כי הקול ושיר וניגון שיצא עם ההשגה הזאת שבמוחו הוא שעשה התפעלות גדולה הזאת במוחו ולבו שלא לפ\"ע התפעל[ות] השכל והשגה האלקי' מצד עצמה לבד <span data-k=\"pg\">רא</span> ּ כידוע. וא\"א לומר שע\"י הקול וניגון שאו' השבח וגדולת ה' יוסיף לו דעת והשגה מחודשת באותו השכל וההשגה שמתבונן בדעתו, שהרי מגוף אותו אור השכל והשגה שהי' לו מכבר הוא מתבונן בשעה שאו' שבחי ש\"מ בפסוד\"ז וכה\"ג בלי תוס' כלל יותר מהשגתו בעומק דעתו ועכ\"ז מעורר התפעלות יתירה במוחו ולבו כו'. וא\"כ בהכרח צ\"ל בזה שיש בטבע הקול הזה שיוצא ממיצר הגרון לעורר את הכוונה שבמוח ביתר מכפי שהי' מושג אצלו בהשגה מכבר, כי השגה הראשונה שלו הי' רק בחיצוניות שנק' הסבר וטעם לעצם המושכל שנתיישב במוח הבינה בכלי ההשגה כפי שיוכל שאת לפ\"ע הכלי שלו בלבד, אבל התעוררות הכוונה שבמוח בינה היינו בחי' הכוונה פנימית שהוא בבחי' הרוחניות והפנימיות ותמצית של כל ההשגה הבא בהסבר לאורך ורוחב שא\"א להשיג כלל בהשגה ונק' עומק המושג הרוחניות כמו שהוא בבחי' אי\"ן והעלם דנקודה דחכ' שמאין תמצא. וזהו שמעורר הקול היוצא מן הגרון לכוונה רוחניות זו אף בהעלם דאין דחכ' כו' (והוא שנק' שיר כפול בחו\"ב דמה שא\"א שיבא לגילוי בהסבר ונק' עומק דחו\"ב הוא שמתגלה בשיר וניגון) (והוא [כמו] ענין ראיית עין השכל מקרוב הנ\"ל, וכמו ולבי ראה<sup data-n=\"5053\">450</sup> הרבה חכ' ודעת כו' ובקול השיר וניגון יתגלה כמו שהוא בבחי' ראי' מקרוב כמו לבי ובשרי ירננו כו' וע\"כ נק' שיר א\"ל דוקא כו'). וגם הלוים שהן בבחי' בינ\"ה<sup data-n=\"5054\">451</sup> בהתלהבות ושמחה בהשגה האלקי' כמ\"ש ועב\"ד הלוי הו\"א בבחי' פנימי' בינה וא' בזהר דא הוא ע\"י<sup data-n=\"5055\">452</sup>",[["5049","446","<b>והנה</b>: י: נרשם כאן פט\"ז."],["5050","447","<b>בפיו</b>: אג: ליתא."],["5051","448","<b>הללו את ה' מן השמים</b>: תהלים קמח, א."],["5052","449","<b>הללו אל בקדשו</b>: תהלים קנ, א."],["5053","450","<b>ולבי ראה</b>: קהלת א, טז."],["5054","451","<b>הלוים. . בינ\"ה</b>: ראה לקו\"ת יו\"כ ע, ג. וש\"נ. ביאוה\"ז אחרי צה, ב."],["5055","452","<b>דא הוא ע\"י</b>: נסמן לעיל פ' שמות לד, א הערה 345."]]],[2300540839,"עצמ[ו] שהי' מתגלה בשיר שלהם על הקרבן ב[בחי'] פנימי' דע\"י שהוא בחי' [פנימיו'] התענוג הפשוט שבעצמות א\"ס ב\"ה שנק' רדכ\"ר כו'. והיינו לפי שבקול ושיר הניגון דלוים אע\"פ שהי' מלובש באותיות הדבור שלהם שהיו אומרים הקפיטל<sup data-n=\"5056\">453</sup> בתהלים לפי אופן הכוונה במוח ההשגה שלהם מ\"מ הי' שורה בזה מעצמות התענוג שבעצם הנפש דיחידה שלהם, והוא שא' דא הוא ע\"י שהיו מעוררים בזה לבחי' פנימי' דע\"י למעלה משום דרוח כו' (וזהו מ\"ש בפסוד\"ז רוממות אל בגרונם<sup data-n=\"5057\">454</sup> וחרב פיפיות בידם כו', פי' רוממות דאל דהיינו בהשגת רוממות העצמות דאור א\"ס שלמעלה מע\"ס דאבי\"ע בבחי' ממלא וסובב כו' שאינו נתפס בהשגה דבינה בהבנה והסבר רק בבחי' רוחניות הכוונה שבעומק פנימית השכל כמו שהוא בבחי' אין דמקיף דחו\"ב כנ\"ל, הוא שנמשך בגרונם דוקא דהיינו בקול הגרון כמו שיוצא מן המוח ללב דרך הקנה והגרון בשבח ש\"מ שמדבר בקול רם דוקא, אזי בזה נעשה חרב<sup data-n=\"5058\">455</sup> בחי' חרב פיפיות להכרית יניקת החיצונים כו' שהוא יניקת בחי' הרע שבנה\"ט שלא יתערב בטוב כלל, שאין בחי' בירור זה יכול להיות כלל ע\"י ההשגה דמוח בינה<sup data-n=\"5059\">456</sup> ולבו בלבד בלא קול היוצא מן הגרון, וזהו רוממות אל בגרונם דוקא כו' וד\"ל).\n[טז<sup data-n=\"5060\">457</sup> ] ושרש הענין הוא, דאע\"פ שבודאי אין ערך כלל וכלל לקול גשמי זה שיוצא מן הגרון המורכב מאמ\"ר גשמי לגבי אור השכל והשגה האלקי' אפי' לחיצוני' שלו הנתפס בכלי מוח הבינה וכ\"ש לגבי בחי' הרוחניות והעומק שלו עד שיוכל להיות לו<sup data-n=\"5061\">458</sup> כח חיבור זה מן הרוחניות דהשגה זאת ע\"י אמצעות הקול הזה דוקא כנ\"ל שהוא העושה שינוי התהוות רוח חדש <span data-k=\"pg\">404</span> ּ מבחי' פנימי' הכוונה הרוחניות של השכל וההשגה להתפעל בהתפעלות יתירה במוח ולב מאותו השכל והשגה עצמ[ו] כנ\"ל. אך עכ\"ז ההכרח לומר לפי שיש בטבע הקול לעורר את ההעלם שיבא [לידי] גילוי והיינו כל מה שגנוז ונעלם בבחי' הפנימי' ועצמות יצא לחוץ מגדרו לגילוי (וכמו שאנו רואים גם בריבוי הדיבור שמגלה כל צפון ונעלם שבמוח שלא הי' מגלהו לעולם וגם לא הי' יכול להביאו לגילוי כי לא הבינו לעומקו היטב, ובהבל הדיבור דוקא הוא שנפתח ויוצא מהעלמו בחידוש גדול ורב בגילוי כל עומק הנעלם) (וכמ\"ש במ\"א גם [ב]ענין טו\"ר הגנוז בנפשו בהעלם שע\"י הקול ודיבור<sup data-n=\"5062\">459</sup> יצאו מן ההעלם ונק' עומ\"ת או עומ\"ר<sup data-n=\"5063\">460</sup> כו') וזהו הטעם שהקול מעורר הכוונה היינו להוציא לגילוי מן ההעלם דכוונה הפנימי' כמו שהוא במקור ושרש של זה השכל והשגה האלקי' שבמוחו והיינו בכח החכ' הנעלמה שבעצמו' הנפש (שנק' כח המשכיל בחי' ח\"ס בבחי' הרוחניות דעצמות הנפש (כמו שנשמות משיגי' בלא גופים וכמו",[["5056","453","<b>הקפיטל</b>: ראה גם לקמן פ' בשלח קנט, א הערה 455. מאמרי אדה\"ז הקצרים ע' שמא. כתובים ע' כז. מארז\"ל ע' שפט. פיה\"מ לו, ג בשולי הגליון (מהדורת תשנ\"ג). בד קודש פ\"א (ע' 11. נדפס גם באגרות קודש אדה\"א ע' רצ). אוה\"ת נח (כרך ג) ע' 1320 [כרך ו ע' 2130]. תשא ע' א'תתק. שלח ע' תמב. חוקת ס\"ע תתלט. פינחס ע' א'קמב. תהלים (יהל אור) ע' תקיג. שם (כרך ב) ע' א'יא. מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' קפג."],["5057","454","<b>רוממות אל בגרונם</b>: תהלים קמט, ו."],["5058","455","<b>חרב</b>: אב: ליתא."],["5059","456","<b>דמוח בינה</b>: ב: ניתוסף: במוחו. א: דבינה במוחו."],["5060","457","<b>טז</b>: י: יז. טז נסמן לעיל הערה 446."],["5061","458","<b>לו</b>: אב: ליתא."],["5062","459","<b>טו\"ר. . שע\"י הקול ודיבור</b>: ראה גם לקמן פ' בשלח קסט, א ובהערה 254."],["5063","460","<b>עומ\"ת. ֿ. עומ\"ר</b>: אב: עומק טוב. . א: עומק רע. במאמרי אדה\"א שם: עומק רום ועומ\"ת [ ועומק תחת]. אבל ראה בהערה שם."]]],[2300540848,"אסתכלנא כו'), וכמו שהי' השגת רשב\"י וחביריו למעלה כנ\"ל וכהאריז\"ל שהי' רואה בשינה שעה ורגע<sup data-n=\"5064\">461</sup> א' רזי' דאוריי' הסתומים ונעלמים מכל השגת שכל כו' כנ\"ל). וכך יש בכל א' מעין זה ברוחניות בהעלם דחכמה דנה\"א שלו שזהו שנק' כוונה שבמוח שהוא בחי' כוונה הרוחניות דעצמו' החו\"ב שבנפש טרם בואם לכלי המוחי' מאין ליש בהשגה מוגבלת וחיצוניות, וע\"י מה נתעורר כח ההעלם הזה לבא בגילוי הנה זהו הקול ודיבור כשאומר זה השבח האלקי בפסוד\"ז שנק' רוממות אל בגרונם דוקא כנ\"ל בזה דוקא הוא מעורר לבחי' פנימי' הכוונה הרוחניות שבהעלם עצמות הנפש, ולזאת נעשה התפעלות יתירה מן המדה גם בכלי המוח והלב אשר לא הי' מתפעל כ\"כ מצד ההשגה עצמה בלא קול ודיבור כנ\"ל וד\"ל. וא\"כ מוכרח לומר שהקול הזה הוא בחי' ממוצע ממש להמשיך ולחבר הכוונה הרוחניות הזאת שתבוא בגילוי בהתפעלות יתירה ובתוס' אור רב בכלי המוח עד שלא יכילנו הכלי דמוח ולב כלל, ובאמת זהו פלא מאין ימצא כח הזה בהבל קול גשמי שאינו רק הרכב[ת] קול מאמ\"ר שבהבל הלב בלבד ומן המוח כנ\"ל, אלא צריך לומר כמו שמבואר למעלה בעורקי' וגידי' הנ\"ל שהן נק' צנורות השפע לחבר גשמיות המוח בגידי ההרגשה ורוחניות דחו\"ב בעורקי' כו', כך הוא גם כאן שמיצר קול זה שיוצא מהגרון הוא כמו צנור דק שנשלח בו השפע הרוחני' דכוונה הרוחניות שבחו\"ב דעצמות הנפש שלמעלה מכלי המוח דרך קול זה דוקא. והוא מה שקול זה מעורר את הכוונה שבמוח ולב הרבה יותר מכפי מדתם המצומצם, והרי הקול הזה הוא בחי' רוחניות יותר מן הגידי' הנ\"ל שהן לבושים גסים ועבים יותר לרוחניות דרוח החיים שמלובש בהן כנ\"ל שהוא רק מרוחניות דמוח הגשמי, או גם בסיפוק הידים שמחבר מעצם אור המקיף דיחידה ה\"ז בחי' לבוש שמתלבש או\"א<sup data-n=\"5065\">462</sup> הזה בתנועה גשמית הזאת. משא\"כ התחברות הרוחניות בקול הגרון המדבר בשבח האלקי הרי מלובש בו <span data-k=\"pg\">רב</span> ּ מעצם פנימי' ומהות אור השכל וכוונה הרוחניות [שבמוח הראש שנק' ח\"ס כנ\"ל] כמו שהיא בנפש השכלית עצמה ממש, שזהו מה שהקול מעורר הכוונה לפי שבו משכן אותו כח השכל הרוחני כמו שהוא ממש רק שמוסתר ומלובש ברוחני' דקול זה שיוצא מהבל הלב ומן המוח במיצר הגרון כנ\"ל, ומה גם בהתלבשות וחיבור אור העליון יותר והוא מבחי' עצמות התענוג והרצון שבעצמות הנפש שנק' שיר פשוט שיר אל כו' כנ\"ל, שכ\"ז בא מן ההעלם דעצמות הנפש ממש לידי גילוי בקול זה שמעורר גם לכוונה העצמי' דנפש ממש כנ\"ל וד\"ל.\n<b>(ובאמת</b> אינו מובן שרש הטעם לזה שהקול מעורר הכוונה או מה שהתפעלות העצמיות ממש או רוחני' הכוונה",[["5064","461","<b>ורגע</b>: ראה תו\"ח נח מח, ג הערה 23. שה\"א צג, א הערה 11."],["5065","462","<b>או\"א</b>: אב: או\"מ אור מקיף."]]],[2300540857,"שבחו\"ב יוצא דוקא בקול ושיר היוצא ממיצר הגרון כו', דלכאורה אנו רואים במיצר זה דקול הגרון שהוא בעצם בתכלית הקטנות והצמצום מכל צד מן המוח ומן הלב, דהנה כפי שהשגה האלקי' הוא במוח בהתפשטות והתרחבות ובהתפעלות רוחניות אור השכל עכ\"פ וגם במדות שבשכל והשגה זאת שנק' דו\"ר שכליים הן בדקות ורוחניות ובהרחבה והתפשטות, וכאשר נמשכים ללב להתפעל במהות מדות דאהוי\"ר שבלב הרי הן מתצמצמי' תחלה בכל עצם מהותם בתכלית הקיצור וההעלם, והוא בבואו למיצר הגרון ששם נפסק אור ההשגה והתפעלות שלה והי' כלא כו' ונדחק דרך המיצר הזה ונמשך ללב ושם נעשה המוחי' ומדות שבה בשינוי המהות לגמרי להיות במהות התפעלות הלב, כידוע בטעם שנק' ל\"ב שהן ל\"ב חדרים שבמוח<sup data-n=\"5066\">463</sup> כו' וכ\"ז נעשה רק מצד מיצר הגרון. וזהו בלא קול ודיבור כלל וא\"כ כ\"ש וק\"ו בהמשכות המוחי' בקול זה שמתצמצם הרבה יותר מצמצום שלהם בלב ולמה יהי' להיפוך שיהי' התלבשות עומק הרוחניות דחו\"ב בקול זה דוקא עד שמעורר מלמטה למעלה ונמשך בו מלמעלה כנ\"ל (וכמו\"כ הרי הקול מעורר הכוונה שבלב ג\"כ מן ההעלם לגילוי מבחי' העומק הרצון ותענוג ופנימיות עומק השכל שגנוז בנקודת הלב הוא שיוצא בקול ושיר פשוט ושיר כפול הנ\"ל וכמ\"ש במ\"א בענין ממעמקים קראתיך עומק דחו\"ב<sup data-n=\"5067\">464</sup>, ובחי' עומק דכתר ג\"כ יוצא מנקודת הלב בקול הגרון וזהו ג\"כ בחי' צמצום גדול דהבל הלב שיוצא בדוחק קול זה דגרון מלמטה למעלה כנ\"ל<sup data-n=\"5068\">*465</sup>. אך מבואר למעלה לפי שיש בטבע הקול ודיבור להוציא מן ההעלם לגילוי כו'. אמנם זה עצמו אינו מובן מאיזה טעם יש בו כח זה לעורר את ההעלם הגנוז שיתגלה (ואם משום דקול זה הוא בחי' רוח ורוח אייתי רוח<sup data-n=\"5069\">465</sup> ואמשיך רוח מרוחניות דעצמות הנפש ועצמות דרוח חו\"ב כו', למה לא יעורר גם בדיבור בחשאי בלא קול שיעלה הבל הדיבור או הבל רוח הלב למעלה כו'). אלא צריך לומר עוד טעם ב' והוא לפי שהקול יוצא מן המיצר דוקא וכל מיצר עושה התרחבות דוקא אח\"כ כמו מן המיצר קראתי<sup data-n=\"5070\">466</sup> כו' ענני במרחב י\"ה<sup data-n=\"5071\">467</sup>, מצד המיצר דוקא שבנקודת הלב יעשה המשכה למעלה בבחי' התרחבות אור כו'.\n<b>ויובן</b> זה גם מבחי' המיצר דגרון מצד עצמו בלא קול כנ\"ל דאותן המדות שהיו בשכל והשגה בבחי' גדלות השכל וגם אור החו\"ב עצמו הי' בגדלות ע\"י המיצר <span data-k=\"pg\">406</span> ּ דגרון נתצמצם מאד כנ\"ל, ואמנם בחי' מיצר הזה עצמו הוא שגרם מעלה יתירה במוחין עצמן דחו\"ב שבראש ומדות שלהם כשבאי' ללב שלא הי'",[["5066","463","<b>ל\"ב. . חדרים שבמוח</b>: ראה ע\"ח (שער פרצופי זו\"ן) של\"א, פ\"ד. (שער טנת\"א) ש\"ד, פ\"ה. מאמרי אדה\"א דברים ח\"ד ע' א'רמב. שמות ח\"א ע' לג ובהנסמן בהנ\"ל."],["5067","464","<b>ממעמקים קראתיך עומק דחו\"ב</b>: תהלים קל, א. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תקצ. שמות ח\"א ע' נד."],["5068","*465","<b>כנ\"ל</b>: אוצ\"ל: כנ\"ל)."],["5069","465","<b>ורוח אייתי רוח</b>: נסמן לעיל פ' וארא סג, ג."],["5070","466","<b>מן המיצר קראתי</b>: תהלים קיח, ה."],["5071","467","<b>י\"ה</b>: אב: כו'."]]],[2300540866,"בהם בעצם בתחלה כלל, דהרי הגם שתחלת התפעלות הלב אינו רק בסיבת ההשגה שבמוח [דוקא] אבל אח\"כ נעשה ההתפעלו' של המדות בלב בהתפשטות גדולה מאד למעלה הרבה מגוף התפעלות השכל והטעם. וכמו\"כ גם בעצם השכל וטעם שבמוח שהוליד המדות שבלב ע\"י צמצום כאשר באים בלב הוא בחי' עומק דחו\"ב בראיית עין השכל שבלב ובבינה ליבא שהלב מבין<sup data-n=\"5072\">468</sup> כו', שזהו בבחי' עומק ותמצית הרוחניות דחו\"ב שלא הי' מאיר במוחין עצמן כשהן במציאותן ברעש<sup data-n=\"5073\">469</sup> כו', ואין כל זה בא רק ע\"י סיבה של המיצר דגרון ששם נתקצר ונתעלם ע\"כ מיד בהתפשטו' המוחי' בלב נתגדלו לעומקם ביותר, כמו מים רבים שמעכבים אותם במסך שמיד שיסירו המסך מתגברים בשטף גדול ביותר וכידוע ומבואר במ\"א שזהו ענין קיבוץ אורות דאו\"א במיצר מ\"י שנתגברו בלב יותר עי\"ז ע\"כ נק' הלב כו' כמ\"ש בע\"ח<sup data-n=\"5074\">470</sup> וד\"ל. וכ\"ש וק\"ו כאן במיצר קול הגרון שלבד מיצר הגרון יש מיצר הבל הלב והמוח שמתצמצמי' ומתכווצים מאד זה מלמטה למעלה וזה מלמעלה למטה והכל בא בשינוי המהות בקול זה שיוצא מתוך המיצר הזה כו', ע\"כ יהי' בו בחי' ההתפשטו' וההתרחבות אח\"כ, וכמו קול השופר שצדו א' קצר יוצא ע\"י צמצום הזה בקיצור התרחבות הקול וחזק מאד בצדו הב' כו', וכך הוא בטעם שקול זה מעורר להעלם הכוונה העצמי' מעצמו' הנפש ו[מ]עומק דחו\"ב לפי שעולה במרחב דעצמות הנפש מצד מיצר שלו דוקא וד\"ל.\n[יז<sup data-n=\"5075\">471</sup> ] והנה אנו רואים לכאורה בהיפך מכל הנ\"ל בקול הגרון שיש בו מעלה יתירה הנ\"ל שהוא כח המחבר לעצמות הנפש ועומק הרוחני' דחו\"ב ומדות [כ]אה\"ר בתענוגי' כו' כנ\"ל דהלא התפלה הוא בלחש ובחשאי דוקא כידוע שכל המשמיע קולו בתפלתו ה\"ז מקטני אמנה<sup data-n=\"5076\">472</sup> כו', ואם הי' בקול הגרון מעלה יתירה הנ\"ל למה לא יצעוק בקול רם דוקא בתפלה<sup data-n=\"5077\">473</sup> שהרי הקול מעורר הכוונה הרוחני' והעצמ[י'] יותר מהכנת דעתו ולבו כנ\"ל (ומ\"ש רוממות אל בגרונם דוקא זהו בפסוד\"ז דוקא ולא בתפלה ולמה יחולק ביניהן לכאורה). וגם הלא לכאו' הקול דניגון<sup data-n=\"5078\">474</sup> יוצא בחיצוניות מאד כמו מן השפה ולחוץ וע\"כ א' נתנה עלי בקולה<sup data-n=\"5079\">475</sup> ע\"כ שנאתי' וכתיב בפיו ושפתיו כבדוני<sup data-n=\"5080\">476</sup> ולבו רחק ממני כו' ואבדה חכמת חכמיו<sup data-n=\"5081\">477</sup> כו', וא\"כ למה ישובח יותר בקול חיצוני זה שמדבר בשבחו ש\"מ<sup data-n=\"5082\">478</sup> בפסוד\"ז אם אינו רק בפיו ושפתיו ולבו רחק כו' מן השפה ולחוץ ואע\"פ שמעורר הכוונה אח\"כ כו'. אך הנה ידוע שיש בקול ב' דברים א' בחי' או\"י בירידה והמשכה מן ההעלם לגילוי כנ\"ל",[["5072","468","<b>ובבינה ליבא שהלב מבין</b>: ת\"ז בהקדמה (יז, א)."],["5073","469","<b>ברעש</b>: אב: בראש."],["5074","470","<b>כמ\"ש בע\"ח</b>: ראה הנסמן בהערה 463."],["5075","471","<b>יז</b>: י: יח."],["5076","472","<b>שכל המשמיע. . מקטני אמנה</b>: ראה ברכות כד, ב. לקמן קח, ג. פ' משפטים חצר, ד. מאמרי אדה\"א קונטרסים ע' שז. וש\"נ."],["5077","473","<b>למה לא יצעוק. . בתפלה</b>: ראה מאמרי אדה\"א דברים ח\"ג ע' תשסו. וראה גם לקמן קח, ג."],["5078","474","<b>דניגון</b>: אב: דגרון."],["5079","475","<b>נתנה עלי בקולה</b>: ירמי' יב, ח."],["5080","476","<b>בפיו ושפתיו כבדוני</b>: ישעי' כט, יג [ושם: ובשפתיו — ראה לקמן פ' בשלח רג, ד. רה, ג. (תצוה שלו, ד). ויקהל שצה, ד [ושם הוגה מגוכתי\"ק]. שצז, א. מאמרי אדה\"א שמות ח\"א ע' נג־ ח\"ב ע' תסא ובהנסמן בהנ\"ל. נ\"ך ע' שפ. דרושי חתונה ח\"ב ע' תמח. תו\"ח נח נ, ב ובהערה 23]."],["5081","477","<b>ואבדה חכמת חכמיו</b>: ישעי' שם, יד."],["5082","478","<b>ש\"מ</b>: ב: של מקום."]]],[2300540875,"בשיר פשוט וקול פשוט שיורד ומלובש בו מעצמות הנפש, והב' בחי' או\"ח בהעלאה מלמטה למעלה והוא מה שקול היוצא מהבל הלב מלמטה עולה ומעורר הכוונה שבמוח ולב עד עצמות [ה]נפש כו'<sup data-n=\"5083\">479</sup>. וזהו שאנו רואים שהקול מעורר הכוונה גם בלב זולת[ו] ששומע הקול כמו שישמע אדם קול זולתו מדבר בשבחו ש\"מ מפנימי' לבבו יעורר הכונה שבמוחו ולבו כו' ויתפעל גם הוא ביותר, משא\"כ כשאינו מדבר בקול רק בלחש כו'. <span data-k=\"pg\">רג</span> ּ ויובן מזה שע\"י קול זה יעורר גם למעלה באלקים חיים שישמע לקול ושיר האדם בשבחו ש\"מ רק כשאינו מן השפה ולחוץ בפיו ושפתיו בלבד ולבו רחק אדרבה מעורר הכוונה בלב ומוח בהיותו יוצא מתוך שמחה ואהבה שבלב ומוח. אך זהו דוקא בפסוד\"ז שצ\"ל שיהי' רוממות אל בגרונם דוקא להיות בירידה והמשכה מרוממות אל דהעלם עצמו' אוא\"ס ב\"ה למטה באו\"כ דוקא (כדי להאיר לעולמו' ולנשמות ולהאיר גם לחושך כמ\"ש במ\"א בפי' הללו י\"ה<sup data-n=\"5084\">480</sup> כמו יה\"ל אורו<sup data-n=\"5085\">481</sup> בהל\"ו נרו<sup data-n=\"5086\">482</sup> כו') ולהיות הכנה מזה לק\"ש שיוכלו לייחד יחו\"ע באחד<sup data-n=\"5087\">483</sup> באריכות דד' דאחד<sup data-n=\"5088\">484</sup> להמליכו בשמים וארץ כו', לפי שבשבחו ש\"מ בפסוד\"ז מעוררים לעצמות אוא\"ס שיאיר ויומשך במדותיו באבי\"ע כו' וע\"י שתים לפניה והעיקר באה\"ר אהבתנו<sup data-n=\"5089\">485</sup> נמשך כח ועוז לנש\"י שיוכלו למס\"נ באחד כו'. אבל בתפלה שאינה רק בחי' העלאת מ\"ן במרירות ושפלות<sup data-n=\"5090\">486</sup> ושפיכת נפש<sup data-n=\"5091\">487</sup> צריך להיות בלא הרמת קול כלל וכלל ואדרבה צ\"ל בלחש ובחשאי דוקא וכל המשמיע קולו כו', כי המשמיע קולו סומך על הקול שמעורר הכוונה גם למעלה למלאות בקשתו, וע\"כ הוא מקטני אמנה שאינו מאמין באמונה רבה שהוא במהו\"ע ית' שלמעלה מן החכ' ומדות ששם א\"צ הרמת קול לעורר כלל אלא רק בבחי' ר\"ר העצמיי', שהוא נמשך דוקא על [ידי] בחי' שפלות ונמיכת רוח עד שא\"י לדבר בקול כלל רק בבחי' צעק לבם בקול הפנימי שבהבל הלב דלא משתמע בדבור כלל שבזה יומשך מבחי' העצמות ממש כמ\"ש את מי אשכון<sup data-n=\"5092\">488</sup> כו'. וזהו הקל קול יעקב<sup data-n=\"5093\">489</sup> קל קמא חסר וי\"ו דא קול צלותא וקול בתרא בוי\"ו שהוא קול תורה דוקא שצ\"ל בחי' ירידה והמשכה מאור עצמות הרצון והח\"ע בקול זה<sup data-n=\"5094\">490</sup> שה' יושב ושונה כנגדו<sup data-n=\"5095\">491</sup> וכמ\"ש ואשים דברי בפיך<sup data-n=\"5096\">492</sup> כו'. וזהו השמיעני את קולך<sup data-n=\"5097\">493</sup> כי קולך ערב דא קלא דאורייתא (כמ\"ש במ\"א) (ועכ\"ז יש תפלה שהיא בקול רם<sup data-n=\"5098\">494</sup> דוקא וכמו ויצעקו אל ה' כו' שהוא בחי' העלא[ת מ\"ן] מן המיצר שבנקודת הלב כמו מן המיצר קראתי כו', וכן ותעל",[["5083","479","<b>כו'</b>: אב: כנ\"ל."],["5084","480","<b>בפי' הללו י\"ה</b>: ראה סידור שחרית נו, ב. לעיל פ' וארא עה, א (בהערה)."],["5085","481","<b>יה\"ל אורו </b>[אב: אור]: נסמן לעיל עה, א הערה 179."],["5086","482","<b>בהל\"ו נרו</b>: איוב כט, ג."],["5087","483","<b>יחו\"ע באחד</b>: זהר בראשית יח, ב."],["5088","484","<b>באריכות דד' דאחד</b>: ברכות יג, ב."],["5089","485","<b>באה\"ר אהבתנו</b>: ברכת ק\"ש נוסח אשכנז."],["5090","486","<b>בתפלה. . ושפלות</b>: ראה גם לקו\"ש עקב (כרך לד) ע' 69 ואילך. וש\"נ."],["5091","487","<b>בתפלה. . ושפיכת נפש</b>: נסמן לקמן פ' בשלח רלז, ד."],["5092","488","<b>את מי אשכון</b>: נסמן לעיל פ' וארא פג, ב."],["5093","489","<b>הקל קול יעקב</b>: תולדות כז, כב. ראה מאמרי אדה\"א בראשית ע' שמח. וש\"נ. תו\"ח מקץ רכז, ב ובהערות 32-4."],["5094","490","<b>זה</b>: אגט: רם."],["5095","491","<b>שה' יושב ושונה כנגדו</b>: נסמן לעיל פ' וארא נח, ג."],["5096","492","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["5097","493","<b>השמיעני את קולך</b>: שה\"ש ב, יד. ראה זהר אחרי סא, א. פינחס ריג, א. ביאוה\"ז שמיני סה, ב ואילך. מאמרי אדה\"ז תקס\"ג ח\"א ע' צט. תקס\"ה ח\"ב ע' תתקכד. מאמרי אדה\"א שמות ח\"א ע' סב. במדבר ח\"ב ע' תתכא. דרושי חתונה ח\"ב ע' תקלד."],["5098","494","<b>תפלה שהיא בקול רם</b>: ראה גם תו\"ח מקץ רכז, ב. וראה גם ביאוה\"ז תזריע ע, ד ואילך. מאמרי אדה\"ז תקס\"ג ח\"א ע' רס."]]],[2300540884,"שועתם כו', שבקול זה מעורר למעלה ר\"ר דוקא וכמו ויזעקו בקול גדול וא' שהחזירו העטרה ליושנה<sup data-n=\"5099\">495</sup> שהוא בחי' עצמות אור הרצון העליון דרעדכ\"ר כו'. אך זהו בתפלה דרבים בצרת רבים דכביר לא ימאס<sup data-n=\"5100\">496</sup> וכמו שהיו מתפללים בבהמ\"ק בכל עת צרה כמבואר בתפלת שלמה<sup data-n=\"5101\">497</sup> (וגם בצום ובכי כו'), אבל בתפלה דיחיד א' כל המשמיע קולו בתפלתו כו' וראי' מתפלה דחנה שהיתה מדברת על לבה וקולה לא ישמע<sup data-n=\"5102\">498</sup> כידוע).\n<b>ונמצא</b> מובן מכל הנ\"ל דגם שיש כח המחבר עצמות הנפש ופנימי' הכוונה הרוחני' שבמוח ולב בקול וניגון וגם בלבוש דגידי' ועורקי' כמו בסיפוק הידים וכה\"ג, אבל כ\"ז הנה בא מרוחניות הנפש בהתלבשות בלבושים זרים כמו בגידים ומיצר הגרון בבחי' הדוחק מיצר וצמצום גדול, וגם הן מלבישים ומעלימים מאד לבחי' אור הרוחניות [ב]מהות ועצמות דרצון וחכ' העצמי' דנפש שמלובש בהן אע\"פ שנגלה הארה גדולה בהתפעלות יתירה דעצמו' ממש, אבל אין ערך כלל וכלל לתנועת גשמיות בסיפוק הידים דרך העורקי' לגבי מהו\"ע התפעלו' הנפש הרוחניות, כי מה שנראית ונגלית התפעלות הנפש מן הסיפוק הזה הוא לבוש <span data-k=\"pg\">408</span> ּ ומסך גמור ועב וגס מאד כו', וכן אפי' התפעלות עצם השכל הרוחני כמו שהוא בעומק המוח כשנגלה מתוך הקול וניגון או סיפוק<sup data-n=\"5103\">499</sup> בידים שזהו דרך הגרון ודרך גידים ועורקים במיצר ודוחק גדול שאין ללבושים זרים וגסים הללו ערך ויחוס כלל עם גופו ומהותו של השכל הרוחני שאינו אלא כמו שנראה האור דרך מסך עב (משא\"כ בהתלבשות השכל הרוחני בכלי המוח הגשמי שעכ\"פ נק' המוח חומר מוכן לקבל צורה זו הרוחניות כאור הראי' הרוחניות בכלי העין וכה\"ג, אבל התלבשות זו דרוחניות השכל בשיר וניגון או בסיפוק ידים ה\"ז לבוש גס ועב ביותר שלא לפ\"ע חומר לצורה כלל, שהרי עצם התפעלות השכל שבמוח אף כמו שהוא בכלי המוח לבד הוא רוחני מאד ודק ביותר נבדל מערך תנועה גשמי' או חושיות כו' (ואע\"פ שכלי המוצאות דדיבור הן ג\"כ כלים ולבושים גשמיים לרוחניות אור הדבור דאותיות שנמשך מרוחניות הנפש שנק' נפש המדברת<sup data-n=\"5104\">500</sup> רוח ממללא<sup data-n=\"5105\">501</sup> כו', כאותיות אחה\"ע<sup data-n=\"5106\">502</sup> מהגרון הגשמי וגיכ\"ק מהחי\"ך הגשמי ובומ\"ף מהשפתים וכה\"ג. אמנם ידוע שאותיות הללו דאחה\"ע וגיכ\"ק וכה\"ג כבר נתגשמו מהבל הלב בהרכבה דאמ\"ר גשמיים והן מניעי' את המוצאות הגשמיי' ולא ככלי המוזיקא שהקול נשמע מחמת עצם החללים",[["5099","495","<b>שהחזירו העטרה ליושנה</b>: יומא סט, ב."],["5100","496","<b>דכביר לא ימאס</b>: איוב לו, ה. ברכות ח, א."],["5101","497","<b>בתפלת שלמה</b>: מלכים-א ח, ל ואילך. דהי\"ב ו, כא ואילך. ראה מאמרי אדה\"א ויקרא ח\"א ע' צב. וש\"נ. נ\"ך ע' דש. וש\"נ."],["5102","498","<b>מתפלה דחנה. . לא ישמע</b>: שמואל-א א, יג."],["5103","499","<b>או סיפוק</b>: אט: ושיר וסיפוק."],["5104","500","<b>נפש המדברת</b>: נסמן לעיל פ' וארא פא, ג."],["5105","501","<b>רוח ממללא</b>: ת\"א בראשית ב, ז."],["5106","502","<b>אחה\"ע</b>: נסמן לעיל פ' שמות מז, ב."]]],[2300540893,"שבכנור בדחיקת המיצרי'<sup data-n=\"5107\">503</sup> וכו' (ועכ\"ז גם קול הכינור פועל התפעלות הנפש השומע כקול שמעורר את הכוונה ויותר מזה, וזהו מ\"ד [ד]עיקר שירה בכלי<sup data-n=\"5108\">504</sup> וכמ\"ש אזמרה לך בכנור<sup data-n=\"5109\">505</sup> כו' הללוהו בנבל וכנור<sup data-n=\"5110\">506</sup> כו', והיינו מצד עריבות דקולות מצד עצמן כשהן במזיגות טובות כו', וכן קול ערב דאדם אע\"פ שאינו יוצא מפנימיות הלב יתפעל זולתו וגם הוא עצמו יתפעל בשיר שלו מצד מתיקות ועריבות מזיגת הקולות. וזהו טעם אחר מה שיש יתרון מעלה בתענוג שבקול ערב לעורר לעצמות הנפש הן לשמחה [ו]הן לצער<sup data-n=\"5111\">*507</sup> כו' כמ\"ש במ\"א וית' בסמוך וד\"ל. ואע\"פ שאנו רואים שיוכל רוחני ממש להתלבש בגשם כמו האהבה הרוחניות בדבור וכל השכל הרוחני בא ברמז ביד [ב]תנועה גשמי' וכן הרצון ומח' שבמוח בגידי ההרגשה והתנועה כנ\"ל. הנה גם זה בא ע\"י צמצום גדול במדה וגבול רק כפי הנמשך מן המוח ללב דרך מיצר הגרון, כך נמשך האהבה שבלב לדיבור דרך הגרון בצמצום והעלם גדול בסדר והדרגה כנ\"ל. אבל האור והשפע מעצם הנפש ממש ה\"ז בא בדרך דילוג גדול מאד שלא כסדר והדרגה כלל ודוקא מתלבש במיצר ודוחק בלבוש הגס כגידים ועורקי' וקול הגרון ושיבא גם זה מן המיצר אל המרחב דוקא כנ\"ל (וכמעיינות שמצומצמי' במיצר גידי הארץ באים למרחב אח\"כ בנהרות שמתרחבים ומתפשטים רק מן המיצר דמעיין שנובע טיפין טיפין מהעלם הגידי' שבארץ, וכן הגשמי' יורדי' טיפין מן המיצר ועיכוב שבעננים וכן טיפת מ\"ד שיורה כחץ דרך גידים המעכבים כו' ואח\"כ מוליד ויצמח הולד [כו'], וכן בעיבור יתעכב הולד ט\"ח ואח\"כ יולד כו', וכה\"ג גם בצמיחת כל זריעה, וכן בהצלחה דפרנסה וחכמה וכה\"ג בתחלה יעוכב במיצר (כמו הקרום המפסיק בין כת\"ר לחכמה<sup data-n=\"5112\">507</sup> כו'), וכן מיצר הגרון בשביל תולדה דמדות בלב והדיבור בקול, וכן חצר הכבד בשביל הגשמה <span data-k=\"pg\">רד</span> ּ דאברי המזון כו', וכ\"ז מעילה לעלול וכן מעלול לעילה הכל בביטול היש לאין תחלה ואח\"כ יהי' התהוות מאין ליש כמ\"ש במ\"א).\n[יח<sup data-n=\"5113\">508</sup> ] והנה הדוגמא מכל הנ\"ל יובן בשרש ענין בכללות בבחי' יצ\"מ שהוא ענין בצאת ישראל ממצרי\"ם ממיצר מ\"י דבינה או [מ]מיצר י\"ם דחכמה שמתצמצמי' המוחי' דחו\"ב במיצר הגרון תחלה ואח\"כ נמשך ללב להתפעל באוי\"ר שבלב כנ\"ל. והנה במצרים היו בנ\"י בבחי' קטנות המדות דאוי\"ר רק באמונה פשוטה למעשה בלבד להיות סומ\"ר דנש\"ט דמצרים כו', וגם מה שנתפעלו באוי\"ר בלב בעת התפלה וק\"ש הי' רק ע\"פ בחי' הצמצום דמיצר הגרון שבו נתקצר ונתעלם כל אורך השכל והטעם ומבחי' הרושם בעלמא המאיר דרך המיצר הזה",[["5107","503","<b>המיצרי'</b>: אוצ\"ל: המיתרי'."],["5108","504","<b>[ד]עיקר שירה בכלי</b>: ראה סוכה נ, ב ואילך."],["5109","505","<b>אזמרה לך בכנור</b>: תהלים עא, כב. ראה גם לקמן פ' בשלח קפב, ד."],["5110","506","<b>הללוהו בנבל וכנור</b>: תהלים קנ, ג."],["5111","*507","<b>שבקול ערב. . לשמחה [ו]הן לצער</b>: ראה גם שע\"ת פט, ב."],["5112","507","<b>הקרום המפסיק בין כת\"ר לחכ'</b>: ראה זהר (אד\"ר) נשא קכח, ב. מאמרי אדה\"א בראשית ע' ח. וש\"נ. לקמן פ' בשלח קצ, ג."],["5113","508","<b>יח</b>: י: יט."]]],[2300540902,"הוא שנעשה מהות התפעלות המדות דאוי\"ר בלב בשינוי המהות כאוי\"ר דעכשיו בק\"ש בא' ואהבת כו' אחר ההשגה וההתבוננו' ביחו\"ע דפסוק ראשון שמע כו', שהתפעלות הלב באה במדה ושיעור בשינוי המהות [כמו] מקיצור דהתפעלות שכליות שבמוח כו', אבל ביצ\"מ הרי הי' בחי' הדילוג הגדול שהוא בחי' התפעלו' עצמיות דיחידה שבנשמתם שלמעלה מן השכל והטעם שבמוחי' דחו\"ב, והתפעלות עצמיות זאת היא שבאה בגילוי גמור בהתפעלות המדות שבלב ביתר הרבה מכפי מדתם המצומצם מן המוח (אף למעלה מעומק דחו\"ב בראי' ושמיעה בלב הנ\"ל) שלא ע\"י מסכים ולבושי' דמיצר הגרון כלל, אלא הי' גילוי התפעלות עצמות הנפש וגם מעצם דחו\"ב הרוחניות דנפש במדות שבלב כמו שהוא ממש כו', שזהו למעלה הרבה גם מהתפעלות עצמיות הנפש שבאה בלבוש בתנועות סיפוק הידים או בקול הגרון שמלובש בו כוונה העצמיות שזהו רק דרך צמצום גדול בהעלם כנ\"ל וד\"ל. וכמו\"כ עד\"ז הי' למעלה בבחי' ישראל דלעילא שהוא בחי' מדות עליונות דז\"א דאצי' שיצאו מבחי' המיצר מי דבינה שבגרון כו'. והענין הוא כידוע שכמו\"כ למעלה באדם העליון דאצי' הרי נמשך שפע המוחין דחו\"ב דאצי' במדות שבלב העליון במדה ושיעור כפי הצמצום שצריך להיות בשינוי המהות מן המוחין למדות שבלב שהוא ע\"י מיצר הגרון כנ\"ל באדם התחתון שהוא בצלם אלקי' כו'. ואמנם בדרך דילוג גדול נמשך מבחי' מהו\"ע הבינה הרוחניות דאו\"א דאצי' במדות דז\"א ע\"י הקול דמיצר הגרון העליון שמעורר הכוונה (וכדוגמא שא' מנין שהקב\"ה מתפלל כו' מאי מצלי<sup data-n=\"5114\">509</sup> כו'). וגם מבחי' מהו\"ע דמאציל בבחי' מקיפי' דנר\"נ דז\"א שנק' צלם כו' יתלבש בקול זה (כמו קול ה' על המים<sup data-n=\"5115\">510</sup> קול ה' בכח ובהדר<sup data-n=\"5116\">511</sup> כו' שהן ז' קולות<sup data-n=\"5117\">512</sup> שנמשך בהן לז' מדות דחג\"ת [כו'] מפנימי' ועצמו' דרצון ותענוג דעצמות א\"ס ב\"ה כמו במ\"ת<sup data-n=\"5118\">513</sup> וכידוע) (וכמשי\"ת). וכמו שמבואר למעלה שיש התחברות גשמי ממוחי' למדות ע\"י גידי הדם ועורקי' כו', כך יש למעלה התחברות המוחי' בקנה חכ' קנה בינה למדות דז\"א כו' שנעשו מוחי' מצומצמי' לחו\"ג דז\"א כנ\"ל כמו חד\"ר<sup data-n=\"5119\">514</sup> להנהגת העולמות לבד. אבל מבואר למעלה שיש התחברות רוחני מעצמות הנפש לאברי' דרך גידים ועורקי' כמו בסיפוק הידים ובקול כו', כך הוא למעלה שיש התחברות רוחני מעצמות המקיפי' במדות ביתר מכפי מדתם שמקבלי' מן המוחי' עליונים [כו'] והיינו [כמו] ע\"י הקול שמעורר הכוונה וע\"י בחי' עורקי' כו' שע\"י <span data-k=\"pg\">410</span> ּ לבושים הללו יתגלה מבחי' העצמות אבל זהו בחי' לבושים מעלימי' מאד כנ\"ל. ואמנם ביצ\"מ הי' יציאת ישראל דלעילא מבחי' מיצר ודוחק דלבושים הללו דקול<sup data-n=\"5120\">515</sup> ועורקי' וכה\"ג ג\"כ אלא הי' בחי' גילוי אור העצמות",[["5114","509","<b>מנין שהקב\"ה מתפלל. . מצלי</b>: ברכות ז, א."],["5115","510","<b>קול ה' על המים</b>: תהלים כט, ג."],["5116","511","<b>קול ה' בכח ובהדר</b>: ראה תהלים שם, ד."],["5117","512","<b>ז' קולות</b>: ראה לקו\"ת נשא כט, סע\"א ואילך. פינחס עט, סע\"ג. פיה\"מ יט, ד. מאמרי אדה\"א דרושי חתונה ח\"א ע' רטו."],["5118","513","<b>ז' קולות. . במ\"ת</b>: יל\"ש תהלים כט, ג (סוף רמז תשט). ראה ספר הבהיר סמ\"ה (ובאור הגנוז ובאור הבהיר שם). פרדס (שער עה\"כ) שכ\"ג, מערכת קול. מאמרי אדה\"א במדבר ח\"ב ע' תרפה וע' תתכד. דרושי חתונה ח\"א ע' רמא. ח\"ב ע' תפא. לקו\"ש יתרו (כרך ו) ע' 108 הערה 12."],["5119","514","<b>חד\"ר</b>: חסד דין רחמים."],["5120","515","<b>דקול</b>: אב: (ד)גידי'."]]],[2300540909,"דא\"ס כמו שהוא במדות עליונות דאצי' בלי אמצעות לבושים כלל וכלל, וכמו שנגלה עליהם בכבודו ובעצמו<sup data-n=\"5121\">516</sup> דוקא כידוע, וזה הי' מצד בחי' יצ\"מ למטה באתעדל\"ת שיצאו המדות ממיצר מי דבינה כו' כנ\"ל. וזהו ענין הדילוג הגדול שהי' ביצ\"מ שהוא בחי' התפעלות עצמיות הנפש דיחידה בלי התעלמות בלבושים כלל כנ\"ל וד\"ל.\n[יט<sup data-n=\"5122\">517</sup> ] והנה אע\"פ שמבואר למעלה בענין קול מעורר הכוונה כו' ש[ה]קול הוא בחי' הצמצום ולבוש מסך מבדיל על בחי' הרוחניות הכוונה וההתפעלו' דעצמות הנפש כו' זהו דוקא בקול בלא כוונה בתחלה רק שמעורר לכוונה כו' כנ\"ל. אבל הנה יש בחי' קול שמ[ת]גלה בו כל העצמיות דוקא והוא קול השיר בשמחה ועונג נפלא כשהנפש עצמה היא בשמחה בכל עצמותה ופנימי' שלה דוקא שאז בוקעת כל המסכים והלבושים שהן השתלשלו' המוחי' ומדות כו' ונמשך בגילוי דוקא בקול השיר, כמו שהי' שירת הים שא' אז ישיר משה ובנ\"י כו' אשירה לה' כי גאה גאה כו' זה אלי כו', דהיינו ששירה זאת הי' בהתפעלות [כל] השמחה בעצמות נפשם דוקא שנק' שמחת הנפש דוקא והוא מ\"ש אז ישיר ממילא<sup data-n=\"5123\">518</sup> ומאליו [דוקא] כו'. [ו]כמו שאנו רואים לעין שכאשר יתפעל אדם בשמחה עצמי' בכל נפשו ינגן [בשיר] בקול רינה ושמחה גדולה שהיא שמחת הנפש בעצמה ומהותה דוקא שתצא מן ההעלם לגילוי בשיר ורינה זו (וכנ\"ל בענין שיר פשוט שנק' שיר אל בשבת כו'), ואין קול שיר ורינה זו באה בבחי' צמצום והעלם להעלים אור הרוחניות דנפש עצמה או הכוונה הרוחניות העצמי' שבעמקות דחו\"ב בנפש עצמה כנ\"ל, אדרבה בקול ושיר זה נתגלה דוקא מהעלם כל העצמות (שלא [כ]גילוי ההתפעלו' העצמיות בסיפוק הידים ובריקוד ברגל שמלובש ומוסתר שם בהעלם דלבושי' אלה בתנועות גשמיות שאין ניכר מהו\"ע התפעלות הנפש כ\"כ כו') (וראי' לזה משיר הלוים בבהמ\"ק שהי' בקול ערב בנעימות יתירה כדי להמתיק כל בחי' הדינין הקשי' שנאחזי' במל' שנק' גבורות קשות ע\"י נעימות קולם בשיר שלהם בכלי ובפה<sup data-n=\"5124\">*519</sup> (שמזה<sup data-n=\"5125\">519</sup> הטעם נק' בדיחי דמלכא כמ\"ש בזהר ע\"פ כהניך<sup data-n=\"5126\">520</sup> כו' וחסידיך ירננו לוייך מיבעי לי' כו'. ועד\"מ שאנו רואים שיש בכח השיר וניגון בכלי זמר בקול הנעים לשמח גם למי שהוא בעצבות גדולה מאיזה דבר צער ויגון גדול כאשר [י]שמע קול ערב ונעים בשיר הכלי זמר הטוב כנגן המנגן יבא עליו רוח חדוה ועונג",[["5121","516","<b>שנגלה עליהם בכבודו ובעצמו</b>: ראה גם סידור סדר הגדה שא, א. מאמרי אדה\"א ויקרא ח\"א ע' לה. נ\"ך ע' תכג וע' תנ. הנחות תקע\"ז ע' כא. לעיל צו, ג. לקמן קכב, א. קנב, ב."],["5122","517","<b>יט</b>: י: כ."],["5123","518","<b>אז ישיר. . ממילא</b>: בשלח טו, א. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' רס."],["5124","*519","<b>הלוים. . בשיר שלהם בכלי ובפה</b>: ראה גם לקמן פ' בשלח קפב, ד. וש\"נ."],["5125","519","<b>(שמזה</b>: א: שמזה. ואולי סיום הסוגר הוא לאחרי תיבת כו' שבשו\"ה ירננו."],["5126","520","<b>בדיחי דמלכא. . כהניך</b>: תהלים קלב, ט. ראה זהר ויצא קמח, ב. ביאוה\"ז שם (קלג, ב ואילך)."]]],[2300540916,"ושמחה בנפש הנעצבת ויפול ממנו העוצב והדאגה כידוע, וכמו שהי' דוד מנגן לפני שאול וסר מעליו רוח הרעה<sup data-n=\"5127\">521</sup> שהי' מבעתו<sup data-n=\"5128\">522</sup> כו'. [ו]כך עושין לפני שרים ומלכים [גדולים] להסיר העוצב ע\"י קול שירה וזמרה [ב]קול ערב ונעים המשיב את הנפש לעורר את החדוה ועונג וממילא יפלו כל הדינים ומקטרגי' הרעים שאינן פועלים רק בעת רוגז ועוצב כו', אבל בשעת שמחה ועונג וחדוה אין להם מקום כלל לקטרג כידוע וד\"ל. וכך הי' עיקר המכוון בשיר הלוים על הקרבן שהקרבן עצמו מכפר על העון<sup data-n=\"5129\">523</sup> כו' ולהסיר הקטרוגי' הרעים ולהמתיק הדיני' שנעשי' <span data-k=\"pg\">רה</span> ּ מן העו[נו'] כו', לזה הי' השיר על הקרבן בכל כלי שיר ע\"י הלוים דוקא ששרשם בבחי' גבורות דע\"י כמ\"ש ועבד הלוי הוא דא הוא ע\"י<sup data-n=\"5130\">524</sup> כו' שהוא בחי' ההתלהבות בשמחה וחדוה ועונג האלקי כדי לעורר את החדוה ועונג העליון למעלה להאיר אור פני מלך חיים<sup data-n=\"5131\">525</sup> כו', ועי\"ז יומתקו כל הדינים והמקטרגי' העליונים וכמ\"ש כד אנפהא דמלכא נהירין<sup data-n=\"5132\">526</sup> כו' כל דינין אתכפיי' ומתעברי' כו', וזה לא הי' רק ע\"י נעימות הקול שלהם שמעורר לעצמות התענוג הפשוט שבעצמות הנפש ממש שיבא בגילוי גמור דהיינו בהתפעלות גלוייה ממש, ולא בהעלם ולבוש כקול המעורר הכוונה שהוא קול בלא נעימה שאין בו רק בחי' התלבשות הכוונה הרוחני' שהורד ונשפל בו ע\"י צמצום והעלם גדול כנ\"ל וד\"ל) (ודוגמא לזה עוד יובן מענין השיר ונגינות דתורה שנק' טעמים שהוא בבחי' מקיף דתענוג העצמות הפשוט שבא בגילוי מן ההעלם בשיר ורננה זו בלתי לבוש והעלם כלל וכלל, אע\"פ ששרש הניגון דזרקא מקף סגולתא<sup data-n=\"5133\">527</sup> כו' הוא בבחי' המקיף דחכ' ומקיף דכתר וע\"כ הטעמים הן למעלה מאור הח\"ע הגנוז באותיות דתורה כידוע בענין טנת\"א<sup data-n=\"5134\">528</sup>, עכ\"ז בחי' הארת או\"מ דתענוג בקול הנגינות בגילוי גמור עד שכל עצמות השעשועי' העליוני' שבעצמות אוא\"ס מתגלה בהן ונק' שירו של הקב\"ה כמ\"ש ויהי שירו<sup data-n=\"5135\">529</sup> כו' [(וזהו קול ה' בכח קול דתורה] וכמבואר במ\"א בענין זמירו\"ת היו לי חוקי\"ך<sup data-n=\"5136\">530</sup> שנענש דוד ע\"ז וכתיב ובלילה שירה עמי<sup data-n=\"5137\">531</sup> כו' וד\"ל).\n[כ<sup data-n=\"5138\">532</sup> ] והנה אחר כ\"ז יובן יותר ענין יצ\"מ שנק' דילוג כמ\"ש קול דודי כו' מדלג על ההרים העליונים ועל הגבעות שהן ב' מיני מדות מדות שברצון ותענוג שנק' הרים גדולים<sup data-n=\"5139\">533</sup> ומדות שבחו\"ב שנק' גבעות כו', לפי שב' [מיני] מדות הללו (שנק' טורי חשוכא וטורי נהורא<sup data-n=\"5140\">534</sup> כו' כידוע) זהו כשהולך",[["5127","521","<b>וסר מעליו רוח הרעה</b>: שמואל-א טז, כג [ושם: וסרה — ראה שע\"ת פט, ב]."],["5128","522","<b>שהי' מבעתו</b>: ראה שם טז, יד. טו."],["5129","523","<b>בשיר הלוים על הקרבן. . העון</b>: ראה זהר ויקרא ח, סע\"א ובאוה\"ח שם. הנסמן באוה\"ת ויקרא כאן (ע' תתקעג הערה שיר)."],["5130","524","<b>ועבד. . הוא ע\"י</b>: נסמן לעיל פ' שמות לד, א."],["5131","525","<b>אור פני מלך חיים</b>: ע\"פ משלי טז, טו."],["5132","526","<b>כד אנפהא דמלכא נהירין</b>: ראה זהר (אד\"ר) נשא קלג, ב. הנסמן במאמרי אדה\"א נ\"ך ע' לז."],["5133","527","<b>דזרקא מקף סגולתא</b>: ראה זהר בראשית כד, א-ב. מאמרי אדה\"ז תק\"ע ע' קנא. מאמרי אדה\"א דברים ח\"ד ע' א'תסט. וש\"נ."],["5134","528","<b>בענין טנת\"א</b>: ראה מאמרי אדה\"א שם ע' א'תסט ואילך."],["5135","529","<b>ויהי שירו</b>: מלכים-א ה, יב. ראה זהר בהקדמה (ח, א). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תשפא הערה: רננא. תו\"ח בראשית ד, א ובהערה 7."],["5136","530","<b>זמירו\"ת היו לי חוקי\"ך</b>: תהלים קיט, נד. ראה סוטה לה, א. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תשפג. תו\"ח מקץ ריט, ד."],["5137","531","<b>ובלילה שירה עמי</b>: תהלים מב, ט. ראה תו\"ח בראשית לד, ד בהערה 50."],["5138","532","<b>כ</b>: י: כא."],["5139","533","<b>מדות שברצון ותענוג שנק' הרים גדולים</b>: ראה סידור שער האלול רלג, א. מאמרי אדה\"ז תקס\"ב ח\"ב ע' תקל. עט\"ר ע' כז. מאמרי אדה\"א דברים ח\"ג ע' תתקצח."],["5140","534","<b>טורי חשוכא וטורי נהורא</b>: נסמן לעיל פ' שמות טז, א."]]],[2300540923,"בסדר והדרגה מעצמות הנפש ברצון ותענוג ומרצון ותענוג לשכל כו'. אבל ביצ\"מ הי' בחי' דילוג מאור העצמות ממש במדות שבלב שהוא דילוג על המדות שבכתר ומדות דחו\"ב, כי בהתפעלות העצמיות ממש שם כלולים התפעלות הרצון והתפעלות השכל כא' ממש והכל בגילוי בלי סדר והדרגה לבוא בתחלה<sup data-n=\"5141\">535</sup> דרך מיצ\"ר י\"ם והעלמות במיצר הגרון ממוחי' דחו\"ב למדות דלב ודרך קרומא דאוירא מן הכת\"ר שהוא הרצון לחו\"ב כו'. וידוע דכל היוצא מן בחי' המיצר והגלות למרחב<sup data-n=\"5142\">536</sup> כמו שהוא זהו עד\"מ כאסור במאסר בזיקי' וחבלים וכה\"ג דאע\"פ שאין שינוי ניכר בעצמו רק בלבושים דזיקי' וחבלים שהוסרו ממנו והיכל המאסר שהי' נעלם שם במצור ומצוק כו', הנה עכ\"ז יש גם בגופו ופנימיותו שינוי גדול מאד והוא מה שישמח מאד בשמחת הנפש בעצמה ומהותה דוקא במה שיצאה מהעלמה וצמצומה כו'. וכך הוא בהתפעלות עצמות הנפש שיוצאה מן הצמצום והעלם דמיצר הגרון ודרך העורקי' כו' שנאסרה בהן כמו בזיקי' כו' וכיוצא מן המאסר וחבלי' כו'. כך יהי' השמחה בכנ\"י בעצמות הנפש דיחידה בצאתם מגלות כו' שהוא שנק' לידה כמו לידת הולד מבטן אמו שהי' אסור וקשור שם במיצר ודוחק גדול מאד שכאשר יצא לאויר העולם ויראה אור כו' ישמח מאד עד שיבכה מרוב <span data-k=\"pg\">412</span> ּ שמחה כו'. וכך הי' ביצ\"מ שמחת הנפש בעצמה שיצאו ממיצר ודוחק הנפש בלבושים דבינה שמאיר במדות דרך מיצר הגרון וקול כו' וכתיב כימי צאתך<sup data-n=\"5143\">537</sup> מאמ\"צ אראנו נפלאות לע\"ל בעלי' יותר בנהר פרת<sup data-n=\"5144\">538</sup> שיעברו עוד הפעם כמ\"ש עד יעבור<sup data-n=\"5145\">539</sup> כו' והיינו בבחי' לידה מבינה עילאה דא\"א כו' (וכמו בימות המשיח שיראו אור האלקי בעצמות נפשם ממש שלא ע\"י לבוש דחו\"ב כלל כמ\"ש ולא ילמדו<sup data-n=\"5146\">540</sup> כו' וד\"ל) (ובמ\"א מבואר דביצ\"מ הי' רק בחי' אירוסין<sup data-n=\"5147\">541</sup> וכמ\"ש וארשתיך לי באמונה כו', ובמ\"ת הי' בחי' נשואין<sup data-n=\"5148\">542</sup> בחופה וקדושין שאו' הרי את מקודשת לי והכלה שותקת<sup data-n=\"5149\">543</sup> ובשתיקה זו כהודאה דמי'<sup data-n=\"5150\">544</sup> מקודשת<sup data-n=\"5151\">545</sup>. אבל לע\"ל יהי' קול חתן וקול כלה<sup data-n=\"5152\">546</sup> וכן קול ששון וקול שמחה כו' שיהי' בחי' קול גם לכלה ונק' קול גדול ולא יסף<sup data-n=\"5153\">547</sup> בבחי' א\"ס כמו שהי' במ\"ת במשפיע בקול השופר הולך וחזק<sup data-n=\"5154\">548</sup> כו', וזהו סתירה להנ\"ל וד\"ל).",[["5141","535","<b>בתחלה</b>: אב: בתפילה."],["5142","536","<b>והגלות למרחב</b>: אב: להגילוי ומרחב."],["5143","537","<b>כימי צאתך</b>: מיכה ז, טו."],["5144","538","<b>לע\"ל. . בנהר פרת</b>: נסמן לעיל מ, ד."],["5145","539","<b>עד יעבור</b>: בשלח טו, טז."],["5146","540","<b>ולא ילמדו</b>: ירמי' לא, לג."],["5147","541","<b>דביצ\"מ. . אירוסין</b>: ראה שה\"א ט, א ובהערה 8. לעיל קד, א. לקמן קיח, ב."],["5148","542","<b>ובמ\"ת. . נשואין</b>: ראה שה\"א שם ובהערה 9. סידור ברכת נשואין קלו, ד. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתקיט. מאמרי אדה\"א בראשית ע' ריט. ויקרא ח\"א ע' דש. במדבר ח\"ב ע' תיט. לקמן קיח, ב."],["5149","543","<b>הרי את. . והכלה שותקת</b>: ברכת אירוסין. קידושין ה, ב."],["5150","544","<b>ובשתיקה זו כהודאה דמי'</b>: יבמות פז, ב."],["5151","545","<b>ובשתיקה. . מקודשת</b>: ראה סידור ברכת נשואין קלט, א. תו\"ח ח\"ש קמא, ד ובהערה 38. לקו\"ש תצא (כרך ט) ע' 149 הערה 52."],["5152","546","<b>לע\"ל. . וקול כלה</b>: ראה הנסמן במאמרי אדה\"א בראשית ע' ריט הערה: הרי. דרושי חתונה ח\"ב ע' תרלו ואילך."],["5153","547","<b>קול גדול ולא יסף</b>: ואתחנן ה, יט. ראה סידור דרושים לחתונה קלב, סע\"ב ואילך. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תרלח."],["5154","548","<b>בקול השופר הולך וחזק</b>: יתרו יט, יט."]]],[2300540930,"[כא<sup data-n=\"5155\">549</sup> ] והנה מעתה הנה יובן שרש ענין מצה וד' כוסות להיות שעיקר ענין הפסח הוא בחי' הדילוג הגדול הנ\"ל לדלג על המוחי' במדות בלי מצרים ולבושים כלל כנ\"ל, ובשה\"ש א' מדלג על ההרים כו' ובתורה מפורש להיכן הי' הדילוג<sup data-n=\"5156\">550</sup> והוא מ\"ש ופסח ה' על הפתח<sup data-n=\"5157\">551</sup> בראותו הדם על המשקוף וב' המזוזות כו' ולכך נק' חג הפסח ובעובדא תליא מילתא בפסח ומצה כו'. וענין המצה הוא ג\"כ ענין הדילוג שהוא בפסח רק שמתלבש בלבוש והעלם דמצה שהוא בבחי' קטנות דאור אבא דוקא (כמשי\"ת) והקידוש על היין הוא בבחי' מוחין<sup data-n=\"5158\">553</sup> דאימא<sup data-n=\"5159\">552</sup> שמלובש בו מבחי' נה\"י דאבא כו', כענין זכרהו על היין<sup data-n=\"5160\">554</sup> בקידוש דשבת כידוע. וא\"כ הי' ראוי להקדים<sup data-n=\"5161\">555</sup> אכילת מצה שהוא בבחי' קטנות דאבא ששם נמשך ההארה תחלה בבחי' הדילוג מן העצמות שהוא מגבוה לנמוך ביותר ואח\"כ יעלה מנמוך לגבוה [ב]סדר והדרגה מקטנות לגדלות כו', ולמה הקדים הקידוש דמוחי' דאימא תחלה ואח\"כ אכילת מצה דקטנות דאבא כו'. אלא לפי שאין סדר והדרגה כלל בהדרגה הצריכה להיות בחג זה דפסח שהוא בא בבחי' דילוג שלא בסדר והדרגה כלל כשאר המועדי' כו' (וכמשי\"ת הטעם בסמוך), וע\"כ הקדים המאוחר שהוא גדלות דאבא במוחין דאימא<sup data-n=\"5162\">556</sup> [שב]יין דכוס הקידוש וד\"ל. ועוד יש טעם אחר לפי שידוע בשרש קליפה דפרעה שהוא בבחי' עורף<sup data-n=\"5163\">557</sup> ואחוריי' דכתר<sup data-n=\"5164\">558</sup> דקדושה שהוא ההתקשרות בעומק הרצון<sup data-n=\"5165\">559</sup> הז[ר] כו' בבחי' מקיף בהעלם<sup data-n=\"5166\">560</sup> שלמעלה מן הטעם ושכל כו', ולזאת זהו עיקר המונע ומעכב את גילוי התולדה של המדות מבחי' בינה במיצ\"ר הגרון שנק' מצרים מצ\"ר מ\"י להיותו אוחז באחורי העורף כמבואר בכוונות דעבדים היינו אנו בנ\"י ז\"א<sup data-n=\"5167\">561</sup> כו' (והיינו מה שאנו רואי' שמתוך גודל העמקת הרצון והשכל במו\"מ וכל עניני גופו נסתם ונעלם אור התפעלות המדות שבמוח בינה ולא יוכלו לצאת בגילוי בלב כלל כידוע). ולפי שקליפה זאת היא עושה תכלית ההסתר וההעלם דעמ\"ר<sup data-n=\"5168\">562</sup> ע\"כ לא הי' ביכולת האדם האלקי<sup data-n=\"5169\">563</sup> הקטנה דמצה שנק' מיכלא דמהימנותא בבחי' אמונה פשוטה בלא טעם ודעת כלל (כמשי\"ת) שהוא בבחי' קטנות דאבא לעמוד נגד העומ\"ר הנ\"ל, והיו המדות דאוי\"ר בהסתר והעלם עדיין",[["5155","549","<b>כא</b>: י: כב."],["5156","550","<b>הי' הדילוג</b>: א: הוא מדלג."],["5157","551","<b>הפתח</b>: ב: ניתוסף: שדילג על הפתח."],["5158","553","<b>והקידוש. . מוחין דאימא</b>: במאמרי אדה\"ז תקס\"ג כאן (ע' רצ) ”מוחין דגדלות דאבא\". . ”קידוש. . גדלות דאבא שהכוס הוא כלי אבא והיין דכוסות הן מוחין דאמא\". ועד\"ז במאמרי אדה\"א הנחות תקע\"ז כאן (ע' לא). אבל בהנחת הר\"מ שם (מאמרי אדה\"ז תקס\"ג ס\"ע רפג ואילך) הוא ע\"ד כבפנים. וראה בסמוך בפנים. ראה גם מאמרי אדה\"ז על מארז\"ל ע' סג. ביאוה\"ז תזריע עד, ד."],["5159","552","<b>והקידוש. . מוחין דאימא</b>: ראה פע\"ח (שחה\"מ) שכ\"א, פ\"ב. (פ\"ו). פ\"ז."],["5160","554","<b>זכרהו על היין</b>: פסחים קו, א. ראה סידור שער המועדים רכא, ד. לקמן קכ, ג."],["5161","555","<b>וא\"כ הי' ראוי להקדים</b>: ראה גם בהמאמרים שבהערה 553."],["5162","556","<b>גדלות דאבא במוחין דאימא</b>: ראה הערה 553."],["5163","557","<b>דפרעה. . עורף</b>: נסמן לעיל פ' שמות יט, ב."],["5164","558","<b>דפרעה. . ואחוריי' דכתר</b>: ראה גם לעיל לב, ד. וש\"נ."],["5165","559","<b>דכתר. . הרצון</b>: נסמן לעיל פ' וארא עט, א."],["5166","560","<b>בהעלם</b>: א: והעלם."],["5167","561","<b>אנו בנ\"י ז\"א</b>: סידור האריז\"ל פיסקא עבדים היינו."],["5168","562","<b>דעמ\"ר</b>: א: בעומק רום. ואוצ\"ל: בעומק רע."],["5169","563","<b>האדם האלקי</b>: א: הארת אלקות. ב: האר' האלקי'."]]],[2300540937,"במיצ\"ר מ\"י כו' ולא הי' בחי' הלידה שנק' גאולה בשלימות כלל ולא היו ראויים <span data-k=\"pg\">רו</span> ּ לקבלת התורה בבחי' גדלות דאור אבא (לפי שבחי' אור אבא שמלובש באכילת מצה מוסתר ונעלם בבחי' הקטנות מאד, ומצד בחי' ק[ו]טנה בתכלית היתה נבלעת באברי' ולא הי' בט[ו]ל לקליפה דמצרים כלל כי נבלע מעט הטוב ברע כו'). ולכך או' קידוש על היין בכוס תחלה שמעוררי' לבחי' שמחה העצמי' שיצאו ממיצר מי כו' בהגלות נגלות אור העצמות בחו\"ב שבעצמיות הרוחניות דנפש ביין שבכוס זה דקידוש, שהיין הוא פנימי' מוחי' דאימא ונמשך בכוס שהוא כלי אור פנימי' אבא כמו כוסי רוי\"ה<sup data-n=\"5170\">564</sup> כמו כסא דמלכא משיחא<sup data-n=\"5171\">565</sup> כו', לפי שגאולה זו מעין גאולה דלע\"ל בימות המשיח כנ\"ל<sup data-n=\"5172\">566</sup> כימי צאתך כו' [וכמאמר יבא טוב<sup data-n=\"5173\">567</sup> כו'], ובזה נתבטל כל יניקה דפרעה מן העורף כו' ואז יוכלו להמשיך מבחי' מהו\"ע דגדלות דאור אבא במצה שנק' קטנות ד[אור] אבא שיהי' בזה בחי' כלי חומר מוכן לקבל הצורה בגילוי אור פנימי' הח\"ע דמ\"ת פב\"פ אחר ימי הספי' (כמשי\"ת). וזהו ג\"כ ענין ד' כוסות בכלל שהוא בחי' המשכות מוחין דאימא<sup data-n=\"5174\">568</sup> בבחי' הפנימי' שבה שהוא שמחת הנפש בעצמה הנ\"ל שמתגלה בלב שלא ע\"י שכל וטעם כלל רק מצד בחי' אמונה הפשוטה שיצאו מן המיצר דבינה, רק מלובש בעומק הלב לשמח הלב בפנימי' ועצמי' בלי העלם ולבוש דמצרים הנ\"ל והוא בחי' קו השמאל דבג\"ה<sup data-n=\"5175\">569</sup> כמ\"ש אני בינה לי גבורה כו'. והיינו כמו שמשמחים את התינוק ביין המשמח לשמח עצמיות נפשו שלא יהי' לו געגועי' אחר אביו ואח\"כ מאכילים אותו לחם וטעם חטה לחזק עצמות המוחי' שלו כידוע דלחם בחכ'<sup data-n=\"5176\">570</sup> כו'. וזהו ענין כוס של קידוש ביין המשמח בתחלה [לשמח] עצם נקודת יהדותו ממה שיצא מאפילה לאור גדול כיוצא מבית השבי' וכמו גר שנתגייר<sup data-n=\"5177\">571</sup> או בע\"ת אמיתי (כמשי\"ת), כדי שעי\"ז יוכל אח\"כ לקבל בנפשו האלקי' מבחי' ג\"ר דאבא שמלובש בהעלם במצה שנק' מיכלא דמהימנותא שמחזק לכח האמונה הפשוטה העצמי', והוא מה שמהו\"ע דמוחי' דאבא שמשם הוא שרש כל הנשמות כמ\"ש כי אתה אבינו<sup data-n=\"5178\">572</sup> כו' (כמשי\"ת) מלובש ונעלם במצה זו שאנו אוכלים ע\"ש מ\"ה דחכ' עצמה בבחי' קטנות דאור אבא, שזהו בחי' קטנות דאמונה הפשוטה שנק' לחמא עניא די אכלו אבהתנא כו' שלמטה מן הדעת ושרשו למעלה מן הדעת (כמשי\"ת), ואם לא כוס של קידוש ביין המשמח כנ\"ל לא הי' ביכולת לקבל אכילת מצה זו דקטנות דאבא מטעם הנ\"ל וד\"ל.",[["5170","564","<b>כוסי רוי\"ה</b>: תהלים כג, ה."],["5171","565","<b>כסא דמלכא משיחא</b>: ראה יומא עו, א. סידור שחרית נב, ב. תו\"א תולדות יח, סע\"ד ואילך."],["5172","566","<b>כנ\"ל</b>: אב: כמ\"ש."],["5173","567","<b>יבא טוב</b>: נסמן לעיל פ' שמות מג, ד."],["5174","568","<b>מוחין דאימא</b>: א: אור אימא."],["5175","569","<b>קו השמאל דבג\"ה</b>: נסמן לעיל פ' וארא פד, ד."],["5176","570","<b>דלחם בחכ'</b>: נסמן לעיל צג, ב."],["5177","571","<b>גר שנתגייר</b>: ראה הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תקכא."],["5178","572","<b>כי אתה אבינו</b>: ישעי' סג, טז."]]],[2300540944,"[כב<sup data-n=\"5179\">573</sup> ] והנה להבין שרש ענין המצה שנק' מיכלא דמהימנותא והוא בבחי' קטנות דאבא דוקא כנ\"ל. הנה תחלה י\"ל בשרש ענין הפסח בכלל שהוא בחי' הדילוג הגדול שלא בסדר והדרגה כלל<sup data-n=\"5180\">574</sup> כנ\"ל למה הוא שלא [כ]סדר והדרגה בדרך דילוג דוקא, והנה באמת שרש ענין הפסח והמצה א' הוא שהוא ענין ובחי' כל העצמיות דוקא רק שהפסח הוא מלמעלה למטה ממקום הגבוה שהוא מדלג משם כמ\"ש קול דודי הנה זה בא מדלג<sup data-n=\"5181\">575</sup> שהוא מגבוה לנמוך מדלג על ההרים כו', והיינו מצד בחי' גילוי אור המשפיע כמ\"ש ופסח ה' על הפתח כו', ובחי' המצה זהו המקום שלשם הוא מדלג והיינו בהתלבשותו וירידתו למטה מטה בהעלם דקטנות דאור אבא שהוא האמונה הפשוטה כנ\"ל וד\"ל. והנה ענין הפסח שהוא הדילוג היינו בבחי' התפעלות כל העצמיות <span data-k=\"pg\">414</span> ּ דנפש<sup data-n=\"5182\">576</sup> בדילוג על הסדר והדרגות דעו\"ע כמו מרצון לשכל ומשכל למדות אלא הכל כלולים בה<sup data-n=\"5183\">577</sup> כא' להיותה למעלה מהתפעלות רצון ושכל כו'. וזהו אנו רואים גם בבחי' הקטנות דאמונה הפשוטה שהוא המצה שאנו אוכלים לחזק כח האמונה אע\"פ שישראל מאמינים בני מאמינים<sup data-n=\"5184\">578</sup> בירושה כו', מ\"מ ע\"י מצה זו דוקא נתחזק יותר כח האמונה (והוא בחי' אמונה רבה במהו\"ע ית' ממש שהוא למעלה משם הוי' ואלקי' בסובב וממלא<sup data-n=\"5185\">579</sup> כו' שלמעלה מאמונה דאבות כו' כמ\"ש במ\"א שזהו ורעה אמונה<sup data-n=\"5186\">580</sup> שא'<sup data-n=\"5187\">581</sup> בר\"מ דמשה דוקא כו'<sup data-n=\"5188\">582</sup> ) (ואפי' משה הי' חייב באכילת מצה זו בליל א' דפסח), והוא בבחי' מקיף כעטרה ע\"ג הראש שנק' אירוסין [כ]עיגול הטבעת כמ\"ש וארשתיך לי כו'. והטעם הוא שזהו בבחי' קטנות דאבא דוקא כנ\"ל הענין ידוע ומבואר במ\"א<sup data-n=\"5189\">583</sup> שזהו כמו תינוק שא\"י לקרות אבא ואימא עד שיטעום טעם דגן דוקא, כי בטעמו טעם לחם דגן כי הדגן והלחם שרשו בחכמה (דלחם גימ' מזלא כמ\"ש בסידור<sup data-n=\"5190\">584</sup> ) וכשטועמים<sup data-n=\"5191\">585</sup> טעם לחם יש בו מכח עצם ומהות דאור השכל והחכ'<sup data-n=\"5192\">586</sup> [שבנפש] (אע\"פ שקטן אין לו מח'<sup data-n=\"5193\">587</sup> דבינה אבל בחי' כח מקור השכל יש בו בהעלם דמפני זה יודע לצרף אותיות הדיבור כידוע דאבא יסד ברתא כו' וד\"ל<sup data-n=\"5194\">588</sup>. ולכך אין יכול לקרות אבא דוקא בימי היניקה דחלב שעדיין אין בו מבחי' אור החכ' דאבא ואע\"פ שמכיר לאביו ולאמו א\"י לקרות אבא בדיבור בפה עד שיטעום טעם דגן דוקא שאז יש בו הכרה זו להכיר לאביו לקרותו אבא כו'. וכך הוא בנש\"י שנק' בנים<sup data-n=\"5195\">589</sup> בקטנות כילד שא\"י לקרות אבא לומר בפה כמו כי אתה אבינו כבן קטן שנמשך אחר אביו מצד שממנו נלקח, כך נש\"י נמשכים מאליהם לאביהם שבשמים ואו' אתה אבינו כו' כי כל דבר נמשך לשרשו<sup data-n=\"5196\">590</sup> דוקא",[["5179","573","<b>כב</b>: י: כג."],["5180","574","<b>כלל</b>: א: ליתא."],["5181","575","<b>מדלג</b>: אב: ליתא."],["5182","576","<b>העצמיות דנפש</b>: אב: הנפש."],["5183","577","<b>בה</b>: אב: ליתא."],["5184","578","<b>מאמינים בני מאמינים</b>: באוה\"ת תשא ע' א'תתלט־ א'תתעט מציין: במדרש [רבה] פ' שמות פ\"ג דקכ\"א, סע\"ד [פ\"ג, יב]. וראה גם שבת צז, א."],["5185","579","<b>הוי' ואלקי' בסובב וממלא</b>: נסמן לעיל פ' וארא עג, ב."],["5186","580","<b>ורעה אמונה</b>: ראה גם לעיל צב, א. וש\"נ."],["5187","581","<b>שא'</b>: א: ששרשו."],["5188","582","<b>כו'</b>: אב: כנ\"ל."],["5189","583","<b>במ\"א</b>: ראה שה\"א ח, ב."],["5190","584","<b>דלחם גימ' מזלא כמ\"ש בסידור</b>: ראה סידור ר\"ש ראשקוב סדר סעודת ת\"ח (כוונת המוציא) א, ב. סידור אדה\"ז שער בהמ\"ז קז, ד [בשם הע\"ח]. מאמרי אדה\"א ויקרא ח\"א ע' קכב־ דברים ח\"ד ע' א'שסה־ קונטרסים ע' קמו ובהנסמן בהנ\"ל. הנחות תקע\"ז ע' קכט. תו\"ח מקץ רכה, ב. שה\"א ט, א."],["5191","585","<b>וכשטועמים</b>: א: דכשטועם."],["5192","586","<b>השכל והחכ'</b>: אב: החכ'."],["5193","587","<b>שקטן אין לו מח'</b>: ראה חולין יב, ב."],["5194","588","<b>וד\"ל</b>: אוצ\"ל: וד\"ל)."],["5195","589","<b>בנש\"י שנק' בנים</b>: נסמן לעיל צב, א."],["5196","590","<b>כל דבר נמשך לשרשו</b>: נסמן לעיל פ' וארא צה, ב."]]],[2300540951,"כידוע, ואמנם א\"י לקרות אבא עד שיטעום טעם לחם דגן שהוא חטה כ\"ב אותיות דתורה<sup data-n=\"5197\">591</sup> כידוע ומבואר במ\"א וד\"ל.\n<b>אך</b> הנה כ\"ז הוא אינו שייך רק בטועם טעם לחם דוקא לפי שידוע שהטעמי' הוא בחכ' כמו וחיך יטעם אוכל<sup data-n=\"5198\">592</sup> שהוא החכ' שנק' אוכל כטועם טעם מתיקות השכל כו', אבל במצה דלא מליח<sup data-n=\"5199\">593</sup> הרי אין בה שום טעם כלל ואיך יוכל להכיר לאביו לקרות[ו] אבא כנ\"ל. אך הענין הוא דאדרבה היא הנותנת דמשום שאין במצה טעם מורגש כלל יש בה מעלה יתירה דוקא יותר מלחם חמץ שיש בו טעם מורגש. והענין הוא לפי שמפני זה שאין במצה טעם מורגש לחיך כ\"כ ה\"ז למעלה מבחי' הטעם שבחכ' שהוא בחי' היש שבחכ' שנמשך לבינה בשכל וטעם ממש, אלא [הוא] בבחי' כ\"ח מ\"ה דחכ' כמו שהוא בבחי' אי\"ן ממש שזהו בחי' הביטול בעצם דבחי' מ\"ה בעצם כמשה שהי' בביטול עצמי ותמידי לאלקות להיותו מבחי' מ\"ה דחכ' כמ\"ש ונחנו מ\"ה<sup data-n=\"5200\">594</sup> כו'. והיינו בבחי' ראי' מקרוב דוקא כעומד לפני המלך בתמידות שיש בו ביטול פנימי מכל וכל לגמרי בלתי מרגיש עצמו כלל, שזהו למעלה הרבה מן הביטול שבא מצד הטעם והשכל המורגש בבינה ודעת כידוע. וכך הוא בענין לחם דמצה שהוא בלא טעם מורגש כלל להיות [ש]שרשו בבחי' כח מ\"ה דחכ' הנ\"ל רק שהוא שבא בבחי' קטנות המוחין דאמונה הפשוטה ונק' מיכלא דמהימנותא כנ\"ל, כי האמונה היא למעלה מן הטעם ודעת רק שמבטל א\"ע לגמרי מכל וכל רק מצד בחי' <span data-k=\"pg\">רז</span> ּ ההתקשרות העצמי' לפי שנמשך לשרשו שנלקח משם בלבד ונמשך אחר מקור חוצבו כנ\"ל בתינוק שמכיר לאביו ונמשך אחריו וקורא אבא כך ישראל או' אבינו כו' וכנ\"ל. וזהו בחי' ביטול העצמי שבפנימי' החכ' הנק' אבא שהוא מקור השכל הבא בגילוי טעם ודעת שהוא בבחי' הראי' מקרוב ממש כנ\"ל במשה רק שבמצה נסתר ונעלם ביטול עצמי ופשוט זה בבחי' האמונה הפשוטה שהיא בקטנות כתינוק כו'. וזהו לפי שבמצה אין בה טעם מורגש ע\"כ שרשו בעצם דכח החכ' ע\"כ מכיר לאביו שבשמים באמונה פשוטה וקוראו אבא לפי שיש לו השגה והכרה במהו\"ע א\"ס ב\"ה שבאור פנימי' אבא שהוא החכ' כמו כי אתה אבינו, ולא בהשגת מציאותו מרחוק בבינה לבד כמו שע\"י טעם דלחם הגשמי מכיר התינוק למהות אביו כו', משא\"כ בלחם שיש בו טעם מורגש לחיך זהו בבחי' טעם שבחכ' כשמוטעם במורגש בשכל והשגה שהוא בחי' בינה שנק' יש דחכ' ולא כח מ\"ה [דחכ'] כו', וכמו השאור והחמץ שנותן טעם מורגש בעיסת לחם ומנפח העיסה ויש בה התפשטות וגסות בהעלאה והתנשאו' והגבהה למעלה שזהו היפוך הביטול ושפלות דחכ' בהעדר הרגשה והתפשטות לגמרי מכל וכל, והיינו המצה שאין בה התנשאות",[["5197","591","<b>חטה כ\"ב אותיות דתורה</b>: ראה זהר בלק קפח, ב. ת\"ז תס\"ט (קיד, ב. ד). ראה גם לקו\"ת בחוקותי מח, סע\"ב ואילך. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקעא. מאמרי אדה\"א ויקרא ח\"ב ע' תרסג. במדבר ח\"ב ע' תטז. ע' תעא."],["5198","592","<b>וחיך יטעם אוכל</b>: איוב יב, יא [ושם: אוכל יטעם]. לד, ג [ושם: יטעם לאכל]. ראה מאמרי אדה\"א שמות ח\"א ע' קמה. וש\"נ. שה\"א ט, א ובהערה 1."],["5199","593","<b>במצה דלא מליח</b>: ראה שו\"ע אדה\"ז הל' פסח סתנ\"ה, סכ\"ט. שה\"א טו, א (פ\"ו)."],["5200","594","<b>ונחנו מ\"ה</b>: נסמן לעיל פ' שמות מג, א."]]],[2300540958,"וניפוח כלל רק מים וקמח נלושין כמו שהן שהוא בחי' העצמיות כמו שהוא בבחי' הביטול העצמי דכח מ\"ה דחכ' כנ\"ל, שהוא במהו\"ע דאור אבא שהוא מקור של השכל והטעם שבגילוי שאין בו התפשטות והרגשה<sup data-n=\"5201\">595</sup> כלל רק בבחי' אי\"ן ומ\"ה ממש. וזהו שמלובש באמונה שנק' קטנות דאבא שלמטה מן הדעת ששרשו למעלה מן הדעת והשכל המורגש בבינה וד\"ל (ומה שא' עד שיטעום טעם דגן<sup data-n=\"5202\">596</sup> דוקא אין הכונה בטעם מורגש דוקא אלא הכוונה בטעם דגן דוקא שהוא הלחם ששרשו בחכ' דוקא משא\"כ בימי היניקה שהוא רק בחלב דמוחי' דאימא כו'). ומעתה יובן ענין הפסח שהוא בחי' הדילוג מלמעלה למטה כנ\"ל ובחי' מצה הוא מקום ששם הוא הדילוג להתלבש בו כנ\"ל.\n[כג<sup data-n=\"5203\">597</sup> ] והענין הוא דבאמת שרש ענין<sup data-n=\"5204\">598</sup> בחי' הדילוג דפסח הנ\"ל זהו יובן ממה שאנו רואים התפעלות יתירה בכל בחי' העצמות דנפש בכל מי שמתחיל לעורר עצמו להיות עובד ה' שלא הי' בלבו מתחלה שום התעוררות כלל ואדרבה הי' להיפך מקושר בכל מיני רע ותאוה גופני', כמו הבע\"ת האמיתי כשבא לו הרהור תשובה פתאום מעומקא דלבא מאד שאז יהי' חידוש גדול ושינוי מופלג בנפשו בבחי' התפעלות כל עצמות נפשו עד שלא יהי' אצלו סדר והדרגה כלל בעבודת ה' כשאר [כל] אדם, כמו להיות התפעלות השכל תחלה ואח\"כ התפעלות הלב כפי אופן התפעלות השכל וטעם בשבחו ש\"מ כו', אלא יהי' אצלו בחי' התפעלו' כללית והיולית בעצם נקודת יהדותו כמו שהוא בלא טעם ודעת כלל. וא\"כ יהי' אצלו התפעלות הלב עם התפעלות השכל כא' בלי סדר והדרגה וקדימה מזה לזה כלל, לפי שהתפעלות שלו הוא רק בכלל בעצם נפשו שרוצה לדבקה בו ית' בכל לב ונפש ולא ילך עוד בדרך עקלתון שהולך בתחלה, ואע\"פ שהי' לו איזה טעם ודעת בזה לפי שהוא ית' מקור כל החיים כו' ונתעורר בתחלה מטעם זה, אבל כאשר נתפעל בעצמיות שלו נשכח ונעלם הטעם ותהי' התפעלותו למעלה מן הטעם לגמרי ושלא כסדר <span data-k=\"pg\">416</span> ּ והדרגה כלל וכלל כנ\"ל.\n<b>ושרש</b> הענין הוא לפי שהתפעלות זאת באה לו בתכלית ההתחדשות מהיפוך להיפוך ממש שהי' תחלה אחוז וקשור בכל תאוה רעה שהוא תכלית ההיפוך מעבודת ה', וכשנתפעל בכל לבו ברצון אמיתי להתקשר בה' אחד ה\"ז שינוי וחידוש מופלג מן הקצה לקצה בחידוש גדול ורב בנפשו אשר נהפך ממהות למהות כמו מאפילה לאור גדול וכיוצא מבית האסורים מחשך לאור וכה\"ג, שעי\"ז יהי' בו ביטול ושכחה על כל עצמותו לגמרי כי ניזוז הוא ונעתק ממקומו ומהותו הראשון",[["5201","595","<b>התפשטות והרגשה</b>: אב: הרגשה והתפשטות."],["5202","596","<b>שיטעום טעם דגן</b>: ראה גם שה\"א ע' 34. ע' 46."],["5203","597","<b>כג</b>: י: כד."],["5204","598","<b>ענין</b>: אב: ליתא."]]],[2300540964,"לגמרי ונעשה כמו בריה חדשה ממש וכתינוק בן יומו שנולד ויצא לאויר העולם וכה\"ג. וע\"כ בחי' התפעלות [שלו] הוא בעצמיות נפשו בלי סדר והדרגה כלל וכלל דהיינו שמתפעל ברצון ושכל ומדות שבלב כא' בלי סדר והדרגה מזה לזה כי התפעלות שלו בעצמיות ממש ששם שוין כל הכחות רצון ושכל ומדות כו'. וגם מה שהי' צריך להתפעל תחלה במוח ואח\"כ בלב יהופך ויתפעל בלב תחלה ואח\"כ במוח יתפעל<sup data-n=\"5205\">599</sup> משכל והשגה קטנה בהתפעלות גדולה יותר משיתפעל זולתו (הגדול ממנו) משכל והשגה גדולה, כמו רק מבריאת שמים וארץ והשגחה הפרטית וחסד שעשה עמדו כו', שאין בערך נפשו האלקי' להתפעל בפעם אחרת כן, רק מפני שנעתק מכל מקומו ומהותו הראשון לגמרי ומושך בנפשו בכל נקודת יהדותו מכח עצמי' אלקות שאליו נושא את נפשו שזהו שנק' בחילא יתיר<sup data-n=\"5206\">600</sup> כמ\"ש בזהר, וכמשל המדלג וקופץ בכל כחו ביתר מכפי המדה<sup data-n=\"5207\">601</sup> או זורק ומושך בקשת או מגביה בכל כחו משא כבד וכה\"ג. ואמנם אח\"כ כשכלה כח התפעלות והתעוררות החזקה הראשונה שהי' לו בתחלה ויבא לעבוד את ה' כפי ערך עצם הכנת לבו ודעתו ונפשו האלקי' אזי יהי' התפעלות שלו בסדר והדרגה דוקא, דהיינו שמתפעל תחלה במוח ושכל וטעם בהשגה האלקי' ולפ\"ע ההשגה והטעם בלבד כך יתפעל אח\"כ בלב ואח\"כ יבא להתפעלות הרצון שלמעלה מן הטעם [לגמרי] כידוע וד\"ל. ועד\"ז ממש יובן ענין הדילוג דפסח הנ\"ל שזהו מה שהיו בנ\"י בהתחלת נקודת יהדותם עדיין בהתפעלות כל העצמיות כנ\"ל שבא בלא סדר והדרגה כלל כנ\"ל בבע\"ת וכן כמו גר שנתגייר כו' וכה\"ג, וענין מקום הדילוג הזה הוא מתלבש באמונה הפשוטה שהוא בבחי' ביטול [כל] העצמי' במצה שנק' לחם עני שלמטה מן הדעת, אבל הוא למעלה מן הדעת כמו תינוק שמכיר לאביו ונמשך בכל נפשו אחריו וקוראו אבא כו' כנ\"ל.\n[כד<sup data-n=\"5208\">602</sup> ] ואחכ\"ז יובן ההפרש בין חג הפסח לחג השבועות בדרך כלל וכי חג<sup data-n=\"5209\">603</sup> השבועות תלוי בחג הפסח והספירה שאח\"כ, כי הנה כנ\"י היו במצרים בתכלית הירידה והשפלות בגשמיות וברוחניות כמ\"ש וימררו את חייהם<sup data-n=\"5210\">604</sup> בעבודה קשה כו' כלחץ ודחק דעכשיו בטרדות הפרנסה, והן יצאו מנש\"ט דמצרים מאפילה לאור גדול<sup data-n=\"5211\">605</sup> כענין",[["5205","599","<b>יהופך. . יתפעל</b>: אב: ויתפעל."],["5206","600","<b>בחילא יתיר</b>: נסמן לעיל פ' שמות לז, א."],["5207","601","<b>המדה</b>: אב: מדתו."],["5208","602","<b>כד</b>: י: כה."],["5209","603","<b>וכי חג</b>: א: ומה שחג."],["5210","604","<b>וימררו את חייהם</b>: שמות א, יד."],["5211","605","<b>מאפילה לאור גדול</b>: פסחים קטז, ב (במשנה). הגש\"פ פיסקא לפיכך."]]],[2300540970,"התפעלות עצמיות דבע\"ת הנ\"ל דמשכי לי' לקודב\"ה בחילא יתיר כנ\"ל שלא לפ\"ע נשמתם כלל ([ו]היינו למעלה משרש [נשמת]ם בחו\"ב דאצי' ומדות חג\"ת שהן האבות כו') שזהו שנק' דילוג למטה, וכך הי' אתעדל\"ע מלמעלה למטה ג\"כ בבחי' דילוג גדול על ההרים כו' למעלה מן הסדר והדרגה דמוחין ומדות עליונות שלא ע\"י מיצרים ולבושים כלל כנ\"ל. אך זהו בא מצד בחי' ההתחדשות הגדולה שהי' בעצם נפשם [בהיפוך] מן הקצה לקצה שזהו אינו רק בהתחלה של <span data-k=\"pg\">רח</span> ּ נקודת יהדותם כנ\"ל. אבל לאחר שכבר יצאו ממצרים בליל א' דפסח ובאו להתקרב<sup data-n=\"5212\">606</sup> לעבודת ה' מצד עצמם<sup data-n=\"5213\">607</sup> עצם כח<sup data-n=\"5214\">608</sup> נשמתם לבד אז נצטוו על הספירה שיספרו ז' שבועות<sup data-n=\"5215\">*609</sup> דהיינו שיהי' הילוכם בקדש בסדר והדרגה דוקא, והוא ענין ימי הספירה שזהו לברר בתחלה לז' מדות הרעות דק\"נ בבחי' בירור הטוב מן הרע שלא יתערב שום רע ופסולת במדות דקדושה דנשמה האלקי', וזהו בירור המדות הטבעיות דנה\"ב ששרשו בק\"נ כידוע כאשה שסופרת<sup data-n=\"5216\">609</sup> ז' נקיים<sup data-n=\"5217\">610</sup> לטהרתה שתהי' ראוי' ליחוד כו', והוא בא[מרם] היום יום א' לעומר<sup data-n=\"5218\">611</sup> שהוא מאכל בהמה<sup data-n=\"5219\">612</sup> דנוגה שנברר בחי' חסד שבחסד וביום הב' נברר [בחי'] גבורה שבחסד בסדר והדרגה ממדה למדה עד ספי' המל' בשבוע הז' שאחר שנשלם בירור כל הז' מדות במ\"ט הימים שהן מ\"ט שע\"ב<sup data-n=\"5220\">613</sup> כידוע, אז ראויים לקבלת התורה בשבועות שהוא בחי' שער החמשים<sup data-n=\"5221\">614</sup> דבינה כידוע. ודוקא כשמונים הימים בספי' כל א' וא' בסדר והדרגה זא\"ז, וכן במנין השבועות ולא להקדים המאוחר בז' הספי' העליונות כו' כי נברר בחו\"ב שבאי' על הסדר דוקא כנ\"ל בהתפעלות השכל שבמוח תחלה ואח\"כ יתפעל במדות שבלב לברר לז\"מ הרעות כפי הערך שנתפעל במוח דבינה דוקא כו' ואז יהי' חומר מוכן לקבל הצורה כו' שהוא בחי' אור הכתר דתורה בשבועות<sup data-n=\"5222\">615</sup>. אבל בחג הפסח אין בו סדר והדרגה כלל גם להקדים המאוחר כנ\"ל בכוס דקידוש כו' שהוקדם למצה<sup data-n=\"5223\">616</sup> והוא מטעם הנ\"ל להיותו בבחי' הדילוג מבחי' העצמיות ממש כנ\"ל וע\"כ תלוי בו דוקא בחי' כתר דתורה דשבועות, וז\"ש למען תזכור<sup data-n=\"5224\">617</sup> כו' אפי' לימות המשיח והעוה\"ב כידוע וד\"ל.",[["5212","606","<b>להתקרב</b>: א: להתקשר."],["5213","607","<b>עצמם</b>: אב: ליתא."],["5214","608","<b>עצם כח</b>: א: היכר."],["5215","*609","<b>נצטוו. . שיספרו ז' שבועות</b>: ראה גם לקמן קכא, ג. וש\"נ."],["5216","609","<b>הספירה. . כאשה שסופרת</b>: ראה זהר אמור צז, סע\"א ואילך. הנסמן בלקו\"ש אמור כרך כב ע' 119. וראה ג\"כ תוד\"ה וספרה כתובות עב, א."],["5217","610","<b>כאשה שסופרת ז' נקיים</b>: מצורע טו, כח."],["5218","611","<b>היום יום א' לעומר</b>: נוסח ספירת העומר. ראה גם לקמן פ' פקודי תמח, ד."],["5219","612","<b>לעומר שהוא מאכל בהמה</b>: ראה זהר (רע\"מ) אמור צח, א. מאמרי אדה\"א ויקרא ח\"א ע' שה. וש\"נ."],["5220","613","<b>במ\"ט הימים שהן מ\"ט שע\"ב</b>: ראה לקו\"ת במדבר י, ד. תו\"ח נח נח, ב בהערה 30. לקמן פ' בשלח רד, א. יתרו רנה, ג. רסג, ד."],["5221","614","<b>בשבועות. . שער החמשים</b>: ראה גם לקמן קיז, ד. וש\"נ."],["5222","615","<b>הכתר דתורה בשבועות</b>: ראה מאמרי אדה\"ז תקס\"ו ע' ריג. פרשיות התורה ח\"ב ע' תתה ובהנסמן במ\"מ לשם. תו\"א יתרו סט, ב. מאמרי אדה\"א במדבר ח\"ב ע' תלב ואילך. לקמן פ' יתרו רסג, ד."],["5223","616","<b>כו' שהוקדם למצה</b>: אב: ש(הוא) קודם למצה כו'."],["5224","617","<b>למען תזכור</b>: פ' ראה טז, ג. ראה ברכות יב, ב. מאמרי אדה\"א שמות ח\"א ע' צב. דברים ח\"א ע' טז. שה\"א ב, ב ובהערה 25. לעיל צד, ג. צו, ג. לקמן קיח, ג. פ' בשלח קנב, ב. קפה, ג."]]],[2300540063,"<b>בעז\"ה פ' בא תורת אדמו\"ר בליבאוויץ</b>\n<span data-k=\"pg\">קלז</span> ּ[ויהי] בעצם היום הזה<sup data-n=\"5225\">1</sup> יצאו כל צבאות ה'<sup data-n=\"5226\">2</sup> וכו', צבאות בחירי\"ק תחת הצדי\"ק ובשב\"א תחת הבי\"ת שמורה על [ענין] היות[ו] תיבת צבאות טפל ובטל ונכלל בשם ה[וי'], ר\"ל צבאות של ה[וי'] ואינו ענין ודבר בפ\"ע כלל. וי\"ל למה בנביאים א' קדש ה[וי'] צבאות<sup data-n=\"5227\">3</sup> הרי שם צבאות דבר וענין בפ\"ע ואינו נכלל וטפל כלל לשם הוי' אדרבה נק' הוי' צבאות, וכידוע דשם צבאות הוא מן הז' שמות<sup data-n=\"5228\">4</sup> שאינן נמחקים<sup data-n=\"5229\">5</sup> (וכמו שם הוי' ואהי'<sup data-n=\"5230\">7</sup> ושם<sup data-n=\"5231\">6</sup> אל אלקים אדני שדי [ו]צבאות וכמו וארא אל כו' באל שדי<sup data-n=\"5232\">8</sup> כו' וידוע דשם אהי' בכתר<sup data-n=\"5233\">9</sup> [ו]הוי' בחכמה<sup data-n=\"5234\">10</sup> [ו]שם אל בחסד<sup data-n=\"5235\">11</sup> כמ\"ש חסד אל כל היום<sup data-n=\"5236\">12</sup>, [ו]אלקים [ב]בחי' גבו'<sup data-n=\"5237\">13</sup> הוי' ת\"ת<sup data-n=\"5238\">14</sup> כמ\"ש בני גד אל אלקים הוי'<sup data-n=\"5239\">15</sup> וידוע דשם הוי' בא עם כל אחד מהשמות כמו הוי' אד'<sup data-n=\"5240\">16</sup> הוי' אלקים<sup data-n=\"5241\">17</sup> הוי' צבאות<sup data-n=\"5242\">18</sup> וכה\"ג). אך הנה זהו ההפרש בין תורה לנביאים ששם צבאות זה לא נזכר בכל התורה בבחי' שם בפ\"ע רק כמו צבאות הוי' טפל להוי' רק בנביאים נז' צבאות בבחי' שם בפ\"ע כמו ה' צבאות וכה\"ג<sup data-n=\"5243\">19</sup>.\n<b>ולהבין</b> זה אם שם צבאות הוא מן הז' שמות שאינן נמחקין כנ\"ל, למה לא נז' גם בתו' בשם בפ\"ע<sup data-n=\"5244\">20</sup>. והנה יש להקדים תחלה להבין בשרש ענין הז' שמות<sup data-n=\"5245\">21</sup> מהו ענין השמות, דהנה ידוע בס' הקבלה שהשמות נק' בשם כלים<sup data-n=\"5246\">22</sup> בלבד ויש ב' מדרגות בכלים פנימי' הכלים וחיצוני' הכלים, והיינו ב' מיני שמות שם התואר ושם הכינוי, שם התואר בחי' פנימי' הכלי ושם הכינוי<sup data-n=\"5247\">23</sup> בחיצוניות הכלים, ויש עוד מדרגה הג' בשמות והוא הנק' שם העצם כידוע. ויובן זה עד\"מ באדם יש כלי לאור החכמה והוא הנק' מוח החכמה ואם הוא איש חכם מופלג נק' בשם חכם גדול, הרי קריאת שם זה חכם נק' שם התואר. כי מה שנק' חכם אינו ע\"ש החכ' והשכל בפרטות<sup data-n=\"5248\">24</sup> שיש במציאות בכלי מוחו שכבר למד וקבל הרבה חכמה ודעת כו' וילמוד לכל כו', כי זהו נק' שם הכינוי לבד שמכנים לו שם זה דחכם מצד הקבלה שקיבל בכלי מוחו הרבה חכמות והוא פעולת כלי מוחו לבד שפעל ביגיעתו שקיבל<sup data-n=\"5249\">25</sup> ולהשפיע לזולתו כו' ונק' חיצוניות הכלי",[["5225","1","<b>[ויהי] בעצם היום הזה</b>: מיוסד על ד\"ה זה שנאמר בש\"פ בא תקס\"ה בסעודת שחרית ונמצא בג' נוסחאות והם: א) הנחת כ\"ק אדה\"א נמצאת בבוך 2076 עא, ב (לא נגמרה בכתיבה ולא נדפסה לע\"ע). ב) הנחת הר\"מ בן כ\"ק אדה\"ז במאמרי אדה\"ז תקס\"ה ח\"א ע' רו. ג) בתו\"א ס, א — והוא הנחת הר\"מ בשינויים. וראה גם אוה\"ת בא ע' שכז-ט. ד\"ה זה משנת תשמ\"ג. סה\"מ מלוקט ח\"א ע' שעט ואילך. ראה עוד ע\"ד המאמר להלן ברשימות הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["5226","2","<b>[ויהי] בעצם היום הזה. . ה'</b>: בא יב, מא. — בהוספת תיבת ויהי מובא באגדהוזחייאיביג."],["5227","3","<b>קדוש ה[וי'] צבאות</b>: ישעי' ו, ג."],["5228","4","<b>דשם צבאות. . הז' שמות</b>: ראה שבועות לה, א-ב וברי\"ף ורא\"ש שם. רמב\"ם הל' יסוה\"ת פ\"ו, ה\"ב."],["5229","5","<b>הז' שמות שאינן נמחקים</b>: ראה רמב\"ם שם. תו\"ח נח סד, ג הערה 38. מאמרי אדה\"א שמות ח\"א ע' רפה."],["5230","7","<b>ואהי'</b>: שמות ג, יד. ראה כ\"מ לרמב\"ם שם ובמהדורת קאפח. לקו\"ש שמות (כרך כו) ע' 10 ואילך ובהנסמן לשם."],["5231","6","<b>הוי'. . ושם</b>: כ: אהי' ושם הוי'."],["5232","8","<b>וארא. . שדי</b>: וארא ו, ג."],["5233","9","<b>דשם אהי' בכתר</b>: זהר ויקרא יא, א. ראה מאמרי אדה\"א דברים ח\"א ע' רכו. וש\"נ."],["5234","10","<b>[ו]הוי' בחכמה</b>: ראה זהר (רע\"מ) פינחס רנה, ריש ע\"ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קלה."],["5235","11","<b>[ו]שם אל בחסד</b>: נסמן לעיל פ' וארא סו, ב."],["5236","12","<b>חסד אל כל היום</b>: תהלים נב, ג."],["5237","13","<b>[ו]אלקים [ב]בחי' גבו'</b>: נסמן לעיל פ' וארא סו, ב."],["5238","14","<b>הוי' ת\"ת</b>: נסמן לעיל שם."],["5239","15","<b>אל אלקים הוי'</b>: יהושע כב, כב. ראה המשך תער\"ב ח\"א ע' תקנד."],["5240","16","<b>הוי' אד'</b>: חבקוק ג, יט."],["5241","17","<b>הוי' אלקים</b>: בראשית ב, ד. ועוד. ט: כבפנים. כ: ליתא."],["5242","18","<b>(וכמו שם. . צבאות וכה\"ג</b>: ה: ליתא. וכנראה שזהו השמטת המעתיק."],["5243","19","<b>אך הנה. . וכה\"ג</b>: יט: ליתא."],["5244","20","<b>כמו ה'. . בשם בפ\"ע</b>: ניתוסף ע\"פ כ. ובתו\"ח כאן: כו'."],["5245","21","<b>שמות</b>: יביג: ניתוסף שאין נמחקין כנ\"ל. וכנראה שנשתרבב זה כאן משו\"ה ולהבין."],["5246","22","<b>בס' הקבלה שהשמות. . כלים</b>: ראה תו\"ח נח סד, ד ובהערה 46."],["5247","23","<b>שם. . הכינוי</b>: ניתוסף ע\"פ כ."],["5248","24","<b>בפרטות</b>: א: הפרטיות. יביג: הפרטי(ם)."],["5249","25","<b>שקיבל</b>: איב: לקבל."]]],[2300540101,"לבד כנ\"ל<sup data-n=\"5250\">26</sup> אין זה שייך לעצם כלל<sup data-n=\"5251\">27</sup> חכמתו כ\"כ ונק' ג\"כ שם הפעולה כו'. אבל שם התואר הוא מה שנק' בשם חכם ע\"ש עצם כלי חכמתו דוקא<sup data-n=\"5252\">28</sup>, כי מה שלמד וקיבל הרבה במוחו יש לו שיעור והפסק כפי ערך שקיבל גם אם [מ]תחכם בזה הרבה<sup data-n=\"5253\">29</sup> יותר, ואע\"פ שיש מציאות אור החכמה במוחו ממש ונק' אור בכלי אבל הוא מדוד [ב]שיעור והגבלה כו'. אך בחי' שם התואר הוא הנק' פנימי' הכלי כנ\"ל, היינו מה שכלי מוחו הוא בחי' כלי קיבול לקבל ולהעמיק [בכל] חכמה ושכל להשכיל בו בכל פעם שילמוד, אע\"פ שאין מציאות החכמה עצמה במוחו עדיין זהו הנק' שם התואר מה שיתואר בעצם הכלי של החכמה בכלל ולא שנק' ע\"ש לימוד [ה]חכמה בפרט בלבד, אלא כל שכל וחכמה ישכיל לעומקו יותר מזולתו מפני שהכלי של המוח שלו רחב<sup data-n=\"5254\">30</sup> ביותר שנק' זה כח היולי ועצמי, רק מפני שאין זה חכמה ושכל עצמי אלא שהוא בחי' כלי לקבל כללות כל אור<sup data-n=\"5255\">31</sup> וחכמה נק' שם התואר שמתאר את כח עצם החכמה כנ\"ל. וזהו הנק' פנימי' הכלי שמתאחד עם אור העצם שהוא אור [ו]עצם [כח] השכל [והחכמה] שנק' שם העצם, כמו שנק' איש חכם גדול ע\"י<sup data-n=\"5256\">32</sup> אור החכמה בעצם כחכמת שלמה וכה\"ג שהי' שופע בו ממקור החכמה העליונה בלי שיעור וגבול כלל<sup data-n=\"5257\">33</sup> בכל חכמה ומדע וד\"ל<sup data-n=\"5258\">34</sup> [ו]כמ\"ש וה' נתן חכמה לשלמה<sup data-n=\"5259\">35</sup> <span data-k=\"pg\">276</span> ּ וכן יהיב חכמתא לחכימין<sup data-n=\"5260\">36</sup>, שיש בזה ב' דברים, א' בחי' האור שזהו שפע העליונה מלמעלה למטה להיות כח רב בעצם כח השכל ש[י]איר בתוס' מרובה כמעיין המתגבר [ל]ה[ו]ציא מושכלות עמוקות בלי שיעור כלל, והב' בחי' כלי המוח שיכול להעמיק ולקבל כל חכמה ושכל שנק' גם זה חכם כנ\"ל אלא שהוא שם התואר שמתאר לעצם כח ואור השכל כתואר הפנים שמראה על העצם שנק' צלם וצורה עצמית כנ\"ל<sup data-n=\"5261\">37</sup>, וע\"כ מתאחדים והיו לאחדים ממש כמ\"ש יהיב חכמתא לחכימין דוקא, ולכאורה אם הם חכימין מה הם צריכים למתנה זו דחכמה, אלא חכימין הם בבחי' הכלי' שהוא שם התואר שלהם ראוי ליתן השפע האור דחכמה בכללות ולא למי שאין להם כלי לקבל עצם החכמה וזה מדבר בכח החכמה ההיולית בכלל דוקא, משא\"כ החכמת שלמה<sup data-n=\"5262\">38</sup> כפי ערך כלי קבלת[ו] [ב]יגיעה בפרט[י] שכל[יי]ם זהו חיצוניות כלי חכמתו",[["5250","26","<b>כנ\"ל</b>: אויאיב: כי."],["5251","27","<b>כלל</b>: יאיב: כלי."],["5252","28","<b>דוקא</b>: איאיב: ליתא."],["5253","29","<b>הרבה</b>: איאיב: ליתא."],["5254","30","<b>רחב</b>: איאיב: מוכן."],["5255","31","<b>אור</b>: איאיב: מקור ושכל."],["5256","32","<b>ע\"י</b>: איאיב: ע\"ש."],["5257","33","<b>וגבול כלל</b>: איאיב: ליתא."],["5258","34","<b>וד\"ל</b>: איאיב: ליתא."],["5259","35","<b>וה' נתן חכמה לשלמה</b>: מלכים-א ה, כו."],["5260","36","<b>יהיב חכמתא לחכימין</b>: דניאל ב, כא. וראה ד\"ה זה במאמרי אדה\"א נ\"ך ע' תקכג."],["5261","37","<b>כנ\"ל</b>: יאיב: כו'."],["5262","38","<b>החכמת שלמה</b>: יאיב: החכמה שלומד."]]],[2300540139,"כמו שהוא פועל בידים פעולה ומלאכה שמזה לא יתואר כלל כח העצם של חכמתו רק בחי' התפשטות[ה] לבד וד\"ל. ונמצא מובן מזה שקריאת שם חכם קטן וגדול<sup data-n=\"5263\">39</sup> ימצא בו ג'<sup data-n=\"5264\">40</sup> אלה בכח ואור עצם חכמתו ברוב תגבורת השפע הנשפע ממקור החכמה שזהו נק' אור מקיף הא' הוא נק'<sup data-n=\"5265\">41</sup> שם העצם, והב' בחי' הכלים של עצם כח החכמה שהוא פנימיות הכלי בכל חכמה להשכיל ולהעמיק כנ\"ל כמו הנה ישכיל<sup data-n=\"5266\">42</sup> כנ\"ל יש חכם קטן וגדול כנ\"ל<sup data-n=\"5267\">43</sup>, והג' בחכמה שכבר למד וקיבל בכלי המוח וש[ו]פע לזולתו שנק' חכם ע\"ש התפשטות כח חכמתו לבד שנק' שם הכינוי כנ\"ל וד\"ל (ומ[מ]ה שאנו רואים שאיש זה [כלי מוחו] מסוגל לחכמת רפואה לבד וזה לחכ' אחרת<sup data-n=\"5268\">44</sup> ולא לזולתה וכה\"ג זהו [ג\"כ] מצד בחי' כלי התואר שמתאחד עם העצם וזהו עצם כח חכמתו אינו מסוגל רק לכח חכמה<sup data-n=\"5269\">45</sup> זו דוקא<sup data-n=\"5270\">46</sup> כו' אע\"פ שנק' כח היולי להשכיל בכל חכמה [וכמ\"ש במ\"א וד\"ל]). והנה עכ\"פ מובן מכ\"ז שבחי' שם חכם שהוא בחי' שם התואר אינו רק ע\"ש בחי' הכלי לקבל [כל] חכמה, אבל מצד גופ[ה] של החכמה שנק' אור אינו במציאות קריאת שם התואר אלא נק' שם העצם [ו]עכ\"ז יהי' איך שיהי' נתאחדו יחד בין בבחי' פנימי' הכלי שזהו כח ההיולי לקבל כל חכמה ובין בחיצוני' הכלי כאשר ישכיל שכל פרטי במוחו וד\"ל. וכמו\"כ יובן במדות כמו אור החסד ואור הגבורה שיש בזה ג\"כ ב' מיני שמות הן ב' מיני כלים הנ\"ל שם התואר שמתאר לעצם כח חסדו שנק' פנימי' הכלי ושם הכינוי ברוב<sup data-n=\"5271\">47</sup> פעולת [ו]התפשטות החסד רק<sup data-n=\"5272\">48</sup> שעשה ושעושה כו' וכן במדת הגבו' והדין להיפוך, ושם העצם הוא ע\"ש עצם כח החסד כמו שהוא טרם שיתואר בכלי הפנימיות ויכונה בשם הכינוי או שם הפעולה כנ\"ל באור החכמה וד\"ל.\n[ב] <b>ומעתה</b> הנה יובן בנמשל [למעלה] מכל הנ\"ל בבחי' ז' שמות שאינן נמחקים כמו אל אלקים כו' שיש בזה ב' מדרגות פנימי' הכלי[ם] וחיצוני' הכלי[ם] שזהו שם התואר ושם<sup data-n=\"5273\">49</sup> הכינוי ושם הפעולה כו'. דהנה ידוע בענין ע\"ס דאצי' שנאצלו מעצמות המאציל הן בבחי' או\"כ דהיינו חכמה מוחא חסד כו'<sup data-n=\"5274\">51</sup> דרועא<sup data-n=\"5275\">50</sup> ימינא<sup data-n=\"5276\">52</sup> כו' וכה\"ג, <span data-k=\"pg\">קלח</span> ּ ומצד בחי' האורות דע\"ס שכלולים בעצמות ממש אמר לאו דאית לך צדק<sup data-n=\"5277\">53</sup>",[["5263","39","<b>קטן וגדול</b>: יאיב: גדול וקטן."],["5264","40","<b>בו ג'</b>: יאיב: בג'."],["5265","41","<b>הא' הוא נק'</b>: יאיב: והוא הנק'."],["5266","42","<b>הנה ישכיל</b>: ישעי' נב, יג."],["5267","43","<b>קטן וגדול כנ\"ל</b>: יאיב: גדול וקטן."],["5268","44","<b>אחרת</b>: יאיב: מוזיקא."],["5269","45","<b>לכח חכמה</b>: יאיב: לחכמה."],["5270","46","<b>מסוגל. . חכמה זו דוקא</b>: ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' עד. תקס\"ח ח\"א ע' תמ. דרך חיים לא, ב. מאמרי אדה\"א דברים ח\"ב ע' תרלה ואילך."],["5271","47","<b>ברוב</b>: יאיב: בטוב."],["5272","48","<b>רק</b>: יאיב: רב."],["5273","49","<b>ושם</b>: יאיב: או."],["5274","51","<b>כו'</b>: איאיב: ליתא."],["5275","50","<b>חכמה. . דרועא</b>: נסמן לעיל פ' שמות כח, ד."],["5276","52","<b>ימינא</b>: איאיב: ליתא."],["5277","53","<b>לאו דאית לך צדק</b>: ת\"ז בהקדמה (יז, ב)."]]],[2300540176,"ומשפט<sup data-n=\"5278\">54</sup> ידיעא דאיהו דין<sup data-n=\"5279\">55</sup> עד ולאו מכא\"מ כלל כמ\"ש בס\"י ע\"ס בלי מ\"ה<sup data-n=\"5280\">56</sup> בלי מ\"ה<sup data-n=\"5281\">57</sup> בלי מהות כו' (ומ\"ש דאיהו וחיוהי חד<sup data-n=\"5282\">58</sup> הכל בבחי' א\"ס הרי עכ\"פ יש חכמה וחסד בבחי' א\"ס כמו ולתבונתו אין מספר<sup data-n=\"5283\">59</sup> וחסדי ה' כי לא תמנו<sup data-n=\"5284\">60</sup> כו', אבל אינו נק' במציאות אור מוגבל רק בהיותו בכלי דוקא ומ\"ש<sup data-n=\"5285\">61</sup> דאיהו וגרמוהי ג\"כ חד<sup data-n=\"5286\">62</sup> שהן הכלים בבחי' פנימי' הכלי<sup data-n=\"5287\">63</sup> דוקא), אבל מצד התלבשות האורות דע\"ס בכלים המגבילים ומתארים את האורות נק' [ב]שם כמו<sup data-n=\"5288\">64</sup> אור החכמה ואור החסד, שהן נק'<sup data-n=\"5289\">65</sup> שמות ע\"ד הנ\"ל במשל קריאת שם חכם שהוא רק ע\"ש כלי חכמ[תו] שיוכל לקבל כל חכמה או חסדן ע\"ש כלי חסדו שמוכן לעשות חסד תמיד שזהו נק' פנימי' הכלים שאור עצם החכמה שורה בו ופנימי'<sup data-n=\"5290\">66</sup> הכלי שאור עצם החכ'<sup data-n=\"5291\">67</sup> שורה בו [ו]נק' שם התואר שמתאר לעצם האור. כך הוא ע\"ד הנ\"ל באור החכמה העצמי' הנאצל [ששורה] בכלי מוחו אז הוא הנק' חכים ולא בחכ' ידיעא<sup data-n=\"5292\">68</sup> כו' [ו]זהו חכ' מוחא או\"כ כו', וכך הוא בשאר הספי' וכמו שם אל הוא בחי' כלי לאור החסד הנאצל שנק' שם התואר לתאר לאור עצם החסד כו', וכן בשם אלקים שהוא בחי' כלי לאור הגבורה וזהו פ[נימ]י' הכלים שמתאחדים עם האורות (וע\"כ אמר דאיהו וגרמוהי ג\"כ חד כו' וכנ\"ל דשם התואר מתאחד עם האור בעצם כמו יהיב חכמתא לחכימין כו'). והמדריגה הב' בז' שמות שאינן נמחקין הנ\"ל<sup data-n=\"5293\">69</sup> הוא בבחי' חיצוניות הכלים וכמו שם הכינוי ושם הפעולה כנ\"ל. והענין הוא כידוע בפי' שם אלקים או שם אדני שהוא לשון שררה<sup data-n=\"5294\">70</sup> ואדנות שהוא על זולתו דוקא כמו נשיא אלקים אתה בתוכינו<sup data-n=\"5295\">71</sup> כו' [או] אדון [כל] הארץ<sup data-n=\"5296\">72</sup>, וגם שם אל הוא בבחי' שפע אור חסד שנמשך למטה מאצי' לבריאה ומבריאה ליצי' כו' עד שזן את [כל] העולם בחסד כו' כמ\"ש כי חסד אל<sup data-n=\"5297\">73</sup> כל היום, וכן אל רחום וחנון<sup data-n=\"5298\">74</sup> נמשך עד למטה שהוא אל רחום וחנון למחול ולסלוח חטא ועון בפו\"מ [ו]כמו מי אל כמוך<sup data-n=\"5299\">75</sup> נושא עון כו', וכן אל [לשון כח<sup data-n=\"5300\">76</sup> ] כמו לשון ו[את] אילי הארץ לקח<sup data-n=\"5301\">77</sup> והוא שם אל [מ]אלקים דאלקים הוא [ג\"כ] כח<sup data-n=\"5302\">78</sup> אלקי המהווה את כל העולמות והוא בבחי' כלי הגבורה והוא הצמצום<sup data-n=\"5303\">79</sup> דוקא משום דבלתי הצמצום א\"א שיהי' בריאה מאין ליש וכן<sup data-n=\"5304\">80</sup> שם אדני אדון ומושל<sup data-n=\"5305\">81</sup> על כול[א] ש[ב]זה עיקר שפע האלקי להחיות הנבראים [ו]כמ\"ש מלכותך מלכות כ\"ע<sup data-n=\"5306\">82</sup> כו'.",[["5278","54","<b>ומשפט</b>: יאיב: ליתא."],["5279","55","<b>דין</b>: יאיב: דין כו'."],["5280","56","<b>ע\"ס בלי מ\"ה</b>: ס\"י פ\"א, מ\"ב ובמפרשים שם."],["5281","57","<b>בלי מ\"ה</b>: יאיב: ליתא."],["5282","58","<b>דאיהו וחיוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["5283","59","<b>ולתבונתו אין מספר</b>: תהלים קמז, ה [ושם: לתבונתו — ראה מאמרי אדה\"א בראשית ע' עח. וש\"נ. תו\"ח בראשית יח, א. ח\"ש קלא, א]."],["5284","60","<b>וחסדי ה' כי לא תמנו</b>: איכה ג, כב. ראה לקמן פ' בשלח קעא, ב. שעה\"י קטו, ב."],["5285","61","<b>ומ\"ש</b>: ויאיב: וכמ\"ש. א: כבפנים."],["5286","62","<b>דאיהו וגרמוהי. . חד</b>: ת\"ז בהקדמה (ג, ב)."],["5287","63","<b>בבחי' פנימי' הכלי</b>: יאיב: דהיינו בפנימיות הכלים."],["5288","64","<b>כמו</b>: א: ליתא. ויאיב: כבפנים."],["5289","65","<b>שהן נק'</b>: יאיב: שזהו הנק'."],["5290","66","<b>ופנימי'. . שורה בו</b>: א: בפנימי'."],["5291","67","<b>החכ'</b>: ויאיב: החסד."],["5292","68","<b>חכים ולא בחכ' ידיעא</b>: ת\"ז בהקדמה (יז, ב). ראה לקמן פ' יתרו רסו, סע\"ד ואילך."],["5293","69","<b>הנ\"ל</b>: יאיב: הכל."],["5294","70","<b>אלקים. . לשון שררה</b>: נסמן לעיל פ' וארא ס, א."],["5295","71","<b>נשיא אלקים אתה בתוכינו</b>: ח\"ש כג, ו."],["5296","72","<b>אדני. . אדון [כל] הארץ</b>: נסמן לעיל פח, ג."],["5297","73","<b>כי חסד אל</b>: תהלים נב, ג [בהוספת תיבת כי — ראה לקמן פ' בשלח רמא, ב. רמד, א. יתרו רנח, א. ד\"ה בכ\"ה בכסליו מכ\"ק אדה\"א קה\"ת תשמ\"ט ע' 4]. א: חסד."],["5298","74","<b>אל רחום וחנון</b>: תשא לד, ו."],["5299","75","<b>מי אל כמוך</b>: מיכה ז, יח."],["5300","76","<b>אל [לשון כח]</b>: ראה פרדס (שער השמות) ש\"כ, פ\"ה. (שעה\"כ) שכ\"ג, מערכת אל ההודאות. או\"ת תהלים (מח, ב) ע, ג."],["5301","77","<b>ו[את] אילי הארץ לקח</b>: יחזקאל יז, יג. או: ואילי — ראה ש\"א לו, א."],["5302","78","<b>דאלקים. . כח</b>: נסמן לעיל עה, ב."],["5303","79","<b>דאלקים. . הצמצום</b>: נסמן לעיל פ' שמות לד, ד."],["5304","80","<b>וכן</b>: א: כבפנים. ויאיב: ונק'."],["5305","81","<b>ומושל</b>: איאיב: ומל'."],["5306","82","<b>מלכותך מלכות כ\"ע </b>[או: ב' תיבות אחרונות ליתא]: תהלים קמה, יג."]]],[2300540213,"<b>ונמצא</b> דבכל שמות אלה דאל ואלקים ואד' [וכן] שדי [ו]צבאות הכל הוא בבחי' השפע [וההמשכה למטה דוקא וזהו בחי' חיצוני' הכלים שהוא שם הפעולה] והכינוי ע\"ש פעולת[י]ו, ושם הכינוי הוא [ע\"ש] הדבר שנמשך ע\"ש<sup data-n=\"5307\">83</sup> שפע פרנסה או שפע חיים או<sup data-n=\"5308\">84</sup> רפואה, וכה\"ג יש כינוי לשפע החכמה בפ\"ע וזהו שמכווני' [בש\"ע] בברכות דאתה חונן ורפאינו וברך עלינו כו' שיומשך לאדם למטה בפו\"מ כידוע וד\"ל. וזהו הנק' שמות בחיצוניות כמו שמו של אדם ראובן שאינו רק כדי שיקרא זולתו אותו<sup data-n=\"5309\">85</sup> בשם זה לפנות אליו ובלא שם זה אין לו<sup data-n=\"5310\">86</sup> תפיסא בו כלל [כידוע], ככלי שאין בה בית יד וע\"י הבית יד יכולין לתפסה בו לפנותה<sup data-n=\"5311\">87</sup> לכל <span data-k=\"pg\">278</span> ּ צד שירצה<sup data-n=\"5312\">88</sup> כו', אבל האדם לעצמו אין צריך שם כלל כידוע. אך זהו בשם החיצוני' שהוא בשביל שיותפס בו לזולתו שהוא לחוץ ממנו, אבל שם התואר הוא לעצמו דוקא שהוא שמו המיוחד לו להורות ולתאר לעצם מהות[ו] גם מבלי נצרך להתפס לגבי זולתו, והוא ג\"כ שם העצם שא\"א לקרות לו שם אחר רק שם זה כמו קריאת שמות דכ\"ב אותיות אל\"ף בי\"ת גימ\"ל כידוע שא\"א לקרות לתמונת האל\"ף כ\"א באות[ו] השם אל\"ף וכן אות הבי\"ת לא יקרא בשם אחר רק בי\"ת וכה\"ג, ובאמת אין טעם כלל בזה למה יקרא תמונת אות זה כך ואות זה כך אלא רק מפני ששמות הללו מת[ו]ארים ומורים על עצם האות כמו שהוא [ממש] ע\"כ א\"א לקרות[ו] בשם אחר כלל כו', [ו]עכ\"ז יש תועלת בקריאת שמות [ל]אותיות שיוכלו להתפס בקריאה בפה בדבור כמו שקורין לאדם בשמו שזהו בחי' חיצוני' השם כנ\"ל וד\"ל. ונמצא מובן מזה בענין<sup data-n=\"5313\">89</sup> קריאת שמות באותיות יש ד'<sup data-n=\"5314\">90</sup> מדרגות הנ\"ל בשמות דאלקים ואדני וכה\"ג, [ד]מה שקורין ומכוונין בשמות אלה להביא שפע ע\"י למטה מאצי' לבי\"ע נק' חיצוניות השמות במה שיותפסו להמשיך שפע [למטה] שנק' שם הפעולה ושם הכינוי לכל פרט הטפל<sup data-n=\"5315\">91</sup>, וז\"ש לכו וראו<sup data-n=\"5316\">93</sup> מפעלות אלקים<sup data-n=\"5317\">92</sup> [אלקי'] דוקא אשר<sup data-n=\"5318\">94</sup> שם שמות בארץ א\"ת ש’מות אלא ש מות שזהו בשביל השפע לעולמות כנ\"ל, אבל בחי' פנימיות הכלי[ם] הוא בחי' שם התואר [והעצם באו\"כ שלמעלה מבחי' שפע למטה כלל רק הוא שם כל ספי' ומדה המיוחד לה שמורה על העצם שנק' שם התואר ו]שם העצם כנ\"ל וד\"ל.\n[ג] <b>והנה</b> ז' שמות שאינן נמחקין הנ\"ל מאחר שאסור למחקן הרי הוא בבחי' אלקות ממש בלתי נפרד מבחי' יחודו האמיתי ית' וכמ\"ש דאיהו וחיוהי חד איהו וגרמוהי חד [בהון] כו', והיינו בין בפנימיות הכלי' בין בחיצוניות הכלי' שהוא כמו",[["5307","83","<b>ע\"ש</b>: יאיב: אם."],["5308","84","<b>או</b>: א: או שפע."],["5309","85","<b>שמו. . שיקרא זולתו אותו</b>: ראה לעיל פ' וארא סט, ב. וש\"נ."],["5310","86","<b>לפנות. . זה. . לו</b>: יאיב: שיפנה. . ליתא. . ליתא."],["5311","87","<b>בה. . לתפסה. . לפנותה</b>: או: לו. יא: בו. . או: להתפס. יאיב: לתפוס. . יאיב: להפנותו."],["5312","88","<b>שירצה</b>: או: ליתא."],["5313","89","<b>מזה בענין</b>: ויאיב: מכל הנ\"ל מענין."],["5314","90","<b>יש ד'</b>: יאיב: לב'."],["5315","91","<b>פרט הטפל</b>: יאיב: פרטי השכל."],["5316","93","<b>וראו</b>: יאיב: חזו."],["5317","92","<b>לכו וראו מפעלות אלקים</b>: תהלים סו, ה."],["5318","94","<b>לכו חזו מפעלות אלקים. . אשר. . שמות</b>: נסמן לעיל פ' וארא ס, ד."]]],[2300540245,"חיצוני' השמות דשם אלקים ושם אדנ\"י שמשפיעי' כל שפע למטה בבי\"ע. ויש להבין בזה דבשלמא בחי' שמות וכלים דע\"ס דאצי' כמו שהן באצי' דאיהו וחיוהי וגרמוהי חד כו' בבחי' אלקות עצמו ממש ע\"כ אסור למחוק הז' שמות כו', אבל בחי' חיצוני' [השמות ו]הכלים דע\"ס שנמשך מהם לבי\"ע אין זה בחי' אלקות עצמו ולמה ז' שמות שאינן נמחקין הרי האסור הזה בחיצוניות השם דוקא הכתוב בקלף ודיו גשמי. אלא צ\"ל דגם אור השפע אלקות הנמשך משמות וכלים [ה]חיצוני' [ש]נק' בשם אלקות ממש וכמ\"ש מפעלות אלקים אשר פעל ועשה, אע\"פ שגוף הבריאה וגוף השפע שכבר נתקבל בבריא'<sup data-n=\"5319\">95</sup> הוא בבחי' גבול אבל כח הפועלם ובוראם הוא מאין האלקי ממש, וכן אור השפע הנמשך משם האלקי' עצמו הוא בא, וע\"כ גם חיצוניות השמות אסור למחוק כמו ונוקב שם ה'<sup data-n=\"5320\">96</sup> כו' ונוקב לשון פגם ומחק כו'. והיינו כמו אותיות שנבראו בהם שמים וארץ<sup data-n=\"5321\">97</sup> [כ]מאמר יהי אור<sup data-n=\"5322\">98</sup> כו' אע\"פ שאותיות הללו נשפעים למטה אבל הם עצמם נק' בורא ולא נברא וכמ\"ש בצלאל הי' יודע<sup data-n=\"5323\">99</sup> לצרף אותיות שנבראו בהם שמים וארץ (משא\"כ אורות<sup data-n=\"5324\">100</sup> שיצאו למטה בבחי' נפרד מיחוד העליון דאצי' שנק' כח הפועל אלקי שבתוך הנפעל ונברא והן ג' עולמות בי\"ע וכמשי\"ת).\n<b>והנה</b> דרך כלל [ה]ז' שמות שאינן נמחקין הנ\"ל הגם שיש בכאו\"א פנימיות וחיצוניות כנ\"ל מ\"מ עיקר כללות הפנימי' של כל א' מהם הוא שם הוי' דוקא, הגם ששם הוי' בכלל הז' שמות הוא מ\"מ יש בו יתרון מעלה מכולם, שהרי שם הוי' הוא בחי' שם העצם<sup data-n=\"5325\">101</sup> <span data-k=\"pg\">קלט</span> ּ [בכללות ו]כמ\"ש וארא אל כו' באל שדי כו' הרי ב' שמות דאל שדי נראה להם וש[מי] הוי' לא נודעתי להם כו' (ואע\"פ שכמה פעמים נז' בהם שם הוי'<sup data-n=\"5326\">102</sup> [הוא בחי' ת\"ת כו'). וכמו שאנו מוצאים שאצל כל שם משמות דאל ואלקים ואדנ\"י נזכר שם הוי'] בכמה מקומות כמו הוי' אד' הוי' אלקי' ואל הוי'<sup data-n=\"5327\">103</sup> והוי' צבאות וכה\"ג רבים בכתובים, והיינו מפני ששם הוי' יש בכל ספי'<sup data-n=\"5328\">104</sup> ומדה דאצי' כמו באור החסד דאצי' שהכלי שלו הוא שם אל יש בו שם הוי' של בחי' חסד דאצי', שהוא בחי' הפנימי' של האור [ו]חסד זה דאצי' ע\"כ ממילא הוא פנימי' דפנימי') (פי'<sup data-n=\"5329\">105</sup> הכלי חסד שהוא שם אל וכמו ויקרא הוי' הוי' אל רחום<sup data-n=\"5330\">106</sup> וכו', וזהו מי כמוך באלים הוי'<sup data-n=\"5331\">107</sup>. וכן במדות וספי' דגבורה דשם אלקים נזכר בו שם הוי' אלקים תמיד לפי ששם זה הוא<sup data-n=\"5332\">108</sup> פנימי' האורות וכלים דשם אלקי', וכן בהוי' צבאות וכה\"ג. ואע\"פ ששם הוי' סתם גם הוא באורות וכלים",[["5319","95","<b>בבריא'</b>: יאיב: בברואים."],["5320","96","<b>ונוקב שם ה'</b>: אמור כד, טז."],["5321","97","<b>אותיות. . שמים וארץ</b>: נסמן בהערה 99."],["5322","98","<b>יהי אור</b>: בראשית א, ג."],["5323","99","<b>בצלאל הי' יודע</b>: ראה ברכות נה, א."],["5324","100","<b>אורות</b>: איאיב: אותיות."],["5325","101","<b>הוי'. . שם העצם</b>: ראה כ\"מ לרמב\"ם הל' ע\"ז פ\"ב, ה\"ז. פרדס (שער שם בן ד) שי\"ט, פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' תכו."],["5326","102","<b>שכמה פעמים נז' בהם שם הוי'</b>: ראה גם לקמן פ' בשלח קמט, ד. מאמרי אדה\"א שמות ח\"א ע' כט וס\"ע לד ואילך. תו\"ח לך פה, ד ובהנסמן במ\"מ לשם."],["5327","103","<b>ואל הוי'</b>: תהלים קיח, כח."],["5328","104","<b>ששם הוי' יש בכל ספי'</b>: ראה גם תו\"ח נח סד, ג ובהנסמן במ\"מ לשם."],["5329","105","<b>דפנימי') (פי'</b>: איאיב: לפנימי'."],["5330","106","<b>ויקרא. . רחום</b>: תשא לד, ו."],["5331","107","<b>מי כמוך באלים הוי'</b>: בשלח טו, יא."],["5332","108","<b>זה הוא</b>: יאיב: הוי' זהו."]]],[2300540276,"בפ\"ע והוא במדת וספי' הת\"ת כו'<sup data-n=\"5333\">109</sup> שכלול מחו\"ג<sup data-n=\"5334\">*110</sup> דאל ואלקי' כמ\"ש אל אלקי' הוי' כו'. אבל באמת כל אור הנאצל באצי' [ב]כל הע\"ס א\"א כ\"א ע\"י ד' אותיות דיו\"ד ה\"א וי\"ו ה\"א כו' יו\"ד צמצום וה\"א התפשטות<sup data-n=\"5335\">110</sup> כו', ונק' הוי' של האור הנאצל מעצמות המאציל כמו אור החסד הנאצל א\"א כ\"א ע\"י אותיות דהוי' כו', ועד\"ז כל הספי' א\"כ הרי שם הוי' הוא בחי' הפנימי' של כל ספי' וזהו שם מ\"ה מלגיו<sup data-n=\"5336\">111</sup> דאיהו אורח כל האצי'<sup data-n=\"5337\">*112</sup> וד\"ל). וזהו<sup data-n=\"5338\">112</sup> הכוונה הפשוטה בשמע ישראל<sup data-n=\"5339\">113</sup> הוי' אלקינו כו'<sup data-n=\"5340\">114</sup> שנמשך להיות [אלקינו] בשם וכלי [דשם הוי'] הוא הוי' אחד שבא ונמשך מאחדות הפשוטה להיות מהווה כל הוי[ות] שבכל פרט ופרט דע\"ס והוא שם מ\"ה מלגיו הנ\"ל וד\"ל). והנה שם הוי' שכולל כל הפנימי' דכל שם וספי' ע\"כ אומר[ים] הוי' אלקינו הוי' צבאות כו' הוא הנק' בחי' אדם גימט' מ\"ה<sup data-n=\"5341\">115</sup> וזהו שם מ\"ה מלגיו כו', ופי' אדם אדמה לעליון<sup data-n=\"5342\">116</sup> לעצמות המאציל דלאו מכא\"מ איהו<sup data-n=\"5343\">117</sup> כלל כו' ע\"כ ביכולתו להיות בחי' פנימיות ומקור האור להתהוות כל האורות וכלים דאצי' בפרט ובכלל וז\"ש מי כמוכה באלים הוי' כו'.\n[ד] <b>וביאור</b> הדבר הנה יובן ממ\"ש ויקרא האדם שמות לכל הבהמה וחיות<sup data-n=\"5344\">118</sup> כו' וכל אשר יקרא<sup data-n=\"5345\">119</sup> כו', וידוע הטעם ש[ה]אדם דוקא קרא שמות לכל הבהמות והברואים<sup data-n=\"5346\">120</sup> לפי שכל הבהמות כלולים בו והוא כולל [כול]ם יחד שה[מ]דבר כולל בעצמו חי וצומח ודומם וכתיב אחור וקדם צרתני<sup data-n=\"5347\">121</sup> כידוע, וע\"כ ידע האדם בשרש התהוות נפש כל חי משרש מחצבו<sup data-n=\"5348\">122</sup> ובעצם מציאותו ומהותו שלפי אופן שלו בעצם שרש מציאותו צריך שיקראוהו בשם זה דוקא, כמו השור נק'<sup data-n=\"5349\">123</sup> בשם זה שור לפי אופן שרש עצם מציאות התהוותו, וכן ארי' נק' בשם זה ארי' ע\"ש [עצם] מהותו ומציאותו דוקא, וכה\"ג עכ\"נ<sup data-n=\"5350\">124</sup> חי' ועוף למינה<sup data-n=\"5351\">125</sup> כמו נשר נק'<sup data-n=\"5352\">148</sup> ע\"ש מציאותו בעצם אין לו שם אחר רק שם נשר, וכה\"ג כל פרטי הברואים שבחיות ובהמות ועופות קרא האדם שמות לכאו\"א [ו]כל אשר יקרא לו האדם שם הוא<sup data-n=\"5353\">126</sup> שמו פי' זה שמו העצמי, והוא ענין שם העצם הנ\"ל וכן נכלל<sup data-n=\"5354\">127</sup> בזה",[["5333","109","<b>כו'</b>: איאיב: ליתא."],["5334","*110","<b>הת\"ת כו' שכלול מחו\"ג</b>: נסמן לעיל פט, א."],["5335","110","<b>יו\"ד צמצום וה\"א התפשטות</b>: ראה אגה\"ת פ\"ד. לקמן פ' בשלח קנ, א ואילך."],["5336","111","<b>שם מ\"ה מלגיו</b>: נסמן לעיל פ' שמות יג, ד."],["5337","*112","<b>כל האצי'</b>: בת\"ז ובסידור אדה\"ז: אצי'. אבל כ\"ה גם לעיל פ' וארא פו, ד. לקמן פ' בשלח ריג, ג. ריד, א. שה\"א כ, א. תו\"ח נח סד, ג. ח\"ש קכד, א. ויצא קעב, ד. וישלח קפב, סע\"א. ש\"א עא, א. וש\"נ."],["5338","112","<b>וד\"ל) וזהו</b>: איב: וד\"ל (וזהו."],["5339","113","<b>בשמע ישראל</b>: ואתחנן ו, ד."],["5340","114","<b>כו'</b>: יאיב: הוי'."],["5341","115","אדם גימט' מ\"ה. נסמן לעיל ד, ב הערה 186."],["5342","116","<b>אדם אדמה לעליון</b>: נסמן לעיל פ' שמות מו, ב."],["5343","117","<b>איהו</b>: איאיב: ליתא."],["5344","118","<b>ויקרא. . הבהמה וחיות</b>: בראשית ב, כ [ושם: הבהמה. . ולכל חית]. אויב: הבהמות וחיות [ראה מאמרי אדה\"א דברים ח\"ג ע' א'מח]. יא: הבהמה והחי' [ראה מאמרי אדה\"א הנחות תקע\"ז ע' קכח]."],["5345","119","<b>וכל אשר יקרא</b>: בראשית ב, יט."],["5346","120","<b>הבהמות והברואים</b>: איאיב: הברואים."],["5347","121","<b>אחור וקדם צרתני</b>: תהלים קלט, ה."],["5348","122","<b>ידע האדם. . משרש מחצבו</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' של [ובהנסמן במ\"מ לשם]. תקס\"ו ע' רכח. מאמרי אדה\"א במדבר ח\"ג ע' א'ריט."],["5349","123","<b>נק'</b>: יאיב: יקרא."],["5350","124","<b>עכ\"נ</b>: על ( ) עם ( ) כל נפש."],["5351","125","<b>עכ\"נ. . למינה</b>: יאיב: על כל חי מן העוף למינהו."],["5352","148","<b>נק'</b>: יאיב: יקראו לה."],["5353","126","<b>הוא</b>: יאיב: זה."],["5354","127","<b>וכן נכלל</b>: יאיב: ונכלל. או: כבפנים."]]],[2300540304,"ממילא קריאת שם חיצוני במה שנתפס [בו] לקוראו בשם, וכן בחיות ובהמות דמרכבה פני ארי' פני שור ופני נשר שהן מלאכים העליונים <span data-k=\"pg\">280</span> ּ הרוחני' הכל קרא האדם שמות<sup data-n=\"5355\">128</sup> כו', [ו]מאחר שהאדם יכול לקרוא להם שמות דהיינו לתאר עצם מהותם כנ\"ל<sup data-n=\"5356\">129</sup> שהוא עצמו למעלה הרבה מהן וע\"כ כולם נכלל[ים ב]ו וכוללם יחד כו'. והיינו מפני שהוא ממקור ושרש גבוה שמשם יוכל לתאר כ\"א בשמו כו', וע\"כ לאדם עצמו לא מצא שם עד שאמר לו ששמו אדם<sup data-n=\"5357\">130</sup> כי הוא למעלה מבחי' שם, כי אין שם התואר שייך רק לדבר פרטי כמו לחסד ולמטה הוא פני ארי' אל הימין או לפני שור מהשמאל בחי' הדין וכל פרטיהם למיניהם למטה הנסתעף<sup data-n=\"5358\">131</sup> מהם, אבל האדם כולל כולם איך יתואר בדרך [שם] פרט[י], ועכ\"ז קרא שמו אדם ע\"ש צלם האדם העליון שכולל כל הספי' ע\"ד אדמה לעליון שלמעלה מכל ספי' כו', וכמ\"ש ופני אדם לארבעתן<sup data-n=\"5359\">132</sup> והיינו שם מ\"ה מלגיו כו' דממלא כל שמהן כו' וד\"ל [ומ\"ש ויקרא האדם שם אשתו חוה<sup data-n=\"5360\">133</sup> זה הי' אחר חטא עה\"ד שירדה למטה במדריג' והוצרך לקרוא לה שם חו\"ה שהוא מילוי אחוריים דשם מ\"ה<sup data-n=\"5361\">134</sup> כו' אבל קודם החטא קראה בשם אשה כי מאיש לוקחה<sup data-n=\"5362\">135</sup> כו' וד\"ל].\n<b>והנה</b> התורה נק' [ג\"כ] בשם אדם כמ\"ש וזאת תורת האדם<sup data-n=\"5363\">136</sup> ששרשם מבחי'<sup data-n=\"5364\">137</sup> חכמה ומדות כידוע דאורייתא מחכ' נפקת<sup data-n=\"5365\">138</sup> ונתפשטה במדות כמו [טמא] טהור כשר פסול כמ\"ש ולהבדיל בין הטמא ובין הטהור<sup data-n=\"5366\">139</sup> כו'. והמדות שבה בכלל הן חו\"ג שכוללים רמ\"ח מ\"ע ושס\"ה ל\"ת<sup data-n=\"5367\">140</sup>, הרמ\"ח מ\"ע<sup data-n=\"5368\">141</sup> הן בחי' החסד כוללם<sup data-n=\"5369\">142</sup> ושס\"ה ל\"ת הן הגבו'<sup data-n=\"5370\">144</sup> וכלולים באנכי ולא יהי' לך<sup data-n=\"5371\">145</sup>. והענין הוא כידוע שהתורה עיקר ענינה בבחי' המ[די]דה למדוד הדבר איך וכמה כמו בדרך כלל [ב]רמ\"ח מ\"ע אופן המדידה הוא באיכות מעשה המצות שתעשה כך וכך דוקא ולא כך וכך, וזהו איה סופר ואיה שוקל<sup data-n=\"5372\">146</sup> שסופר ומודד את אופן המעשה ושוקל במשקל הנק' מתקלא, וזהו מפני שכל<sup data-n=\"5373\">147</sup> העלאת מ\"ן והמשכת מ\"ד במדה וקצבה לפי אופן כוונת [ו]רצון המאציל בבירורי' דרפ\"ח כו' אשר צריך תיקון, ועל אופן הזה",[["5355","128","<b>בחיות ובהמות דמרכבה. . קרא האדם שמות</b>: יחזקאל א, י. ראה ת\"ז תמ\"ט (פה, ב). תנ\"ז (צא, ב)."],["5356","129","<b>כנ\"ל</b>: ויאיב: צריך לומר."],["5357","130","<b>שאמר לו ששמו אדם</b>: בראשית ה, ב. ראה ב\"ר פי\"ז, ד."],["5358","131","<b>למטה הנסתעף</b>: יאיב: המסתעפים."],["5359","132","<b>ופני אדם לארבעתן</b>: נסמן לעיל כח, א."],["5360","133","<b>ויקרא האדם שם אשתו חוה</b>: בראשית ג, כ."],["5361","134","<b>חו\"ה שהוא מילוי. . מ\"ה</b>: ראה ע\"ח (שער התיקון) ש\"י, פ\"ג. (שער לאה ורחל) של\"ח, פ\"ב. מאמרי אדה\"ז תקס\"ב ח\"א ע' ע ואילך. מאמרי אדה\"א דברים ח\"ב ע' תריט ואילך. לקמן קכד, ד."],["5362","135","<b>אשה כי מאיש לוקחה</b>: בראשית ב, כג."],["5363","136","<b>וזאת תורת האדם</b>: שמואל-ב ז, יט. ראה זהר (רע\"מ) משפטים קיז, ב. צו כט, ב. א: זאת — נסמן לקמן פ' משפטים רפז, ג."],["5364","137","<b>ששרשם מבחי'</b>: יאיב: ושרשה בבחי'."],["5365","138","<b>דאורייתא מחכ' נפקת</b>: נסמן לעיל יא, א."],["5366","139","<b>ולהבדיל בין הטמא ובין הטהור</b>: כ\"ה גם בשאילתות (מצורע) שאילתא פט ובשמיני יא, מז: להבדיל. איאיב: להבדיל."],["5367","140","<b>רמ\"ח מ\"ע ושס\"ה ל\"ת</b>: מכות כג, סע\"ב."],["5368","141","<b>הרמ\"ח מ\"ע. . ה\"ח</b>: נסמן לעיל צו, א."],["5369","142","<b>החסד כוללם</b>: יאיב: ה\"ח הכללים."],["5370","144","<b>הגבו'</b>: יאיב: ה\"ג."],["5371","145","<b>הרמ\"ח. . ושס\"ה. . באנכי ולא יהי' לך</b>: נסמן לעיל פ' שמות יז, ג הערה 722."],["5372","146","<b>איה סופר ואיה </b>[ויאיב: איה. א: כבפנים]<b> שוקל</b>: ישעי' לג, יח."],["5373","147","<b>שכל</b>: יאיב: שצריך להיות."]]],[2300540329,"הוסדו מצות מעשיות שנק' כלים מכלים שונים, וכמו העושה כלי בציור מדוקדק בתוארה ואיכותה לפי הנצרך לתועלת שלה והרי אם [י]חסר בה אף כקש\"י לא נק' שם כלי כלל וזהו במ\"ע ש[הן] נק' רמ\"ח כלים, והן כמו ענין השמות הנ\"ל בענין שם התואר שמתאר לעצם האור כמו שהוא ואם יחסר בתואר שלא כמו שהוא בעצם אינו נק' שם העצם כלל, וכך הוא ענין הכלים דרמ\"ח מ\"ע כי שמות וכלים ענין א' הוא כנ\"ל, ואפי' בענין שם חיצוני שנתפס בו כך הוא, כמו [כ]שיקראו לראובן שמעון או לאל\"ף בי\"ת וכה\"ג<sup data-n=\"5374\">143</sup> כנ\"ל. וזהו איה שוקל במדה בענין הכלים דמ\"ע כו' וכידוע דמצוה בא\"ת ב\"ש<sup data-n=\"5375\">149</sup> הוא שם הוי' [ב]כל מצוה בפרט שיש בהן [מ]בחי' [אור] החסד דשם הוי', וכללות המ\"ע הן ה\"ח [ו]צריך להיות במדה [קצובה] דוקא. וע[ד]\"ז הל\"ת הן [מ]בחי' הגבו' דשם אלקים והן ג\"כ בחי' כלים רבים רק שאינ[ן] בבחי' כלי קבלה, אבל מ\"מ ודאי נק' שמות כמאמר דכל התורה כולה שמותיו<sup data-n=\"5376\">150</sup> של הקב\"ה כנ\"ל, וכמ\"ש זה שמי לעלם<sup data-n=\"5377\">151</sup> ואמרו שהן שס\"ה ל\"ת [ד]שמי עם י\"ה גימט' שס\"ה<sup data-n=\"5378\">152</sup> וזכרי עם ו\"ה רמ\"ח כו', וכן<sup data-n=\"5379\">153</sup> במ\"ע [ובין בל\"ת הכל] בא במדה ושיעור כמו בציצית ל\"ב חוטין ובתפילין ד' בתים והסוכה תהי' כך וכך דוקא אז ישכנו בה המקיפים דא[מא]<sup data-n=\"5380\">154</sup> וכן בתפילין וציצית כו', וכן בגבו' דל\"ת שזהו להעלות ולברר מק\"נ באופן כך וכך דוקא כו'. וזהו <span data-k=\"pg\">קמ</span> ּ ותורה שם בישראל<sup data-n=\"5381\">155</sup> שם שמות וכלים רבים ע\"י ריבוי הדקדוקים דוקא<sup data-n=\"5382\">156</sup> באיכות [אופן] מעשה המצות ובאופן<sup data-n=\"5383\">157</sup> הל\"ת כו', וכדוגמא הנ\"ל בז' שמות שאינן נמחקין שיש ג'<sup data-n=\"5384\">158</sup> מיני שמות וכלים, וכך הוא בשמות דתורה<sup data-n=\"5385\">159</sup> יש פנימיות וחיצוניות ש[הרי] נק' ארחות הוי'<sup data-n=\"5386\">160</sup> ממש [ודרך הוי'<sup data-n=\"5387\">161</sup> ] וכמ\"ש בכל פ' ויאמר<sup data-n=\"5388\">162</sup> ה' אל משה<sup data-n=\"5389\">163</sup> כו' והוא שם [הוי'] שיש בכל מצוה כענין הוי' אלקים הוי' צבאות, וכאשר ישראל מקיימין המצות בפו\"מ למטה הם מקדשין לבחי' שמות העליונים דאצי' וכמ\"ש אשר קדשנו במצותיו<sup data-n=\"5390\">164</sup> שהן רמ\"ח אברים דמלכא<sup data-n=\"5391\">165</sup> כו', והן יחודים עליונים שבאורות וכלים דאל<sup data-n=\"5392\">166</sup> דאצי' שע\"י תומ\"צ שנעשים כלים רבים לגילוי אוא\"ס באצי' ממש דאיהו וחיוהי חד והוא ע\"י המדות דכשר פסול כו' שזה הוא כללות המ\"ע ול\"ת שכלולים בחו\"ג דאצי' ושרשה בח\"ע<sup data-n=\"5393\">167</sup> שהוא פנימיות אור אבא כו' שמשם מקור אור דתומ\"צ כידוע וד\"ל.",[["5374","143","<b>ושס\"ה ל\"ת הן ה\"ג</b>: ראה קו\"א לתניא (להבין מ\"ש בפע\"ח) קנח, ב."],["5375","149","<b>דמצוה בא\"ת ב\"ש</b>: ראה ת\"ז תכ\"ט (עג, א). מאמרי אדה\"א נ\"ך ע' ג. וש\"נ."],["5376","150","<b>דכל התורה כולה שמותיו</b>: נסמן לעיל פ' וארא נח, ג."],["5377","151","<b>זה שמי לעלם</b>: שמות ג, טו."],["5378","152","<b>[ד]שמי עם י\"ה גימט' שס\"ה</b>: בלקו\"ת פקודי ג, ב מציין: בת\"ז בהקדמה ד' ד' סע\"ב וד' ה' ע\"א (וראה בהנסמן במ\"מ לשם). ראה גם מאמרי אדה\"א דברים ח\"ג ע' תתקי. וש\"נ. נ\"ך ס\"ע צג ואילך. וש\"נ ש\"א צד, ב. לקמן קיט, ג. פ' יתרו רנב, א."],["5379","153","<b>וכן</b>: יאיב: ובין."],["5380","154","<b>והסוכה. . המקיפים דא[מא]</b>: ראה ביאוה\"ז אמור פ, ב. סידור שער הסוכות רנט, א ואילך. רס, ב ואילך. תו\"ח נח נז, ג ובהערה 35."],["5381","155","<b>ותורה שם בישראל</b>: תהלים עח, ה."],["5382","156","<b>דוקא</b>: יאיב: ליתא."],["5383","157","<b>המצות ובאופן</b>: יאיב: המ\"ע ואופני."],["5384","158","<b>ג'</b>: יאיב: ב'."],["5385","159","<b>דתורה</b>: יאיב: דתו\"מ."],["5386","160","<b>ארחות הוי'</b>: נסמן לעיל פ' וארא סט, ד."],["5387","161","<b>ודרך הוי'</b>: וירא יח, יט."],["5388","162","<b>וכמ\"ש בכל פ' ויאמר</b>: ראה גם לעיל פ' וארא נט, א הערה 30."],["5389","163","<b>ויאמר ה' אל משה</b>: שמות ד, ד."],["5390","164","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' לא וע' קפו. דרך מצותיך ע' קסח."],["5391","165","<b>רמ\"ח אברים דמלכא</b>: נסמן לעיל פ' שמות מו, ב."],["5392","166","<b>דאל</b>: יאיב: ליתא."],["5393","167","<b>ושרשה בח\"ע</b>: יאיב: ושרשם הוא מח\"ע."]]]]});
